window.OPTIMISERS={"generated":"2026-08-10","count":434,"cats":["design-elevation","ux","performance","workflow","architecture","accessibility","copy","conversion","dx","integrity","privacy","claims","testing","seo","observability"],"labels":{"design-elevation":"design elevation","ux":"UX","performance":"performance","workflow":"workflow","architecture":"architecture","accessibility":"accessibility","copy":"copy","conversion":"conversion","dx":"dev-experience","integrity":"integrity","privacy":"privacy & legal","claims":"claims accuracy","testing":"testing","seo":"SEO & sharing","observability":"observability"},"items":[{"app":"Breadcrumb","category":"workflow","session":"conversation-2026-08-11","source":"seed","title":"Paste-and-go, zero-question agent prompts (self-install, never interrogate)","detail":"An agent prompt that self-installs its CLI silently, streams if the key is present, and carries on quietly if not — never stopping to ask the user.","why":"Interrogation kills the 'automatic' feel. One-time machine setup + paste-and-go everywhere is what made Bug Ledger feel effortless.","how":"Serve the CLI from a public URL so it installs with a single curl; read the key from a small key file (no shell-profile dependency); tell the agent to self-heal silently and NEVER 'stop and ask' when something is missing."},{"app":"Bug Ledger","category":"design-elevation","session":"conversation-2026-08-11","source":"seed","title":"One-shot entrance animations (never re-animate on refresh)","detail":"Put entrance animations on a one-shot class that is stripped after it plays, not on the base element.","why":"Moving or re-inserting a DOM node restarts its CSS animation — so a live board re-fades every poll and 'blinks every second'.","how":".card.enter{animation} then removeClass after ~600ms; and only touch the DOM order when the sorted order actually changed."},{"app":"Bug Ledger","category":"performance","session":"conversation-2026-08-11","source":"seed","title":"In-place DOM updates for live views (diff, don't re-render)","detail":"Update existing nodes field-by-field each poll and animate only what changed, instead of rewriting innerHTML.","why":"Wholesale re-render flickers, drops scroll/focus, and replays animations.","how":"Keep a refs map per card; compare to last state; mutate only changed text/classes; add a transient 'pop' class on the item that just completed."},{"app":"cross-cutting","category":"design-elevation","session":"conversation-2026-08-10","source":"seed","title":"Aurora-glass design language","detail":"Soft near-white canvas + slowly drifting aurora gradient blobs + frosted-glass cards + a single warm accent (coral) + big rounded type.","why":"Reads as premium and high-end, and keeps every app in the portfolio visually coherent.","how":"A fixed, blurred aurora layer of 3–4 radial-gradient blobs with a slow drift keyframe; cards use rgba white + backdrop-filter blur + hairline border + soft shadow."},{"app":"cross-cutting","category":"design-elevation","session":"conversation-2026-08-10","source":"seed","title":"Theme-aware from the first line","detail":"Design light and dark together with CSS variables and prefers-color-scheme, not as an afterthought.","why":"Respects the viewer's system and avoids a jarring bright flash in dark environments.","how":":root design tokens + a single @media (prefers-color-scheme: dark) override block; test both before shipping."},{"app":"Bug Ledger","category":"ux","session":"conversation-2026-08-11","source":"seed","title":"Live progress counter for long tasks (N / total)","detail":"Stream a running 'checked N / total' counter for long agent work so the user sees exactly where it reached.","why":"Transparency and watchability build trust; a silent long task feels stuck.","how":"Carry progress {done,total,label} on the session; update it every step; show it as a big number + a bar on a live board."},{"app":"Bug Ledger","category":"ux","session":"conversation-2026-08-11","source":"seed","title":"Empty states as first-class design","detail":"Design the 'nothing here yet' state beautifully with a clear next action, not a blank page.","why":"First impressions and guidance — most people see the empty state first.","how":"A calm, centered message on the same aurora background, naming the exact command/step that will fill it."},{"app":"Bug Ledger","category":"ux","session":"conversation-2026-08-11","source":"seed","title":"Full date + timestamp on records (not just relative time)","detail":"Show the full date and time to the second on activity and audit entries.","why":"Auditability — 'when exactly did this run?' matters for a record.","how":"Format as 'DD Mon YYYY, HH:MM:SS'; keep relative time only for the currently-live item."},{"app":"Bug Ledger","category":"integrity","session":"conversation-2026-08-11","source":"seed","title":"Server-verified completeness, not self-report","detail":"When an agent claims it checked everything, verify it server-side and show N/N plus the exact items missed.","why":"Proof beats assurance; it stops silent skipping.","how":"Match the agent's reported titles against the catalog on the server; return {matched,total,missed}; loop until complete."},{"app":"Bug Ledger","category":"integrity","session":"conversation-2026-08-11","source":"seed","title":"Append-only records (add, never modify or delete)","detail":"Make the durable record add-only at the database level so agents can contribute but never corrupt or delete.","why":"Safe multi-agent contribution and a trustworthy audit trail.","how":"SQLite BEFORE UPDATE/DELETE triggers that RAISE(ABORT); a documented owner-only escape hatch for pruning."},{"app":"Bug Ledger","category":"dx","session":"conversation-2026-08-11","source":"seed","title":"Never cache a failure","detail":"Only cache a successful, non-empty fetch; caching a transient failure poisons the isolate until redeploy.","why":"One bad checklist fetch once silently returned 0/0 coverage for everyone on that isolate.","how":"Guard the cache assignment on a non-empty result; on failure return a fallback WITHOUT storing it."},{"app":"Breadcrumb","category":"dx","session":"conversation-2026-08-11","source":"seed","title":"Keep source NUL-free","detail":"Never embed a literal NUL (0x00) in source — e.g. as a cache-key delimiter.","why":"It makes grep/file treat the whole file as binary and silently match nothing, so agents wrongly conclude the code is missing.","how":"Use the \\u0000 escape or a printable delimiter; grep -a as a fallback when a file mysteriously matches nothing."},{"app":"cross-cutting","category":"performance","session":"conversation-2026-07-28","source":"seed","title":"Network-first HTML in service workers","detail":"Serve navigations network-first (or bump the cache name every deploy) so shipped fixes aren't masked by a stale cached shell.","why":"Cache-first service workers pin returning users to an old build — a bug that recurred across many apps.","how":"Network-first fetch handler for document requests; version the cache name on each release."},{"app":"cross-cutting","category":"dx","session":"conversation-2026-07-27","source":"seed","title":"Version-stamp assets (?v=) every deploy","detail":"Append a ?v=N stamp to local script/style URLs each deploy so browsers can't serve stale JS/CSS.","why":"Stale-CSS/JS bugs where a fix ships but the browser keeps the old file.","how":"Bump ?v= on every deploy (or hash the asset)."},{"app":"Hallalu Bookings","category":"integrity","session":"conversation-2026-08-10","source":"seed","title":"Grounded AI that never invents","detail":"Constrain the assistant to page/transcript context only, with a local fallback, and forbid fabrication.","why":"Trust — a made-up fact or call detail is worse than 'I don't know'.","how":"System prompt: answer only from provided context, never invent; local FAQ/summary fallback when the model is unavailable."},{"app":"Hallalu CRM","category":"copy","session":"conversation-2026-08-08","source":"seed","title":"Source-verified stats only (ban folklore)","detail":"Only show a statistic you can cite to a primary source; ban unsourced 'best practice' numbers.","why":"Credibility — one bogus stat undermines the whole product.","how":"Keep a small vetted stats bank; no number ships without a citation."},{"app":"Planner Studio","category":"design-elevation","session":"conversation-2026-07-27","source":"seed","title":"Premium inputs & micro-interactions (no native dialogs)","detail":"Replace native prompt()/alert()/confirm() with in-app modals; add smooth press states, hairline borders, subtle fills.","why":"Native browser dialogs look broken and cheap; micro-polish signals quality.","how":"Custom modal/toast components; :active transitions; consistent radius and spacing tokens."},{"app":"cross-cutting","category":"ux","session":"conversation-2026-07-15","source":"seed","title":"Confirm-first for destructive or outward actions","detail":"Deletes, sends, and voice/agent commands confirm before acting.","why":"Prevents irreversible mistakes and builds trust in automation.","how":"A confirm step (or undo window) before any send/delete; never auto-fire outward actions."},{"app":"Hallalu Bookings","category":"design-elevation","session":"conversation-2026-08","source":"mined","title":"Balanced editorial layout — no orphaned whitespace","detail":"Structure a section as a full-width strip + an aligned card grid so rows line up and nothing is left 'stranded' in one column.","why":"'Left over, not placed' whitespace is exactly what reads as unfinished/cheap.","how":"Full-bleed gallery strip (6→3→2 across) then a 2×2 grid (About·Testimonials / FAQ·Policies); a full-bleed strip becomes its own fold."},{"app":"Hopefil","category":"design-elevation","session":"conversation-2026-08","source":"mined","title":"Editorial typography: serif display + tabular numerals","detail":"Serif display headlines, ledger/tabular numerals, caps-tracked labels, intentional whitespace, layered depth (soft shadow + blur), restraint over flash.","why":"This is the consensus 2026 'premium' ingredient list; it reads as considered and expensive.","how":"Serif for headings/commerce, tabular-nums for figures, 2-line clamps on overlays; restraint, not more effects."},{"app":"Hallalu CRM","category":"design-elevation","session":"conversation-2026-08","source":"mined","title":"Glassmorphism with restraint (floating chrome only)","detail":"Use frosted glass selectively — on floating chrome (modals, aha hero), not on every surface.","why":"Glass everywhere muddies legibility and stops reading premium; restraint is the premium signal.","how":"A dedicated .glass class for floating elements; opaque premium cards elsewhere."},{"app":"cross-cutting","category":"design-elevation","session":"conversation-2026-08","source":"mined","title":"Premium SVG icons instead of emoji in chrome","detail":"Replace bright emoji in nav/tools/buttons with a coherent inline-SVG icon set.","why":"Emoji-as-chrome reads amateur; a stroke-consistent icon set reads like a real product.","how":"Inline SVG, ~1.6 stroke, currentColor so icons inherit theme; one consistent set across the app."},{"app":"Hopefil","category":"design-elevation","session":"conversation-2026-08","source":"mined","title":"Real editorial imagery, never stock people","detail":"Bundle a small in-house image library (no people, no text, one soft-light style) and hide any tile whose image fails.","why":"Stock-people photos make apps generic; a broken image is worse than none.","how":"Generate/curate a few consistent images; a broken-image fallback that hides the tile so a 404 never shows."},{"app":"Stitchhooky","category":"design-elevation","session":"conversation-2026-08","source":"mined","title":"Bento hierarchy + gradient washes + real photography","detail":"Compose with a bento grid, gentle gradient washes and genuine subject photography for a high-end look.","why":"This is the '$100k look' — clear hierarchy and real texture instead of flat boxes.","how":"Bento tiles with varied sizes, soft gradient backgrounds, real photos over placeholder blocks."},{"app":"Hallalu CRM","category":"design-elevation","session":"conversation-2026-08","source":"mined","title":"Frosted-glass device bezel for previews","detail":"Frame a live preview in a translucent glass device edge, not a thick black slab.","why":"The black bezel looks like a placeholder; frosted glass looks designed.","how":"Translucent edge + soft highlight/shadow + subtle notch + a 'LIVE PREVIEW' caption."},{"app":"Hopefil","category":"design-elevation","session":"conversation-2026-08","source":"mined","title":"Layout diversity by content type","detail":"Give different content modes genuinely different anatomies, not one template recolored.","why":"Two prompts should produce two visibly different products; sameness reads as a wrapper.","how":"Editorial = quiet grouped rows + stat strip (no hero); imagery-led = photo card grid; commerce = its own."},{"app":"Planner Studio","category":"design-elevation","session":"conversation-2026-08","source":"mined","title":"Shareable summary cards that market the app","detail":"Generate a beautiful downloadable month/year card with kind, encouraging analysis and the app URL in the footer.","why":"It delights the user and markets the app every time it's shared.","how":"Canvas card: colour ribbon, stat tiles, one warm encouraging line, app URL footer."},{"app":"Finished.","category":"design-elevation","session":"conversation-2026-08","source":"mined","title":"Uniform pill pickers (avoid flex:1 ballooning)","detail":"Make a format/segmented picker natural-width uniform pills, not flex:1 chips.","why":"flex:1 makes buttons stretch and the last wrap-row balloon — visibly broken.","how":"Non-stretching pills, uniform height, one icon each, a single accent on the selected one."},{"app":"Stitchhooky","category":"ux","session":"conversation-2026-08","source":"mined","title":"Onboarding: 1–2 fields per screen","detail":"Ask one or two fields per onboarding screen, never a wall of inputs.","why":"The first session is where 70–90% of users are lost; density kills completion.","how":"One question per step; progressive disclosure; the PIN/passcode can double as a later lock code."},{"app":"Hallalu CRM","category":"ux","session":"conversation-2026-08","source":"mined","title":"Endowed-progress onboarding","detail":"Show the user already partway along the onboarding path rather than starting at zero.","why":"Endowed progress lifts completion (34% vs 19%, Nunes & Drèze) and time-to-value under 5 min drives activation.","how":"Pre-fill/first-step-done state; a progress indicator that starts a notch in."},{"app":"Hallalu CRM","category":"ux","session":"conversation-2026-08","source":"mined","title":"Blank start + explorable demo (kept separate)","detail":"New users land in their own empty workspace; a rich demo is a separate, clearly-labelled choice.","why":"Mixing demo data into a real account confuses ownership and pollutes the user's space.","how":"'Start my own' → empty studio; 'Explore a demo' loads seeded data in a distinct mode."},{"app":"Hallalu Bookings","category":"ux","session":"conversation-2026-08","source":"mined","title":"One-tap row actions; confirm routine, danger card destructive","detail":"Each row gets one-tap actions; routine actions show a small confirm, destructive ones a distinct danger card that never auto-runs.","why":"Speed for the common case, a deliberate stop for the irreversible one.","how":"Danger card for cancel/delete with a match picker when several items fit; never auto-execute."},{"app":"Hallalu Bookings","category":"ux","session":"conversation-2026-08","source":"mined","title":"'New since last visit' + repeat-client cues","detail":"Badge items that arrived since the last visit and flag returning clients.","why":"Reviewers explicitly want at-a-glance 'what's new' and client history one tap away.","how":"'New' badges keyed to last-seen timestamp; '2nd visit' chips + one-tap client notes."},{"app":"Hallalu CRM","category":"ux","session":"conversation-2026-08","source":"mined","title":"Honest labor steps instead of spinners","detail":"Show the real named steps of a long operation instead of an opaque spinner.","why":"Itemised 'labour' feels faster and more trustworthy than a mystery spinner.","how":"Render each step as it runs ('reading transcript… drafting… saving'), not a single loader."},{"app":"Hallalu CRM","category":"ux","session":"conversation-2026-08","source":"mined","title":"Auto-update bar — never run a stale build","detail":"Any open tab checks for a newer deploy and offers a one-tap refresh.","why":"Users otherwise sit on an old bundle after you ship a fix.","how":"On focus/interval, compare a build stamp; show a 'Refresh' bar when a newer one is live."},{"app":"Stitchhooky","category":"ux","session":"conversation-2026-08","source":"mined","title":"Cancel symmetry (FTC click-to-cancel)","detail":"Let users cancel in the same sheet where they signed up, effective at period end.","why":"It's the FTC click-to-cancel standard and it builds trust; asymmetric cancellation feels like a trap.","how":"One-tap cancel in the upgrade/billing sheet; confirm effective-at-period-end."},{"app":"Stitchhooky","category":"ux","session":"conversation-2026-08","source":"mined","title":"Streaks with mercy (never shame)","detail":"Reward streaks but never shame a miss.","why":"The 'abstinence-violation effect' makes people rage-quit after one slip.","how":"Forgiving streaks/grace days; encouraging copy on a miss, never punitive."},{"app":"Hallalu Bookings","category":"accessibility","session":"conversation-2026-08","source":"mined","title":"Reduced-motion + aria-labels on icon buttons","detail":"Honor prefers-reduced-motion and label every icon-only button.","why":"Accessibility and polish; motion-sensitive users and screen readers both need it.","how":"@media (prefers-reduced-motion) to cut animation; aria-label on each icon button."},{"app":"Hallalu Bookings","category":"copy","session":"conversation-2026-08","source":"mined","title":"Replace fabricated metrics with honest editable badges","detail":"Never ship invented performance numbers; use honest, editable placeholders.","why":"Fake '0.38s load / top 1% conversion' metrics destroy trust the moment they're noticed.","how":"Editable badge components with truthful defaults; no unverifiable claims baked in."},{"app":"Hopefil","category":"copy","session":"conversation-2026-08","source":"mined","title":"Restraint as the premium signal","detail":"State value with restraint ('plans are simply the better rate') instead of pushy gating.","why":"Understatement itself reads premium; hard-sell reads cheap.","how":"Calm, factual value copy; no dark-pattern nudges or fear-based gating."},{"app":"Finished.","category":"dx","session":"conversation-2026-08","source":"mined","title":"Stage only the files you touched (concurrent-session safety)","detail":"When another session may be editing the same repo, commit file-by-file, only the files you changed.","why":"A blanket 'git add -A' sweeps a parallel agent's in-progress work into your commit.","how":"git add specific paths; verify HEAD/diff before committing when co-editing."},{"app":"Finished.","category":"integrity","session":"conversation-2026-08","source":"mined","title":"Crash-recovery must never wipe user content","detail":"A self-heal/crash-recovery path may purge caches and the service worker, never user data.","why":"A recovery that clears storage can destroy the user's content — a worse failure than the crash.","how":"Scope resets to SW + caches only; keep user data untouched; audit every self-heal path."},{"app":"Hopefil","category":"workflow","session":"conversation-2026-08","source":"mined","title":"Write a world-class mandate + house rules into the repo","detail":"Put the quality bar and build conventions in a repo doc every future feature must meet.","why":"It keeps standards from drifting across sessions and agents.","how":"A BUILD.md standing rule (editable-everything, delete-confirm, glass, timestamps, local-first, both themes, verified in-browser)."},{"app":"cross-cutting","category":"workflow","session":"conversation-2026-08","source":"mined","title":"Deep-research with counter-evidence before design decisions","detail":"Research a design/product decision against sources AND actively seek counter-evidence before committing.","why":"Trend-following without counter-evidence ships generic or wrong choices (e.g. 'is glassmorphism still premium in 2026?').","how":"A short research pass that cites sources and the case against; then decide."},{"app":"Hallalu CRM","category":"architecture","session":"conversation-2026-08","source":"mined","title":"Marketing landing at root, app at /app","detail":"Serve a marketing landing at the root and the app at /app; returning users skip the landing.","why":"New visitors get a pitch; existing users aren't slowed by it.","how":"Root = landing; /app = product; redirect onboarded users straight to /app."},{"app":"Aprizely","category":"design-elevation","session":"conversation-2026-08","source":"mined","title":"Never flatten a signature boot/splash animation","detail":"Keep a signature animated splash (e.g. rainbow aurora) animated — don't 'optimize' it to a static image.","why":"The boot moment is a brand signature; making it static quietly cheapens the whole app.","how":"Preserve the keyframes; respect prefers-reduced-motion instead of removing it."},{"app":"cross-cutting","category":"integrity","session":"research","source":"research-2026-08-11","title":"Re-audit security after every AI iteration","detail":"Run a security pass after each round of AI edits, not just at the end.","why":"Iterative AI generation measurably degrades security — each edit can re-introduce flaws.","how":"A /securitysweep (or quick detector pass) after each significant AI change; treat 'it worked' as separate from 'it's safe'."},{"app":"cross-cutting","category":"integrity","session":"research","source":"research-2026-08-11","title":"Treat all model output as untrusted","detail":"Validate and sanitize anything an LLM returns before rendering, running or forwarding it.","why":"LLM output can carry XSS/SSRF/command payloads (OWASP: improper output handling).","how":"Encode before HTML, allow-list before navigation/exec, schema-validate structured output."},{"app":"cross-cutting","category":"architecture","session":"research","source":"research-2026-08-11","title":"Least-privilege + human-in-the-loop for AI agents","detail":"Give AI features only the tools/permissions they need and require approval for irreversible/outward actions.","why":"Excessive agency is an exploitable attack surface (OWASP LLM).","how":"Scope tokens/tools per task; confirm before send/delete/purchase; log agent actions."},{"app":"cross-cutting","category":"integrity","session":"research","source":"research-2026-08-11","title":"Parameterize everything, escape on output","detail":"Never build queries or markup by string-concatenating input; parameterize queries and encode at the output sink.","why":"The two most common AI-code flaws are missing sanitization and XSS.","how":"Prepared statements for data; an esc() that handles quotes + CSP for HTML."},{"app":"cross-cutting","category":"architecture","title":"OAuth token never touches the browser — server-side exchange + proxied API calls","detail":"For third-party sign-in, the Worker swaps the OAuth code for a token using the client secret, stores it server-side per user, and proxies every API call so the page reads private data without holding a credential","why":"A leaked client-held token exposes the user's private third-party data; server-side + proxy makes leakage structurally impossible","how":"Worker routes /oauth/start and /oauth/callback (secret in env), a tokens table, and /api/<provider>/* proxy endpoints gated by the session cookie; browser only calls your own proxy","session":"1d8-cd3","source":"dailyledger-2026-08-16"},{"app":"cross-cutting","category":"workflow","title":"Device-link key provisioning (no secret pasted into chat/transcript)","detail":"When an agent CLI has no key, it prints a short Approve link; the signed-in user clicks Approve once and the CLI polls, self-provisions its key to a local file, and starts streaming","why":"Pasting a raw key into an agent chat leaves the secret in the transcript; a one-click device link is easier and safer","how":"A device_codes table, a public /link/<code> approval page (401->sign-in-first guard), start/poll endpoints, and a cookie-authed approve; the CLI polls until approved then writes the key locally","session":"1d8-cd3","source":"dailyledger-2026-08-16"},{"app":"cross-cutting","category":"dx","title":"CLIs must fail loudly, never silently no-op","detail":"A served/worklog CLI that silently succeeded on a missing key or unknown verb misled users and agents into thinking work was recorded when nothing happened","why":"Silent success hides breakage and sends agents down wrong paths (rebuilding clients, 'no key' with no guidance)","how":"Exit non-zero with a clear message on missing key/unknown command; point the user to the recovery command (login/connect)","session":"1d8-cd3","source":"dailyledger-2026-08-16"},{"app":"cross-cutting","category":"dx","title":"Scope CLI/tool state per-repo, never a shared global config path","detail":"A worklog CLI wrote per-run state to cwd/.aprizely.json, which collided with the global token file at ~/.aprizely.json when run from home — clobbering the auth token","why":"A shared or ambiguous state path silently overwrites config/tokens and clobbers other projects' runs","how":"Write per-run state to a distinctly-named, cwd-scoped file, refuse to read a worklog file as config, and gitignore it","session":"1d8-cd3","source":"dailyledger-2026-08-16"},{"app":"cross-cutting","category":"dx","title":"Always re-fetch a served CLI each run — 'install only if missing' goes stale","detail":"A prompt that only re-installed the CLI when the file was absent left agents running an outdated cached copy lacking newer commands, so it printed 'No key' forever","why":"Because the CLI is served (not versioned in a clone), any server-side change needs a re-fetch or clients silently run old code","how":"Make the setup step always curl the latest CLI (overwrite), and add an explicit login/connect fallback for parity","session":"1d8-cd3","source":"dailyledger-2026-08-16"},{"app":"cross-cutting","category":"architecture","title":"Defensive per-item rendering so one bad record can't blank a whole view","detail":"A single malformed record (a string where an array was expected) threw and blanked an entire list view","why":"Lists that render items in one unguarded pass are fragile — one corrupt row takes down everything","how":"Wrap/guard each item's render independently so a bad record degrades to a skipped/placeholder entry instead of aborting the list","session":"1d8-cd3","source":"dailyledger-2026-08-16"},{"app":"cross-cutting","category":"dx","title":"Dependency-free client-side CSV + PDF export","detail":"Spreadsheet/table data exported to a real .csv (proper quoting) and a genuine .pdf via a ~90-line dependency-free PDF generator","why":"Reusable export without pulling heavy libraries; keeps bundles small and works offline in the browser","how":"Build the PDF bytes by hand and validate the xref offsets point to real objects so any viewer accepts the file; verify CSV quoting on values with commas/quotes","session":"1d8-cd3","source":"dailyledger-2026-08-16"},{"app":"Aprizely","category":"ux","title":"User-customizable data grid (reorder, resize, persisted, delete-confirm)","detail":"A spreadsheet view where users drag to reorder columns, drag borders to resize, edit cells inline, and delete rows with a confirm — layout persisted per user","why":"Turns a static table into an Airtable/Excel-grade tool people can shape to their own workflow","how":"Layout-driven column model with a colgroup, drag handles on headers, resize handles on borders, width/order saved per-user, native confirm on row delete","session":"1d8-cd3","source":"dailyledger-2026-08-16"},{"app":"Breadcrumb","category":"integrity","title":"Self-healing demo isolation via a fixed demo fingerprint","detail":"Detect demo data that leaked into a real account (known ids/nickname) and reset it to a clean state on load, while keeping the landing demo fully intact","why":"Explorable demos routinely bleed into new accounts; a fingerprint-based auto-heal fixes already-polluted accounts without manual cleanup","how":"On cloudPull, if state matches the demo fingerprint, reset to a fresh blank state; also reset on signup before adopting the account","session":"1d8-cd3","source":"dailyledger-2026-08-16"},{"app":"Breadcrumb","category":"integrity","title":"Honest usage analytics — predict from user snapshots, never scrape or invent","detail":"A usage/credits view with burn-rate and upgrade-runway predictions grounded only in user-logged (or agent-posted) snapshots plus the tier multiplier the plan panel already shows","why":"No API exposes subscription usage, so scraping/guessing would fabricate numbers; logging snapshots keeps analytics truthful","how":"Ingest usage snapshots via a keyed endpoint or manual entry; compute burn-rate/projection from history and base upgrade math only on the known tier multiplier","session":"1d8-cd3","source":"dailyledger-2026-08-16"},{"app":"cross-cutting","category":"copy","title":"Click-to-understand plain-English step notes for agent actions","detail":"Each agent-logged task/step carries a one-line description of what it does, why, and its effect; users tap a step to read it","why":"Non-technical users can follow exactly what an agent is doing without reading code or jargon","how":"CLI accepts Task::description in --tasks and a --desc flag on step/done; the live board, report timeline, and activity items expose an expandable info affordance","session":"1d8-cd3","source":"dailyledger-2026-08-16"},{"app":"Hallalu CRM","category":"conversion","title":"Show-but-lock gated features instead of hiding them","detail":"Premium (Business-tier) rooms stay visible to every user with a lock badge in the nav/menu; clicking opens an upgrade wall rather than the feature","why":"Hidden features can't sell themselves — showing the locked feature lets users see exactly what they'd gain","how":"One BIZ_VIEWS set drives three gates consistently: nav lock badge, mobile-menu lock, and a render-level upgradeWall on the view","session":"215ee275","source":"dailyledger-2026-08-16"},{"app":"Hallalu CRM","category":"integrity","title":"Per-plan AI usage quotas to protect margin","detail":"Monthly AI call quotas metered in D1 per plan (vision counts triple; anonymous capped by IP)","why":"Uncapped AI features can be abused and erode margin; per-plan caps keep high gross margin while staying generous","how":"Mirror the existing TTS quota pattern in the worker; on cap-hit fall back to an on-device result plus a gentle upgrade nudge","session":"215ee275","source":"dailyledger-2026-08-16"},{"app":"Hallalu CRM","category":"ux","title":"In-app device-framed live preview of the real public page","detail":"A booking Overview tab shows the actual public booking page rendered inside a phone/desktop frame (with a device toggle + QR), driven by the real template and the user's current data","why":"Users otherwise never see their public-facing page without publishing and opening it in a new tab","how":"Render the same public template with current state into an iframe/frame; add a device-size toggle and reuse the existing QR helper","session":"215ee275","source":"dailyledger-2026-08-16"},{"app":"Hallalu CRM","category":"design-elevation","title":"Graceful filler imagery that vanishes on real upload","detail":"Cover, portrait, service thumbnails and a photo gallery fall back to tasteful stock images (seeded by the page slug so they stay stable) and adapt to fewer photos than the demo; fully editable","why":"Empty grey image boxes read as broken; stable placeholders keep the preview presentable and disappear the moment the user adds their own","how":"Seed placeholder URLs deterministically from the slug; render placeholders only when the user's own field is empty; make the gallery a real add/remove editor","session":"215ee275","source":"dailyledger-2026-08-16"},{"app":"cross-cutting","category":"dx","title":"Machine-readable reusable-module hub for agents","detail":"A dedicated repo + Worker hosting each dependency-free module in its own folder, indexed by a modules.json (raw file URLs, API, usage, deps) plus /llms.txt and /AGENTS.txt","why":"Lets any coding agent discover and copy a module's full source in two requests, and makes adding a new module one folder + one JSON entry","how":"public/<slug>/ per module; modules.json as the machine index; llms.txt/AGENTS.txt as the agent contract","session":"215ee275","source":"dailyledger-2026-08-16"},{"app":"Aprizely","category":"integrity","title":"Append-only field-change version history (old-new diffs)","detail":"Every change to a project's info is archived append-only and shown as a readable old-to-new diff in an 'Activity & version history' panel, capturing edits from both the UI and the agent API","why":"Gives a tamper-evident audit trail of who changed what and when, with no schema migration and nothing ever modifiable or deletable","how":"Add an archiveEdit() helper that writes the field diff into the existing append-only logs table at both UPDATE sites (source: user vs claude-code); render as a diff log kind","session":"215ee275","source":"dailyledger-2026-08-16"},{"app":"Hello Baby","category":"design-elevation","title":"Heirloom hand-down account (recovery key = ownership transfer)","detail":"The whole account is designed to be handed to the child later as an 18th-birthday keepsake, made literally true because the cloud data is gated only by a portable recovery key","why":"Turns a planner into a keepsake, a genuinely novel emotional moat no ad-funded incumbent offers","how":"Keep all cloud data behind a single transferable recovery key (no email-locked account); surface 'one day, hand them the key' in-app","session":"2d2c2119","source":"dailyledger-2026-08-16"},{"app":"Hello Baby","category":"ux","title":"Loss-sensitive 'quiet pause' path (stop the cheerful nagging)","detail":"A pause control that halts all weekly prompts/countdowns with an optional private note, shows 'the countdown is resting', and replays the note before resuming, plus a 'close this chapter quietly' option","why":"Pregnancy/period apps are widely criticised for firing celebratory notifications after a loss; almost nobody designs the graceful exit","how":"Add a pause state that suppresses time-based prompts, stores an optional user note, and offers a no-fanfare close; keep all data intact","session":"2d2c2119","source":"dailyledger-2026-08-16"},{"app":"Hello Baby","category":"design-elevation","title":"Era-aware app that grows with the user","detail":"One countdown that rolls itself from due-date to 1st/2nd/3rd birthday and re-labels content by era; setup offers 'expecting' vs 'baby already here' vs 'adopting/arrival day'","why":"Extends product lifespan far beyond the ~9-month window competitors churn at, and serves adjacent segments","how":"Drive labels and prompts off a computed life-stage rather than a single fixed mode; branch onboarding into the relevant era","session":"2d2c2119","source":"dailyledger-2026-08-16"},{"app":"Hello Baby","category":"conversion","title":"Time-gated content reveal with an 'unlocks soon' teaser","detail":"Only arrived weeks appear plus one locked teaser card ('unlocks Saturday - in 4 days')","why":"Creates a weekly reason to return and an anticipation loop, rather than dumping all content up front","how":"Compute each entry's unlock date from an anchor; render passed entries, hide future ones, show one next-up locked teaser with countdown","session":"2d2c2119","source":"dailyledger-2026-08-16"},{"app":"Happy Travel","category":"architecture","title":"Server-enforced role-based share links (no accounts)","detail":"Collaboration via copyable editor/viewer/admin links backed by worker share-tokens: viewers rejected server-side (403) on writes, only super-admin can grant admin or revoke, revoked links die instantly","why":"Canva/Docs-style multi-user editing without forcing accounts, with authorization enforced on the server not the client","how":"Mint role-scoped tokens in a Worker/KV; check role server-side on every mutating endpoint; keep recovery key only with owner","session":"2d2c2119","source":"dailyledger-2026-08-16"},{"app":"cross-cutting","category":"design-elevation","title":"Personal photo as full-bleed wallpaper while themes keep the accents","detail":"Users set their own photo as a 100%-cover background with an adjustable readability veil, while the theme still drives buttons/nav/accent colours on top","why":"Deep personalization without sacrificing legibility or the design system","how":"Fixed background-size:cover layer + themed veil slider; per-section override falling back to global photo; run every url() through a scheme-allowlist sanitizer","session":"2d2c2119","source":"dailyledger-2026-08-16"},{"app":"cross-cutting","category":"design-elevation","title":"Self-building storybook timeline from a single anchor date","detail":"A dashed spine that auto-generates dated chapters from one date, weaves the user's own photo-moments in chronologically, and floats a pulsing 'you are here' marker; reused across Ever After, Happy Travel, Hello Baby","why":"Turns flat data into an emotional, anticipatory narrative and is highly reusable","how":"Derive chapter dates from the anchor, mark past entries done and soften future ones, merge user moments by date, add a live position marker","session":"2d2c2119","source":"dailyledger-2026-08-16"},{"app":"Hello Baby","category":"design-elevation","title":"Concentric closeness rings ('atom') for relationship maps","detail":"Places the subject at centre and auto-orbits people onto rings by closeness, with rings fading outward, even spacing per ring, staggered spokes, and a legend","why":"Communicates relationship closeness at a glance far better than a flat grid","how":"Map each role to a ring radius, distribute members evenly with a per-ring angular offset so nobody stacks, dim guide circles with distance","session":"2d2c2119","source":"dailyledger-2026-08-16"},{"app":"cross-cutting","category":"conversion","title":"One-time purchase over subscription for privacy-first products, with giftable unlock codes","detail":"A single ~$29.99 unlock instead of a recurring fee, with Stripe promo codes, account-after-paying, and single-use gift codes so it can be gifted","why":"A recurring charge contradicts a 'no ads, buy once, hand it down' privacy pitch and loses to churn on a short use arc; buy-once matches Etsy expectations and is giftable","how":"Stripe Checkout -> webhook mints a single-use code -> redeem deep-link flips entitlement; lead the listing with 'Buy Once - No Subscription'","session":"2d2c2119","source":"dailyledger-2026-08-16"},{"app":"Hello Baby","category":"integrity","title":"Data portability as verifiable trust proof","detail":"One-tap 'Download everything (JSON)' export of the user's entire dataset","why":"Makes a privacy/no-lock-in promise provable rather than merely claimed","how":"Serialize all local/cloud state to a single downloadable JSON file from Settings","session":"2d2c2119","source":"dailyledger-2026-08-16"},{"app":"cross-cutting","category":"accessibility","title":"iOS-safe input spec: style :not([type]), 16px font, 44px target","detail":"Add input:not([type]) so type-less boxes can't fall through to the default grey control, set 16px font on phones to stop iOS tap-to-zoom, enforce 44px min height per Apple HIG","why":"Type-less inputs silently escaped every input[type=...] rule (a real 'unstyled box' bug), and sub-16px fields trigger auto-zoom on iOS","how":"Include :not([type]) in the input rule set, bump font-size to 16px at mobile widths, apply min-height:44px, scope dense-view overrides explicitly","session":"2d2c2119","source":"dailyledger-2026-08-16"},{"app":"cross-cutting","category":"architecture","title":"Security headers belong in _headers, not the Worker, for static assets","detail":"On Cloudflare, static assets are served directly at the edge and bypass the Worker's fallback handler, so header injection written in the Worker never runs on asset responses.","why":"Teams add CSP/security headers in the Worker, verify one JSON route, and ship — while every actual HTML/asset response still goes out bare.","how":"Put security headers in a public/_headers file (or the assets config); verify with a GET on a real asset URL, not a HEAD on the API.","session":"mine","source":"dailyledger-2026-08-16"},{"app":"cross-cutting","category":"performance","title":"INP is now the most-failed Core Web Vital — break up long tasks","detail":"INP (replacing FID) scores the worst interaction latency; 43% of sites fail the 200ms bar in 2026. Any task >50ms blocks the main thread and delays taps/clicks.","why":"Heavy synchronous render/parse work on interaction makes the UI feel janky and now directly hurts search ranking.","how":"Chunk long JS with await/yield (scheduler.yield or setTimeout), debounce/throttle scroll+resize, use passive listeners, move heavy compute to a Web Worker, avoid forced synchronous layout.","session":"mine","source":"dailyledger-2026-08-16"},{"app":"cross-cutting","category":"accessibility","title":"Six fixes clear 96% of accessibility failures","detail":"Low-contrast text (83.9% of pages), missing alt text (53%), missing form labels (51%), empty links (46%), empty buttons (31%), and missing document lang (14%) account for 96% of detected WCAG errors.","why":"These exclude real users (and drive ADA/EAA lawsuits) yet are all caught by free automated scanners — cheap, high-leverage wins.","how":"Enforce 4.5:1 text contrast (3:1 large), alt on every meaningful image, a <label> for every input, text/aria-label on every link+button, and <html lang> set.","session":"mine","source":"dailyledger-2026-08-16"},{"app":"Budget LevelUp","category":"ux","title":"Write-in custom categories via datalist beat fixed dropdowns","detail":"Replaced fixed <select> category pickers (subscription/asset/debt/bank/card) with <input list=...> datalists — suggestions plus free write-in.","why":"Every user's real-world categories differ; a closed dropdown forces mislabeling into 'Other'.","how":"One reusable datalist helper feeding an <input list>; keep the common suggestions, allow anything typed.","session":"mine","source":"dailyledger-2026-08-16"},{"app":"Budget LevelUp","category":"ux","title":"New users get a light scaffold, not seeded sample data","detail":"Defaults ship as empty category templates (zero sample entries); a landing 'Try the demo' button and ?demo=1 load rich example data, with a one-tap 'Start fresh'.","why":"Seeding fake entries into a real account makes users delete demo data before they can trust their own numbers.","how":"Keep structural scaffolding in defaults; move all example rows into loadExample(); gate demo behind an explicit action.","session":"mine","source":"dailyledger-2026-08-16"},{"app":"cross-cutting","category":"integrity","title":"Idempotency keys on every mutating / retryable endpoint","detail":"Any POST that creates or charges (payments, inserts, sends) must accept a client-supplied idempotency key and no-op on replay, returning the original result.","why":"AI codegen omits idempotency, so a retry, double-tap, or network re-send creates duplicate rows/charges/emails. Edge runtimes and clients retry more than devs expect.","how":"Client generates a UUID per logical action; server stores it (D1 unique index or KV) with the response and returns the stored result on repeat. Combine with a unique DB constraint so even a race can't double-insert.","session":"research","source":"dailyledger-2026-08-16"},{"app":"cross-cutting","category":"dx","title":"Verify AI-suggested dependencies before trusting them","detail":"Treat every package name and API the model emits as unverified until checked against the real registry/docs; pin exact versions and commit a lockfile.","why":"LLMs hallucinate package names (slopsquatting supply-chain risk) and deprecated/imaginary APIs. Auto-installing or calling them causes build breaks or runs an attacker's squatted package.","how":"Before adding a dep: confirm the genuine repo, publisher, and download history; pin x.y.z not ^; keep a lockfile; prefer platform-native bindings (D1/KV/Workers AI). Cross-check unfamiliar SDK calls against current official docs, not the model's memory.","session":"research","source":"dailyledger-2026-08-16"},{"app":"cross-cutting","category":"integrity","title":"Store timestamps as UTC epoch, format only on display","detail":"Persist instants as UTC (epoch ms or ISO-with-Z); convert to local wall-clock strictly at render time. Never parse bare 'YYYY-MM-DD' or call toISOString() on a locally-constructed Date to store it.","why":"new Date('2026-08-16') parses as UTC midnight, and toISOString() on a local Date subtracts the offset — both shift the calendar day by one for anyone west of UTC, and DST transitions move stored times by an hour. A top recurring AI-codegen date bug.","how":"Store Date.now()/UTC; build local dates with explicit y,m,d fields (month is 0-indexed) or a date lib in a fixed zone; format for the user with Intl.DateTimeFormat and the user's tz. Round-trip through UTC only.","session":"research","source":"dailyledger-2026-08-16"},{"app":"cross-cutting","category":"architecture","title":"Split static-asset routing from the SPA fallback (and auto-recover)","detail":"Requests for hashed assets must 404 when missing — never fall through to index.html — and index.html must be served no-cache while assets are immutable-cached.","why":"Serving index.html (200 text/html) for a missing .js chunk turns a routine deploy into a white-screen ChunkLoadError for users with the page already open or a stale service worker.","how":"In the Worker, match asset extensions first and return the asset or a real 404; only unknown non-asset paths get the SPA shell. Set Cache-Control: no-cache on the HTML, immutable long max-age on hashed assets, and add a one-time hard-reload recovery on failed dynamic imports.","session":"research","source":"dailyledger-2026-08-16"},{"app":"cross-cutting","category":"performance","title":"Budget edge-storage access: batch and chunk, never N+1 in a loop","detail":"Treat every D1/KV/R2/fetch call as a metered subrequest with hard caps (100 bound params per D1 statement, per-invocation subrequest limit). Design writes and reads to stay well under them.","why":"AI codegen writes per-row queries and giant multi-row inserts that pass on demo data and then hit 'too many SQL variables' or 'too many subrequests' under real volume — a silent scaling cliff.","how":"Use db.batch([...]) in one transaction; keep (rows x cols) under 100 placeholders per statement and chunk beyond that; replace N+1 loops with a single JOIN or bulk read; cache repeated fetches; push large fan-out to Queues/Workflows.","session":"research","source":"dailyledger-2026-08-16"},{"app":"cross-cutting","category":"conversion","title":"Honest free tier — don't gate the core loop behind a surprise paywall minutes in","detail":"Across thousands of 1-3 star reviews the #1 pattern is 'free that turns into a paywall': the listing leads with free, then locks the thing the user opened the app to do within minutes.","why":"The lowest-rated apps rarely fail on idea — they fail because the way they ask for money doesn't match what users thought they agreed to. Bait-paywalls burn the goodwill you need for retention and reviews.","how":"Let the core loop (log a habit, write an entry, track a stitch, build a budget) work for free indefinitely. Charge for depth/scale/convenience, never for the primary verb. State the free/paid line plainly on the first screen that hints at cost.","session":"research","source":"dailyledger-2026-08-16"},{"app":"cross-cutting","category":"conversion","title":"Deliver first value before asking users to sign up or pay","detail":"Onboarding-abandonment and paywall complaints share a root: apps demand an account (or a card) before the user has felt anything work.","why":"Time-to-value beats commitment-up-front. A user who has already created something real is far likelier to register to save it than one asked to commit to a stranger.","how":"Allow a full first session anonymously with local persistence; prompt to create an account at the moment there's something worth saving ('sign up to keep this'), and defer any paywall until after a genuine aha. Migrate the local work into the new account on signup.","session":"research","source":"dailyledger-2026-08-16"},{"app":"cross-cutting","category":"integrity","title":"Grandfather existing users through price changes; announce increases in advance","detail":"A one-time-purchase-to-subscription switch is the canonical resentment story — the app may still be good, but the change breaks the value calculation for people who already paid, and users rage at prices that quietly climb between renewals.","why":"Silent or retroactive price hikes convert your most loyal, longest-paying users into your loudest detractors.","how":"When you change pricing, grandfather current subscribers at their existing rate (or give a long honored window), announce any increase before it hits with a clear opt-out, and never let a renewal price rise without an explicit heads-up the user can act on.","session":"research","source":"dailyledger-2026-08-16"},{"app":"cross-cutting","category":"ux","title":"Request ratings/reviews only after a genuine win — never at friction points","detail":"Never prompt on first launch, during onboarding, after an error, or in the middle of a paywall. A frustrated user handed a rating prompt gives you the one-star you spend months digging out of.","why":"Review timing determines review score more than product quality does at the margins; asking at a low-goodwill moment manufactures your own bad ratings.","how":"Trigger the ask only after a detectable success moment (streak milestone, project completed, export finished), rate-limit it, and suppress it entirely for N days after any crash, failed payment, or support contact.","session":"research","source":"dailyledger-2026-08-16"},{"app":"cross-cutting","category":"workflow","title":"Per-item reminder scheduling, not one global notification time","detail":"A top request for habit/tracker apps: different habits need different reminder times. Users want the water reminder hourly and the journaling reminder at 9pm — not both on one global schedule.","why":"A single app-wide reminder time makes reminders useless for everything except one habit, so users disable notifications entirely and then churn from forgetting.","how":"Attach an optional schedule to each trackable item (times of day, days of week, frequency), default to sensible per-type suggestions, and let the user mute one item's reminders without silencing the app.","session":"research","source":"dailyledger-2026-08-16"},{"app":"cross-cutting","category":"copy","title":"Humane notifications — no guilt-trip copy, capped frequency, quiet by default","detail":"Notifications have drifted from helpful nudges to emotional manipulation ('We miss you! Keep your streak alive'). Users report coming to hate apps that shame them; capping alerts to roughly 3/day reduced stress in research.","why":"Guilt-based nudges spike short-term opens but drive long-term disengagement and 'this app makes me anxious' reviews — the opposite of intended habit formation.","how":"Write encouraging, blame-free copy (never 'you failed'). Cap total notifications per day, ship granular per-category toggles, default anything non-essential to off, and offer quiet hours. Frame returns as welcome, not owed.","session":"research","source":"dailyledger-2026-08-16"},{"app":"cross-cutting","category":"integrity","title":"Keep sensitive personal data local or E2E-encrypted — no third-party ad/analytics SDKs on it","detail":"Period/pregnancy apps became a privacy scandal: intimate cycle/pregnancy data leaked to ad platforms, and a 2025 jury held a major platform liable for collecting reproductive-health data via in-app trackers. Users mass-deleted trackers and demanded anonymous mode.","why":"For pregnancy, baby, period, finance, and location data, a routine ad/analytics SDK turns your app into a liability that can expose users to real-world harm — and into a headline.","how":"Classify health, reproductive, financial, and precise-location data as sensitive; keep it on-device or end-to-end encrypted; never route it through third-party ad/analytics/attribution SDKs; offer an explicit local-only/anonymous mode; and say plainly in-app what leaves the device.","session":"research","source":"dailyledger-2026-08-16"},{"app":"cross-cutting","category":"integrity","title":"Real 'delete my data' + a graceful-sunset export path","detail":"Users learn that deleting the app does not undo data already collected/shared, and shutdown stories show apps switching off servers with no archive, no restore, no grace period — years of data gone.","why":"A missing real-delete erodes trust the moment a privacy scare hits; a missing sunset plan turns an eventual wind-down into a betrayal. Both are trust primitives, not edge cases.","how":"Provide a one-tap 'delete my account and data' that actually purges server records, backups, and third-party copies, and confirm honestly what it can and can't reach. Separately commit to a sunset policy: advance notice plus a full self-serve export before any shutdown.","session":"research","source":"dailyledger-2026-08-16"},{"app":"cross-cutting","category":"accessibility","title":"Respect system font scaling / Dynamic Type — never cap text size","detail":"Apps that ignore the device's font-size setting force low-vision and older users to pinch-zoom or leave; a large majority of surveyed users say accessibility barriers significantly hurt their mobile experience.","why":"Fixed pixel type and hard-coded heights silently exclude a large share of real users (seniors, low vision, situational strain) and invite ADA-style complaints — while costing nothing to get right.","how":"Size text in rem/relative units tied to the root, let containers grow with content, and test the whole UI at ~200% zoom / largest system font. No pixel-locked font sizes on body copy, and no clipping when text scales up.","session":"research","source":"dailyledger-2026-08-16"},{"app":"cross-cutting","category":"workflow","title":"Smoke-test the core user loop before every deploy","detail":"'An update that broke the core feature' is one of the universal 1-star patterns: the one thing people relied on stopped working and the next release didn't bring it back.","why":"A regression in the primary verb (save an entry, log a habit, check out, count a stitch) churns your most engaged users instantly and floods reviews.","how":"Keep a tiny checklist/automated smoke test of the core loop (sign in, create, edit, save/sync, reload-and-still-there, export) and run it against the built artifact before shipping. Never deploy a build where the core loop is red.","session":"research","source":"dailyledger-2026-08-16"},{"app":"Hallalu Bookings","category":"workflow","title":"No-show protection: deposit or card-on-file with a fair policy","detail":"Let owners require either a partial deposit (deducted from the final bill) or a card-on-file only charged on a late-cancel/no-show, paired with a plain cancellation policy shown before the client confirms.","why":"No-shows are the top revenue leak for appointment businesses; salons/spas using deposits report large drops. Card-on-file is more palatable because clients don't part with money upfront but know there's a consequence.","how":"Per-service toggle (deposit amount or card-hold), surface the policy on the confirm step, and support a gradual rollout (new clients and weekend slots first). Never auto-charge without showing the agreed policy.","session":"research","source":"dailyledger-2026-08-16"},{"app":"Hallalu Bookings","category":"workflow","title":"Automated appointment reminders (24-48h before)","detail":"Send an automatic reminder 24-48 hours ahead with a one-tap confirm/reschedule link, then optionally a shorter same-day nudge.","why":"Automated reminders alone cut no-shows substantially — the highest-leverage, lowest-friction lever a booking tool has.","how":"Schedule reminders on booking creation (email always, SMS/WhatsApp where a number exists), include reschedule and cancel links so a can't-make-it frees the slot, and let the owner edit timing and copy.","session":"research","source":"dailyledger-2026-08-16"},{"app":"Hallalu Bookings","category":"workflow","title":"Buffer time between appointments","detail":"Let owners set a configurable gap (travel, cleanup, notes) before/after each service so the next slot can't be booked back-to-back.","why":"Back-to-back bookings with no breathing room cause cascading lateness and de-facto double-booking complaints; buffers are frequently demanded and absent from lightweight tools.","how":"Per-service before/after buffer minutes, subtracted when computing open slots, enforced in the same server-side availability check that prevents conflicts.","session":"research","source":"dailyledger-2026-08-16"},{"app":"cross-cutting","category":"workflow","title":"Invoice aging + auto-chase + 'viewed' receipts","detail":"Give every invoice a live status (draft/sent/viewed/due/overdue/paid), group outstanding ones into aging buckets, and send polite automatic reminders on a user-controlled schedule.","why":"Most freelancers are owed money at any time and describe chasing as a nightmare; they lack a way to see what's paid, due, or lost in a client's inbox.","how":"Track a viewed timestamp (hosted invoice link open), show an aging dashboard, and let users enable auto-reminders at due-date, +7, +14 days with editable wording.","session":"research","source":"dailyledger-2026-08-16"},{"app":"cross-cutting","category":"integrity","title":"Own-your-data: one-click complete export, no lock-in","detail":"A single always-available 'export everything' producing a complete standard-format archive (JSON + CSVs) of every entity and its history, plus a documented import path back in.","why":"Buyers increasingly test export before committing, and platforms that make leaving painful earn active rage. For a user-first product, trivially portable data is the honest differentiator.","how":"Reuse the full object-graph export (contacts + notes + activity + attachments + finance), keep it free and self-serve, print row counts for verification, and state plainly in-app that users can leave any time.","session":"research","source":"dailyledger-2026-08-16"},{"app":"cross-cutting","category":"integrity","title":"Import/migration reconciliation report","detail":"After any bulk import or migration, show a reconciliation summary — rows in, rows created, duplicates merged, rows skipped — with a downloadable list of every skipped row and the reason.","why":"The defining pain of switching tools is silent loss; a visible count is what lets users trust the move.","how":"Instrument the importer to emit counts and a per-row outcome, render them on a post-import screen, and offer 'download skipped rows'. Recommend keeping source data until counts reconcile.","session":"research","source":"dailyledger-2026-08-16"},{"app":"cross-cutting","category":"ux","title":"Lean core by default, advanced features progressively revealed","detail":"Ship the everyday jobs (add a contact, log a note, book, invoice) front-and-centre and tuck configuration, custom fields, automations and analytics behind an 'advanced' reveal.","why":"Most small businesses use less than half their CRM's features and roughly a third abandon within a year over complexity — 'too complicated' is the #1 SMB churn reason. Simplicity is the retention feature.","how":"Default new accounts to a minimal surface, gate power features behind a clearly labelled toggle/section, and let complexity grow only as the user reaches for it.","session":"research","source":"dailyledger-2026-08-16"},{"app":"Listing Lab Pro","category":"integrity","title":"Prompt Etsy AI-content disclosure before publish","detail":"When a listing uses AI-generated or AI-assisted images/text, surface a reminder to disclose it per Etsy's current policy, and offer ready disclosure wording.","why":"Non-disclosure of AI-generated images is an active Etsy suspension trigger and appeals are frequently rejected — a compliance landmine an optimizer tool should defend against, not walk sellers into.","how":"Detect/flag AI-origin assets in the listing draft, show a non-blocking compliance note with a copy-paste disclosure line, and link the current policy. Keep it advisory and honest — never assert Etsy rules that aren't published.","session":"research","source":"dailyledger-2026-08-16"},{"app":"Listing Lab Pro","category":"conversion","title":"True net-profit-after-fees per listing","detail":"Show the seller what they actually keep: subtract Etsy's stacked fees (listing fee, transaction % on item + shipping + gift wrap, payment processing, and the Offsite Ads fee where it applies) from the sale price, per listing.","why":"Fee rage is a top Etsy complaint because the fees compound invisibly; sellers routinely misjudge margins. A clear net-take number is decision-grade information.","how":"Add a fee-aware profit field to each listing/price suggestion using current rates, flag when a price barely clears fees, note that the Offsite Ads fee only hits attributed sales, and keep rates in one config so they stay current.","session":"research","source":"dailyledger-2026-08-16"},{"app":"cross-cutting","category":"accessibility","title":"Test the whole UI at 200% zoom and the largest system font","detail":"Size text in relative units tied to the root and let containers grow with content, then verify nothing clips or overlaps at 200% zoom and maximum system font size.","why":"Pixel-locked type and fixed heights silently exclude seniors, low-vision and situationally-strained users — a large share of the audience for keepsake, baby, wedding and finance products.","how":"rem/em for type and spacing, min-height instead of height, no overflow:hidden on text containers; add a zoom pass to the pre-ship checklist.","session":"layers","source":"dailyledger-2026-08-16"},{"app":"cross-cutting","category":"claims","title":"Verify, don't claim — every assertion needs a primary source","detail":"Treat any factual statement shown to a user (a statistic, a market claim, a comparison, a compliance assurance) as unpublishable until it is traced to a primary source recorded alongside it.","why":"AI-assisted copy makes confident, plausible, unverified assertions cheap to produce and expensive to retract; a single false 'first/only' claim damages trust more than the claim ever earned.","how":"Keep a claims register mapping each user-facing claim to its source and date; re-check on a schedule; prefer provable framing over superlatives; delete anything you cannot cite.","session":"layers","source":"dailyledger-2026-08-16"},{"app":"cross-cutting","category":"privacy","title":"Classify data sensitivity before choosing where it lives","detail":"Decide up front which fields are sensitive (health, reproductive, financial, precise location, children's data) and let that classification dictate storage, transport and whether any third party may ever see it.","why":"Retrofitting privacy is far harder than designing it, and the categories that cause real-world harm and regulatory action are knowable on day one.","how":"Tag each field at schema-design time; route sensitive classes to local-only or end-to-end-encrypted storage; forbid them in logs, URLs and third-party SDKs by lint rule, not by memory.","session":"layers","source":"dailyledger-2026-08-16"},{"app":"cross-cutting","category":"privacy","title":"Ship deletion and export on the same day as signup","detail":"Build 'download everything' and 'delete everything' as part of the account feature itself, not as a later compliance task.","why":"Both are legal rights and both are trust primitives users increasingly test before committing; adding them late means retrofitting across every table and blob store.","how":"One export endpoint serialising the full object graph including media, and one delete path that purges records, backups and third-party copies — with honest disclosure of anything it cannot reach.","session":"layers","source":"dailyledger-2026-08-16"},{"app":"cross-cutting","category":"testing","title":"A core-loop smoke test is the highest-leverage test you can write","detail":"One scripted pass through the primary verb — sign in, create, edit, save, reload and confirm persistence, export — run against the built artifact before every deploy.","why":"'An update broke the core feature' is one of the universal one-star patterns; users forgive missing features but not regressions in the thing they rely on.","how":"Automate it against the deployed preview rather than a mock, and make a red result block the deploy even when the change looks unrelated.","session":"layers","source":"dailyledger-2026-08-16"},{"app":"cross-cutting","category":"seo","title":"Treat the share card as part of the product, not an afterthought","detail":"Every shareable page gets a title, description and a 1200×630 og:image, verified in a card validator before launch.","why":"Links are the primary distribution channel for a small product; a bare URL in a message or post converts far worse than a rendered preview with a title and image.","how":"Add og:/twitter: tags to the page template so new pages inherit them, generate the image from the page's own design language, and validate after every deploy.","session":"layers","source":"dailyledger-2026-08-16"},{"app":"cross-cutting","category":"observability","title":"Make silent failure impossible by default","detail":"No empty catches, a .catch on every chain, global error and unhandledrejection handlers, and a build stamp attached to every report.","why":"The worst production bugs are the ones that generate no signal — a swallowed error looks identical to working software until a user complains weeks later.","how":"Centralise error handling in one helper that always logs with context and always surfaces a user-visible state; lint against bare catch blocks; correlate every report to a deploy id.","session":"layers","source":"dailyledger-2026-08-16"},{"app":"cross-cutting","category":"observability","title":"Errors need a user-visible state, not just a log line","detail":"Every failure path should render something honest to the user — a retry affordance or a plain explanation — in addition to being reported.","why":"Logging alone leaves the user staring at a spinner or an unchanged screen, which reads as a broken product even when the failure was transient and recoverable.","how":"Pair each catch with both a report and a UI state; prefer 'that didn't save — retry' over a silent revert, and never let a failed write look like a successful one.","session":"layers","source":"dailyledger-2026-08-16"},{"app":"cross-cutting","category":"dx","title":"Track deployed serverless/edge functions in the repo","detail":"Serverless functions (Supabase edge functions, Cloudflare Workers/Pages Functions) that are deployed but not committed to the repo become invisible — an agent or teammate reads the repo, concludes the function is missing, and builds a redundant, contract-mismatched replacement.","why":"A whole live payment/auth backend can be absent from source control; the next person duplicates it or routes around it, adding risk and drift. It cost a real detour on Finished. (a needless Cloudflare create-checkout in front of the working, deployed Supabase one).","how":"Keep a tracked copy of every deployed function under supabase/functions/ or functions/, secrets read from a vault (never in the file), with a header noting it mirrors the live version. Diff repo-vs-deployed as part of review.","session":"a15dff44","source":"dailyledger-2026-08-18"},{"app":"cross-cutting","category":"architecture","title":"Embedded-view pattern: one component, standalone or nested","detail":"A feature that has a full page (its own header + back button) often also wants to appear as a section inside a hub. Add an  prop that hides the component's own chrome so the host provides the back/title, and render the same body in both places.","why":"Avoids a second implementation and keeps behaviour identical; lets a rich view (e.g. Follow-ups) live both as its own screen and as a tab inside another tool (Task Manager) with no double header.","how":"Gate the header/back on !embedded; neutralise the standalone padding/max-width when embedded; pass onBack that returns to the host section. Verify no double header and that deep actions still work.","session":"a15dff44","source":"dailyledger-2026-08-18"},{"app":"Abba","category":"integrity","session":"acedd3e8","source":"daily-read","title":"Strategy Lab: 'survives' is a multi-pillar rule that names the failing pillar, and thin samples show their trials but can never pass","detail":"Replaced a 5-window/16-variant check with 200 Monte-Carlo reshuffles of the strategy's own trades, up to 40 rolling windows, a robustness sweep and a 10-symbol hold. A strategy earns paper trading only if every pillar clears (>=60% Monte-Carlo with positive median, >=55% windows, >=55% robustness plateau, >=half the symbols, positive out-of-sample) and it has >=15 trades; under that it still displays the trials but is flagged THIN and cannot pass.","why":"A single lucky split or a short record can look like an edge; showing the trials makes fragility visible while the hard rule stops a flattering result being promoted, and naming the failing pillar tells the user what to rework.","how":"Compute each pillar as a boolean, verdictPass = all pillars && !thin, build the failure sentence from the failed pillar names, guard below ~5 trades with 'not enough to judge', and validate the maths in a Node harness on real candles before shipping."},{"app":"Abba","category":"ux","session":"acedd3e8","source":"daily-read","title":"Translate every percentage into dollars at $50 / $5,000 / $500,000 and into 'winners out of every 100 trades'","detail":"Hit rate is stated as 'about 22 winners out of every 100 trades' and each return (median, best-5%, worst-5%, whole record, average trade) is shown as +/- dollars for three account sizes with a liquidity caveat at size.","why":"Percentages are abstract; a trader feels what -36% means at $5k, and the same framing keeps expectations honest for small accounts.","how":"One shared helper pctToMoney(pct) over a MONEY_SIZES array plus a signed formatter that never prints '+-'; reuse it in the Lab and the track-record modal."},{"app":"cross-cutting","category":"dx","session":"acedd3e8","source":"daily-read","title":"Prove client logic of a login-gated app with a Node harness of faithful copies run on real public data","detail":"When the authed modal cannot be driven (no credentials, candles endpoint returns 401), copy the pure functions (backtester, Monte-Carlo, scan) into a .mjs harness, feed them real public market data with permissive CORS, then confirm on the live deploy that window.Views.x is a function (the IIFE ran), the console is clean and the new strings exist in the served bundle.","why":"It verifies the maths and the bundle without ever typing a credential, and it catches guard-rule mistakes (a thin-sample rule that blocked the very trials the user wanted) before shipping.","how":"Write the harness against exact copies, print per-pillar results, patch the rule, re-run, then render the real HTML templates from a localhost http.server for visual proof."},{"app":"ABS","category":"integrity","session":"00ae642b","source":"daily-read","title":"Make a product-policy rule executable: verdict stored per product, unknown categories fail closed, and the seed builder must refuse adversarial listings","detail":"The 'no licence needed' promise lives in compliance.js (category rules, claim tripwires such as health claims on apparel or a power bank filed as decor) and is applied identically to seller listings, admin writes and AI-drafted listings; seed/build.mjs screens every SKU and also asserts a set of must-refuse items.","why":"A rule in a PDF gets ignored by the first seller who uploads something else; a gate in code plus must-fail tests keeps the promise true after every change.","how":"Single screenListing(category,title,description,evidence) returning allow/verdict/missing; fail closed on unknown categories; add adversarial fixtures to the seed script and fail the build loudly if one is admitted."},{"app":"ABS","category":"ux","session":"00ae642b","source":"daily-read","title":"Show every applied filter as a removable chip, especially filters applied by voice or the URL","detail":"A voice command navigated to /c/homedecor?max=5000 and the result list was correct, but the sidebar radios showed nothing selected, which reads as a broken filter. Browse now reads filters from URLSearchParams and renders a chip per active filter (query, price, verified, sort) that can be cleared.","why":"A filter that is applied but invisible looks like a bug, and shared links must restore the same view.","how":"Parse q/sort/min/max/verified/rating from location.search on route load, render chips in the results bar, and let each chip clear one param."},{"app":"ABS","category":"integrity","session":"00ae642b","source":"daily-read","title":"Switching a storefront's currency means converting at a verified FX rate with retail rounding and sweeping every default","detail":"Relabelling GBP prices as USD would have silently cut every price about 26%. Rate was verified from two sources (1.3538), prices converted and rounded to .99, and price, compare_at, cost, wholesale tiers, free-shipping threshold, flat shipping, money() default, schema defaults, filter bands, schema.org priceCurrency and the voice parser's currency words were all moved together.","why":"A partial swap leaves the catalogue in one currency and thresholds or defaults in another.","how":"Script the conversion over every price-bearing column, grep for the old symbol/code, then verify with a server-side re-priced checkout in the new currency."},{"app":"cross-cutting","category":"dx","session":"00ae642b","source":"daily-read","title":"The Bash tool rejects commands containing raw control characters: write control-character regexes as \\x00-\\x1f escapes","detail":"Pasting a regex that contained literal control bytes into a heredoc made the command fail validation ('control characters that would be hidden in the approval dialog'), and the Write tool silently dropped them from the file.","why":"Retries wasted several turns and the written file was missing the character class.","how":"Write /[\\x00-\\x1f\\x7f]/ with backslash escapes via Write or a python chr(92) build, then node --check the file."},{"app":"cross-cutting","category":"workflow","session":"d9735d28","source":"daily-read","title":"Verify a Vite + Pages deploy by hash parity with a local build, not by grepping for a marker in one chunk","detail":"A marker grep for a new localStorage key found nothing in main-*.js and the lazy index-*.js chunks even though the commit had deployed; the code lived in styles-*.js. Running npm run build and comparing the content-hashed bundle names (main-CiaiF9mp.js, styles-BkZer-k7.js) with the live HTML proved the live build was byte-identical.","why":"Chunk names are misleading and a negative grep can trigger a false 'not deployed' panic or an unnecessary redeploy.","how":"Build locally, compare ls dist/assets with the asset paths in the live index.html, then spot-check strings across all referenced chunks with grep -F."},{"app":"Finished.","category":"ux","session":"d9735d28","source":"daily-read","title":"Seed profile-dependent UI synchronously from a last-known localStorage copy, and clear it on sign-out","detail":"The home 'Your story' ring flashed the default silhouette on every load because the own profile came from an async Supabase call with only a 30 s in-memory cache. The profile is now persisted under finished.me, read synchronously to seed state, never blanked if the refresh returns null, and removed in signOut().","why":"Removes the placeholder flash while preventing the next account on a shared device from inheriting the previous avatar.","how":"cachedProfile() getter + setItem after each successful getProfile + removeItem in signOut; initialise useState from the cache and guard the refresh with a null check."},{"app":"Coco Modules","category":"workflow","session":"d9735d28","source":"daily-read","title":"Before porting a feature into the module registry, check the registry, untracked dirs and git log for a sibling session building the same thing","detail":"Two sessions ported overlapping modules the same day (to-do-list vs todo-list, day-planner vs routine-timetable, plus goals/goal-celebrate) and only discovered it from git status noise; the registry reached 20 entries with near-identical names.","why":"Duplicate work and confusing near-identical slugs force the owner to reconcile later.","how":"Run git status/log and list public/ and modules.json first, pick a distinct purpose and name, and write the intended slug into the board before building."},{"app":"Hallalu CRM","category":"copy","session":"8a626956","source":"daily-read","title":"Check every pricing bullet's verb against what the feature itself disclaims before it ships","detail":"A legal read of new tier bullets found one real exposure ('prove the ROI' vs the feature's 'direction not a perfect number'), two bullets that are only safe because an in-app caveat exists (photo-proof IP caveat and logo stripping; valuation shown as a range), and old absolutes ('no caps on anything', '$80-90/mo of separate tools') that need fair-use wording or a named basket on file.","why":"Marketing absolutes create substantiation risk even when the product is honest.","how":"For each bullet list the in-product caveat, replace absolute verbs (prove, guarantee, unlimited) with measurable ones (track, see the payback), and keep the caveat visible where the feature is used."},{"app":"cross-cutting","category":"dx","session":"d9735d28","source":"daily-read","title":"Blank screenshots and 30 s tool timeouts mean the Browser pane is hidden or the tab is not fronted, not that the page is broken","detail":"Repeatedly the DOM and console were healthy while screenshots came back blank or timed out ('pane is not displayed', 'tab is not fronted'). Calling tabs_context and tabs_select on the tab restored painting; when the compositor stayed wedged, read_page, javascript_tool, console and curl proved the same facts.","why":"It stops a false 'the app is broken' conclusion and avoids hacks like forcing .reveal elements visible.","how":"Check tabs_context for 'hidden/not fronted', tabs_select the tab, retry once; otherwise verify through DOM/JS/console/network and state that visual proof was not possible."},{"app":"cross-cutting","category":"workflow","session":"b3ad12bd","source":"daily-read","title":"Primary-source fetch ladder when WebFetch is blocked: Browser pane text, curl + pypdf for regulator PDFs, and record the rest as unverified","detail":"A regulatory study hit domain-verification errors, 403s and bot checks on FinCEN, a law-journal article and a central-bank PDF. Reading them via the Browser pane get_page_text, downloading PDFs with curl -A and extracting with pypdf (pdftotext was absent) worked, while Reloadly's KYB list, Trustpilot and a World Bank page stayed unverifiable and were labelled as such.","why":"Reports stay source-verified without guessing around blocked pages.","how":"Try WebFetch, then navigate + get_page_text, then curl -A 'Mozilla/5.0' + pypdf, tag FACT/SIGNAL/HYPOTHESIS, and list unverified items explicitly."},{"app":"cross-cutting","category":"dx","session":"88a3d192","source":"daily-read","title":"Serialise iOS and macOS xcodebuild runs: parallel builds in one build directory collide","detail":"Launching the iPhone and Mac builds at the same time in native/build produced a build collision; chaining them one after the other and auto-committing on green worked and let the session continue.","why":"A collided build wastes minutes and can leave a half-written product.","how":"Run 'xcodebuild ... iphonesimulator && xcodebuild ... macosx && git commit' in one background chain and poll the output file instead of sleeping."},{"app":"cross-cutting","category":"dx","session":"53e17fe3","source":"daily-read","title":"Scanner detector for shadowed globals: duplicate window.X assignments and duplicate switch case labels across script files","detail":"Add a shadowing family to the Bug Ledger scanner: (a) the same window.<name> = assigned in more than one script listed in index.html, reported in load order so the later wins is explicit; (b) duplicate case '<act>' labels inside one switch; (c) typeof X==='function' call sites where X has no definition anywhere.","why":"Three Hallalu incidents (clientMeetingsCard defined in app.js and projects.js, a second case 'mark-sent', two onboarding flows) all passed node --check and rendered nothing wrong until a feature silently did not appear. The agent even believed clientMeetingsCard was undefined because its grep stopped at app.js and views.js.","how":"Parse the script order from index.html, collect definitions per file with a regex, flag name collisions and orphan hooks; run it in scan.mjs --catalog and in the /finish checklist before any new window.* function is added."},{"app":"cross-cutting","category":"workflow","session":"5a0287de","source":"daily-read","title":"Before building from a long prompt in a shared repo, diff against what other sessions just shipped","detail":"Two sessions worked the same Hallalu repo within hours: one built the client-page Meetings widget (projects.js) and the mark-sent handler while another, answering a prompt that asked for the same thing, built a duplicate that was overridden at load time. A third check found the repo had moved eight commits (v263 to v271) while a session was paused.","why":"Duplicate builds waste a wave and leave dead code that looks verified in source but never runs.","how":"At the start of every wave run git fetch plus git log --since=3.days --stat -- public/, grep the repo for each function and action name about to be added, and re-sync again before shipping."},{"app":"Hallalu CRM","category":"conversion","session":"53e17fe3","source":"daily-read","title":"Give free-tier users a real AI recap and Ava through Workers AI instead of a hard paywall","detail":"Ava's askAI() returned {error:'plan'} when needAI failed, and recaps fell to a verbatim on-device summary. A cheap flag now routes free users to @cf/meta/llama-3.3-70b-instruct-fp8-fast while Claude Haiku stays the premium voice, and Workers AI is the universal backup if the paid provider fails.","why":"The recap is the product's best moment; showing a raw transcript there is the worst first impression, and Workers AI costs only Neurons.","how":"aiText({cheap:true}) tries Workers AI first; the client always sends provider and cheap; the UI upsells 'sharper writing with Claude' rather than blocking the feature."},{"app":"cross-cutting","category":"dx","session":"53323280","source":"daily-read","title":"House shell helper for macOS: perl-alarm timeout plus a fresh Chrome profile per headless run","detail":"macOS has no timeout command; three sessions hit it (Evertrue remote probe, Finished contact sheet, PostPlan slide export). The working helper is t(){ perl -e 'alarm shift; exec @ARGV' \"$@\"; } combined with a mktemp --user-data-dir for every headless Chrome call.","why":"Without a hard limit a wedged render or a hung wrangler dev --remote probe consumes the 120s to 600s tool budget and gets moved to the background silently.","how":"Put the helper and the per-run profile pattern in the sell and kindly skill snippets and in compose.mjs and shoot.mjs; always wrap network probes and Chrome launches."},{"app":"Pixelbake","category":"dx","session":"53e17fe3","source":"daily-read","title":"pxb gen: retry transient flux-2-dev 502s and report per-job status in parallel runs","detail":"Two of five parallel flux-2-dev bakes returned 502 'FLUX.2 dev could not bake that'. A shell pool using & printed 'done' while two files were missing, and manual retries ran past 300 seconds and were pushed to the background.","why":"Silent partial batches cost credits and let a missing portrait ship unnoticed.","how":"Add --retry N with backoff, a non-zero exit code on failure, and a pxb batch file.json --parallel 2 mode that prints id, status and cost per item; the CLI should also verify the output file exists and is not blank."},{"app":"Pixelbake","category":"ux","session":"2cf03367","source":"daily-read","title":"Marketing-from-URL: say so when the page is an empty JavaScript shell before drafting the brief","detail":"On a client-rendered site the drafter saw about 1.8 KB of HTML and guessed grey colours and a corporate audience; the brand was corrected by hand through the briefs API before any credits were spent.","why":"A wrong brief makes every concept off-brand and the user only finds out after paying for the bake.","how":"If extracted text or product count is below a threshold, render the page in a browser fetch or show a banner 'I only saw N characters - check palette and audience' and require brief confirmation before the first paid bake."},{"app":"Pixelbake","category":"integrity","session":"2cf03367","source":"daily-read","title":"paint-a-fix should show a before/after diff and warn when the masked region barely changed","detail":"An sd15-inpaint fix on a third hand returned a success line and cost one credit, but the extra hand was still there; a flux-2-dev re-bake fixed the pose.","why":"A fix that silently does nothing wastes credits and leaves a visible AI artefact in a shipped creative.","how":"Compare pixels inside the rectangle before and after, warn below a change threshold, and offer a remove-object mode using a klein edit with the original as reference."},{"app":"Pixelbake","category":"design-elevation","session":"53e17fe3","source":"daily-read","title":"Portrait preset for realistic people: flux-2-dev, clean seamless backdrop and an equipment negative list","detail":"flux-1-schnell portraits read as hand-drawn; flux-2-dev gave the realism, but backdrops showed light stands and the top edge of the paper. The recipe that worked: 'clean seamless soft neutral grey studio background, evenly lit, absolutely no photography equipment' plus a negative list (light stand, softbox, tripod, backdrop edge, backdrop seam, plastic skin), then a fault check of every PNG.","why":"The user rejected the first sets as not looking like true professional photos; a baked-in preset avoids repeating the rework.","how":"Ship it as a pxb preset (portrait-pro) with the negative list prefilled, flux-2-dev as default and a post-bake checklist (hands, props, equipment, edges)."},{"app":"Aprizely","category":"integrity","session":"5a0287de","source":"daily-read","title":"Reports are append-only, so republishing creates a new id and the already-shared link keeps saying 'Not shipped yet'","detail":"Republishing the report with a ship block (committed, deployed, version) produced a second report; the first, which the user had opened, still showed the stale status.","why":"The link the user holds is the one they trust; a stale 'not shipped' chip undermines the evidence.","how":"Add apz report --supersede <id> that stamps the old report with 'superseded by <new id>' (append-only note, no edit), or publish the report once after ship."},{"app":"Aprizely","category":"dx","session":"fbb12fd5","source":"daily-read","title":"Write the board state file outside the repo: .aprizely.worklog.json keeps getting committed and pushed","detail":"The per-project board file lives in the working directory. It was swept into a SkillSea commit, pushed to a brand-new private GitHub repo for Evertrue after a manual check that it held no token, and shows as modified in Hallalu after every board update.","why":"It is machine state that dirties every git status, can leak titles to GitHub and collides when two sessions use the same folder.","how":"Store it under ~/.aprizely/sessions/<hash of cwd>.json, or have apz start append it to .git/info/exclude."},{"app":"cross-cutting","category":"dx","session":"fbb12fd5","source":"daily-read","title":"Give icon containers a default SVG size so an unsized inline SVG can never fill its column","detail":"The most repeated UI bug across apps: Abba's heart inside a modal heading, Evertrue icons inside .kicker and then inside label (two separate rules needed in one session), Pixelbake's robot icon in a definition list and the album picker, and Hallalu chart SVGs. Note that Hallalu's own global svg:not([width]) default shrank unsized chart SVGs to 16x16, so a blanket rule has a cost.","why":"An unsized SVG expands to its container width and buries the real content, and it is invisible to node --check and unit tests.","how":"Scope a default (width and height 1.1em) to icon contexts such as .kicker svg, label svg, h2 svg and dd svg, give charts explicit viewBox with width:100%, and add a scanner check for icon strings injected into elements without a size rule."},{"app":"Abba","category":"ux","session":"edbebc02","source":"daily-read","title":"Always-on plain-English explainer for every backtest and scan result, computed from the user's own numbers","detail":"The strategy bot showed jargon (out-of-sample, PF, max DD) and only a demo-only walkthrough. A computed panel now says, for example, that $10,000 became $16,257 (+62.57%) but buy-and-hold made +92.15%, that out-of-sample profit is the real test, and what to do next, with a one-line gloss on every term plus an Ask Ava to go deeper button using Cloudflare AI; the whole-watchlist opportunity scan and the explainer were ported to native in tandem.","why":"A beginner needs to know what a result means and what is only luck (22 variants tried, small sample) without leaving the screen.","how":"Generate the explanation from the metrics with templates and real-world analogies (no model call needed), keep an LLM deep-dive optional, and test both web and native from the same wording table."},{"app":"Hallalu CRM","category":"copy","session":"53e17fe3","source":"daily-read","title":"State the real limit when a laptop starts a phone call: web pages cannot hear a Continuity call","detail":"Start call now fires a tel: link (rings through the paired iPhone on a Mac), but no browser can tap the audio of a Continuity or phone call; Hallalu transcribes through the laptop microphone, so putting the call on speaker is the only way both sides are heard.","why":"The user said 'if it can't work with recording and transcript, don't'; claiming a transcript that cannot exist would be an invented capability.","how":"Keep the dial action, show a one-line speaker tip beside the recorder, and state the limit in the help text."},{"app":"cross-cutting","category":"workflow","session":"53e17fe3","source":"daily-read","title":"Trace each prompt clause to evidence and name ambiguous clauses before building","detail":"'Link multiple clients to the same company' was built as multiple contacts and a main number inside one record, an audit then reported 'every request is implemented', and only a closer read exposed that grouping separate lead records under one company (companies.js) was missing. The same session wrote 'board finished' next to an open question.","why":"An ambiguous clause interpreted narrowly produces a finished-looking board with a real gap, and the user loses trust in the word done.","how":"Restate each ambiguous clause with the chosen interpretation (or build the broader reading), keep a clause table with file:line and an Open column, and lead the final message with an explicit Done versus Still-open split."},{"app":"SkillSea","category":"workflow","session":"f7c55a3d","source":"daily-read","title":"Catalog drifts from the skills it lists: edits need a manual node scan.mjs and wrangler deploy","detail":"Changing the /finish skill description only reached skillsea.coconvo.workers.dev after running the additive scan (which also picked up a new patentscan skill) and a deploy; the repo has no git remote, so the commit could not be pushed.","why":"A catalog that lags the skills undermines it as the single place to see what exists.","how":"Run the scan from a post-edit hook or a scheduled task, deploy only when the diff is non-empty, and give the repo a private remote."},{"app":"Evertrue","category":"ux","session":"fbb12fd5","source":"daily-read","title":"One goal system, three plain-English homes: daily goal leads Home, monthly goal on Money, challenge copy in words","detail":"Goal meant a Studio listing challenge, a Routine item, a dashboard profit goal and a Money goal. The new layout leads Home with Today's goal (progress and an I hit it confirm, modelled on Hallalu), puts a monthly-goal card with profit, revenue and orders on Money, links Money and Budget both ways, renames Routine to To Do Checklist, and rewrites the Studio modal to 'New listings to publish in October 2026'.","why":"The user could not tell what to type into the goal and challenge fields, and a goal they set did not appear where they looked.","how":"Name the three horizons once (today, month, challenge), show each in one place, and make every goal field state its unit and month in words."},{"app":"cross-cutting","category":"architecture","session":"53e17fe3","source":"daily-read","title":"Reusable theme modules need an explicit token map and escape-hatch tokens","detail":"abba-backgrounds uses --txt, --dim and --bg2 while Hallalu uses --ink, --ink-2 and --bg-soft, so a THEME_MAP had to be written; the sidebar background was a hard-coded gradient so a --side-bg token with a fallback was needed; and the ThemeStudio preset click kept fine-tune overrides (patched in the module and redeployed).","why":"Each consumer re-solves the mapping, and presets that do not reset overrides never give the user the full preset.","how":"Ship maps/<vocabulary>.json with the module, document that every themed surface reads var(--x, fallback), make presets reset overrides, and expose --side-bg and --side-ink as standard parts."},{"app":"cross-cutting","category":"conversion","session":"085fe7cc","source":"daily-read","title":"For developer-tool marketing weight sets toward real product screens and disclose AI photos","detail":"Evidence gathered for the Aprizely creative run said builders trust real product screens more than AI-generated faces, so the 14-piece set was weighted toward real screens, composed with a real-product-screen layout, and AI photos carry an on-image disclosure line ('AI-generated photo - real product').","why":"Trust in AI-generated imagery is mixed and an undisclosed AI face risks the credibility the product is selling.","how":"In the sell playbook add a real-screen ratio per set, a disclosure line on any AI photo, and a QA item that checks the disclosure is legible at feed size."},{"app":"cross-cutting","category":"dx","session":"2d2c2119","source":"daily-read","title":"Syntax-gate every deploy: node --check all edited JS, and again after any killed or partial agent run","detail":"A dashboard edit left a duplicated half-open if(photo){ block in wed.js, producing 'Unexpected end of input' at line 367 that would have blanked the whole wedding app; node --check found it before deploy. In a later session node --check over ~30 files edited by agents killed mid-run proved no partial edit shipped.","why":"A single unbalanced brace in a no-build vanilla-JS app takes down every view, and agents killed by a rate limit can stop mid-file. Naive brace counters give false positives; the parser does not.","how":"Before wrangler deploy run `node --check` on each changed .js/.mjs file (git diff --name-only | grep '\\.m\\?js$'), fail the deploy on any error, and re-run it after any interrupted multi-file edit."},{"app":"cross-cutting","category":"workflow","session":"ff83cc6a","source":"daily-read","title":"Recover from agents killed mid-edit by a rate limit: diff stats, syntax check, whitelist-grep of added lines, census against the expected list","detail":"Eight parallel fix agents (several delegating to sub-agents that never notify) were killed by the session limit; result files and the scratchpad were lost, yet ~30 repos held real edits. Recovery: git diff --shortstat per repo, node --check every edited JS file, grep the added lines for anything that is not aria/for/alt/og/meta/focus, review each flagged diff by hand, and rebuild the report from git.","why":"Killed agents can leave half-written files and lost bookkeeping; trusting 'it probably finished' ships broken code. A census against the expected app list also caught an app (PlannerStudio) that no agent had been assigned.","how":"Keep parallel agents at four or fewer, forbid sub-delegation in the prompt, write each result to a file as it finishes, and after any interruption run the diff-stat plus syntax plus added-line-whitelist audit before committing or deploying."},{"app":"Pixelbake","category":"workflow","session":"34d39eb1","source":"daily-read","title":"Preview a creative set on the 3-credit FLUX.2 klein-4b model and re-bake only approved frames on the 63-credit dev model","detail":"With the accounts at 36 and 21 credits, a full dev re-bake of seven photos (~441 credits) was unaffordable and one dev square needed 42 credits. A full set 2 was composed and QA'd on klein-4b previews at 3 credits each, with the dev re-bake stated as one re-runnable command.","why":"Layout, copy and safe-zone defects are found at composition time and do not depend on the model; spending dev credits before QA wastes them, and a mid-batch 402 leaves a set half-baked.","how":"Check pxb whoami balance against the batch total first, bake previews on klein-4b with --ref for character consistency, run the composer QA passes, then re-bake only the approved frames on flux-2-dev, budgeting one extra bake per set for 3046 timeouts."},{"app":"Pixelbake","category":"performance","session":"7b29bece","source":"daily-read","title":"A/B one motif on klein-9b vs FLUX.2 dev before baking a large abstract set: klein-9b matched the look at ~1.7s and 16 credits","detail":"For 34 dark, textless glass-sculpture hero images, klein-9b matched FLUX.2 dev's premium look at 1.7s and 16 credits each versus ~4 minutes and timeout risk for dev; the whole set cost about 544 credits and was fault-checked at full size.","why":"Dev is needed for photoreal people but not for abstract renders; picking the model per image class saves minutes per image and avoids 3046 timeouts.","how":"Bake the same motif on both models, read both at full size, choose the cheaper that matches the house look, then run pxb with a shared STYLE suffix and a per-topic accent tint, followed by a full-size fault check of every PNG."},{"app":"Abba","category":"dx","session":"8a349be2","source":"daily-read","title":"Verify a native app against a local wrangler dev API with DEBUG-only env overrides instead of touching production","detail":"API.swift reads ABBA_BASE and ABBA_TOKEN under #if DEBUG; wrangler dev --local on :8787 with all migrations applied via d1 execute --local and a throwaway account registered by curl; the simulator is launched with SIMCTL_CHILD_ABBA_BASE/ABBA_TOKEN; the Mac app must be exec'd as build/Debug/Abba.app/Contents/MacOS/Abba because `open` drops environment variables.","why":"Proves write paths (timer, edit, upload) on iPhone and Mac without polluting the live D1, and mediaURL and other builders must follow the same base or screenshots break.","how":"Add the #if DEBUG override, route every URL builder through base, start the local worker, seed an account, launch with the SIMCTL_CHILD_ prefix, rebuild each target after the patch (a stale Mac binary ignored the override), and screenshot each screen."},{"app":"cross-cutting","category":"dx","session":"8a349be2","source":"daily-read","title":"Count-asserting patch helper for scripted multi-file edits: every find string must occur exactly the expected number of times","detail":"A tiny patch.mjs (find/repl/count per file, exits non-zero on 0 or more than expected matches, prints a tick per file) was used for all JS and Swift edits in a 23-file wave, and a syntax check followed each batch.","why":"String.replace silently no-ops when the anchor drifted, producing the classic 'only the call-site swap landed' half-edit that passes review and breaks at runtime.","how":"Write patch(file, [[find, repl, expectedCount]]) that reads the file, counts split(find).length-1, aborts the whole run on mismatch, otherwise writes; call it from heredoc JSON, then node --check or xcodebuild."},{"app":"Aprizely","category":"ux","session":"ff83cc6a","source":"daily-read","title":"State-aware, adaptive time on live boards and reports: done shows actual, active shows actual plus ~left, pending shows ~estimate","detail":"Each wave chip shows only what matters for its state; remaining time is the mean of completed tasks with the in-progress task counted down; the active wave tints amber 'running over' beyond 1.25x its estimate; finished waves collapse to one line on runs over 8 tasks; the published report groups its timeline by wave with real per-task time and ends with a pace line (slowest and fastest wave).","why":"Showing estimate and actual on every chip was cluttered and untrustworthy beside tiny real times; users want to know what is happening and when it ends, and a closing pace line makes the report teach something.","how":"Stamp per-task startedAt/doneAt server-side, compute per-wave state client-side, use the completed-task mean as the ETA with a token override, freeze the clock when idle over 3 minutes, and reuse the same helpers in the report timeline."},{"app":"cross-cutting","category":"workflow","session":"2d2c2119","source":"daily-read","title":"Strip commit attribution trailers across repos safely on macOS: portable awk --msg-filter, self-test, verify on the branch, drop refs/original, force-push","detail":"Write the filter as a script (grep -v the trailer, then awk to trim trailing blank lines; BSD sed multi-line forms fail with 'unexpected EOF (pending }'s)), pipe a sample message through it first, run filter-branch from each repo's top level, check `git log main --grep` rather than --all, delete refs/original, reflog expire plus gc, then push --force and confirm origin/main trailer count and commit counts.","why":"Four traps (BSD sed, wrong working directory with swallowed stderr, backup refs inflating counts, force-with-lease 'stale info') each looked like success or a random failure.","how":"Use `FILTER_BRANCH_SQUELCH_WARNING=1 git filter-branch -f --msg-filter 'bash filter.sh' -- --all` from `git rev-parse --show-toplevel`, then `git for-each-ref refs/original | update-ref -d`, `git reflog expire --expire=now --all && git gc --prune=now`, `git push --force origin main`, and verify with git rev-list --count origin/main."},{"app":"cross-cutting","category":"workflow","session":"ff83cc6a","source":"daily-read","title":"Portfolio deploy-sweep recipe: inventory dirs x git x workers_list, secret-guarded commit, npx --yes wrangler deploy, status check where 401 means auth gate","detail":"List every dir with .git or a wrangler config with dirty count, branch, remote and ahead count, cross-reference the live Workers list to find orphans, commit with a secret-file guard and git reset of board-state files (.aprizely.worklog.json, .wrangler), push, deploy each app with npx --yes wrangler deploy capturing URL and Version ID, then curl every worker root (200 expected, 401 for PIN-gated apps).","why":"'Make every app latest' otherwise silently skips apps with no remote or no source and sweeps board-state noise and secrets into commits.","how":"Run the inventory in zsh with arrays (apps=(a b c), not a space-separated string), use absolute $HOME paths, capture the first 'Current Version ID' per app, and report the orphan list (no git, no remote, no local source) separately."},{"app":"cross-cutting","category":"dx","session":"7b29bece","source":"daily-read","title":"When the Browser pane is hidden, verify with DOM metrics (counts, naturalWidth) instead of scroll and screenshot calls that time out","detail":"With the pane hidden, computer scroll timed out after 30s and a promise-based javascript_tool check hung for 45s; a synchronous check (cards with thumbnail, broken = complete && naturalWidth===0, total) returned 35/35 and 0 broken, and the detail page was proven by reading figure.hero img and figcaption.","why":"Pane-compositing quirks make visual checks flaky, while DOM counts are exact and cheap, and they expose a partial batch edit that a grep count hid.","how":"Prefer synchronous javascript_tool expressions that return counts and broken-image lists, scroll with window.scrollTo via script, avoid awaiting image onload promises, and take one screenshot only after fronting the tab."},{"app":"Coco Modules","category":"architecture","session":"627c1f78","source":"daily-read","title":"Dependency-free modules should expose optional host hooks (e.g. opts.prompt) with a built-in fallback so apps with premium dialogs plug theirs in","detail":"theme-studio's new inline rename calls opts.prompt(currentName), which may return a Promise, so Abba passes its own promptBox; with no hook it falls back to window.prompt and still works. The rename control reveals on hover/focus beside delete and the click guard stops it applying the look.","why":"Copy-in-whole modules cannot import an app's UI kit, but forcing native prompt() into premium apps would violate the no-native-dialogs house rule.","how":"Accept an optional async hook per interaction (prompt, confirm, toast), default to the browser primitive, document it in the module README and header, and test both paths (hook fired and Renamed-1 persisted)."},{"app":"Pixelbake","category":"integrity","session":"595e7a34","source":"daily-read","title":"Never encode an unpublished price as 0: use NA so cost math cannot silently treat it as free","detail":"Models without a published price were given cost:()=>0, and fitsFreePool then treated them as free, undercounting true spend and letting them bypass the free pool.","why":"A zero is a claim (it is free); an unknown is not. Margins and free-tier logic built on 0 are wrong in the user's favour and invisible.","how":"Represent unknown as null/NA, make cost consumers throw or label 'unpriced', exclude NA models from free-pool logic, and only quote numbers copied from the published rate card (worker.js:73-91, 841)."},{"app":"PatentCake","category":"integrity","session":"847a2e5f","source":"daily-read","title":"Enforce append-only at the database with triggers, not by convention","detail":"D1 triggers RAISE on UPDATE and DELETE of the registry tables, so a bug or a rogue caller cannot edit or remove a disclosure.","why":"An evidence registry is only worth anything if history cannot be rewritten; code review alone does not guarantee it.","how":"CREATE TRIGGER ... BEFORE UPDATE/DELETE ... SELECT RAISE(ABORT,'append-only'); add a test that attempts both and expects failure; corrections are new rows that reference the old id."},{"app":"BirthdayTreat","category":"conversion","session":"85333044","source":"daily-read","title":"Per-entity Open Graph meta by rewriting the SPA shell in the Worker","detail":"Birthday links shared to chat apps showed a generic preview because OG tags were static in index.html.","why":"The link preview is the first impression and drives clicks for send-a-link products.","how":"Worker fetches the asset shell, uses HTMLRewriter to inject og:title/description/image for the specific wall (escape values), and keeps caching headers short; verify with a crawler UA curl."},{"app":"Evertrue","category":"design-elevation","session":"be39af71","source":"daily-read","title":"Build a dashboard primitives module (card, stat, sparkline, empty state) and study live category leaders first","detail":"Dashboard screens were assembled from ad hoc markup, so spacing and states drifted between views.","why":"Consistent primitives make every new screen premium by default and cut regression surface.","how":"Extract card/stat/chart/empty-state helpers into one module with tokens, and screenshot live Dribbble/leader references in the browser before designing, not from memory."},{"app":"cross-cutting","category":"workflow","session":"0a7090bc","source":"daily-read","title":"Use CDP headless Chrome for reliable before/after screenshots instead of the flaky pane","detail":"The browser pane returned stale or half-loaded frames; a CDP-driven headless Chrome (Node global WebSocket) captured deterministic shots.","why":"Before/after evidence is only credible if the capture is repeatable.","how":"Launch Chrome with --remote-debugging-port, navigate, wait for load plus a settle delay, Page.captureScreenshot, and name files Label.before.png / Label.after.png for auto-pairing."},{"app":"cross-cutting","category":"workflow","session":"0a7090bc","source":"daily-read","title":"Verify the deployed asset (script src ?v= and curl the file) rather than trusting the pane's console buffer","detail":"The console buffer kept errors from a previous page load, which looked like a live bug after the fix shipped.","why":"Stale buffers and stale caches produce false alarms and false all-clears.","how":"curl the deployed JS and grep for the fix, confirm the ?v= stamp on the script tag, hard-reload, clear the console, then re-check."},{"app":"Fullfill","category":"workflow","session":"819356c7","source":"daily-read","title":"Benchmark models on a synthetic ground-truth set (clean and scanned twins) and pin reasoning_effort low","detail":"Model choice and detector changes were validated against a generated form with known field positions, in both clean and scanned renditions.","why":"Gives a numeric pass rate (29/45 to 45/45) instead of eyeballing, and catches regressions on scans.","how":"Generate the test form with known boxes, render a rasterised noisy twin, score precision/recall per change, and record latency per model."},{"app":"Fullfill","category":"integrity","session":"819356c7","source":"daily-read","title":"Optimistic lock (rev) on envelope save to stop two tabs overwriting each other","detail":"Saves carried a revision and the server rejected writes against an older rev.","why":"Prevents silent last-write-wins data loss in a multi-tab, multi-signer document flow.","how":"UPDATE ... WHERE id=? AND rev=? then rev+1; on 409 reload and merge; show a non-blocking 'updated elsewhere' notice."},{"app":"cross-cutting","category":"dx","session":"819356c7","source":"daily-read","title":"Front the tab and use project-local launch.json when testing in the Claude browser pane","detail":"Hidden panes throttle timers and rAF, and preview_start only sees a launch.json inside the project directory.","why":"Avoids chasing phantom freezes and 'server not found' errors.","how":"tabs_select the tab before timing-sensitive tests; keep .claude/launch.json in the project root."},{"app":"cross-cutting","category":"workflow","session":"6c59c3ad","source":"daily-read","title":"Stage hunks with git apply --cached to commit only your session's changes","detail":"With another session editing the same files, whole-file staging would have bundled their work.","why":"Keeps commits attributable and reversible when sessions overlap.","how":"git diff -- file > p.diff, edit to your hunks, git apply --cached p.diff, then git diff --cached before committing."},{"app":"cross-cutting","category":"workflow","session":"6c59c3ad","source":"daily-read","title":"Verify a pushed commit builds in an isolated worktree with symlinked node_modules","detail":"A clean worktree of the pushed SHA proves the deploy is reproducible without dirty-tree help.","why":"Catches missing files and uncommitted dependencies before they reach production.","how":"git worktree add ../verify <sha>; ln -s ../app/node_modules ../verify/node_modules; run build/tests there; remove the worktree."},{"app":"Abba","category":"architecture","session":"3814d650","source":"daily-read","title":"Probe third-party data sources from Worker egress with an authed, allowlisted debug fetch route","detail":"Feeds that work from a laptop (Google, GDELT) were blocked from Cloudflare egress, so local curl tests proved nothing.","why":"Source viability must be tested from the network that will actually call it.","how":"Add /api/debug/fetch behind auth with a host allowlist and size/time caps, and use it to test each candidate feed before building on it."},{"app":"cross-cutting","category":"dx","session":"3814d650","source":"daily-read","title":"Test recording/camera features headlessly with Chrome fake-media flags and a getDisplayMedia stub","detail":"--use-fake-ui-for-media-stream --use-fake-device-for-media-stream plus a stubbed getDisplayMedia let recording flows run in CI-like headless Chrome.","why":"Media permission prompts otherwise block automated verification.","how":"Launch Chrome with the fake-media flags, inject a stub returning a canvas captureStream for screen share, and assert the recorder output size > 0."},{"app":"Abba","category":"ux","session":"3814d650","source":"daily-read","title":"Double-tap-to-hear gesture module for lessons and glossary terms","detail":"A single gesture module lets any text element be read aloud without per-view wiring.","why":"Makes learning content accessible and hands-free with one consistent interaction.","how":"Delegate dblclick/double-tap on [data-say] elements to the shared TTS module, with a visible hint the first time and a stop affordance."},{"app":"Abba","category":"architecture","session":"3814d650","source":"daily-read","title":"Push-only service worker plus payload-less VAPID push for notifications","detail":"A minimal service worker handling only push/notificationclick, with VAPID-signed push that carries no payload, avoids payload encryption and cache complexity.","why":"Gets reliable alerts with far less code and no stale-asset risk from a caching SW.","how":"SW shows a generic notification and fetches the detail from the API on click; sign with VAPID JWT in the Worker; never cache assets in this SW."},{"app":"Breadcrumb","category":"architecture","session":"1d8ee789","source":"daily-read","title":"Use a generic docs table instead of one growing blob for large synced content","detail":"Conversations, artifacts, sessions and the asks ledger were added after the sync layer and did not fit the single-blob design.","why":"Per-document rows give tombstone sync, per-doc size caps, and avoid the 2 MB blob limit.","how":"docs(id, kind, body, rev, deleted_at) with ON CONFLICT upsert that includes meta, and push/pull deltas by updated_at."},{"app":"cross-cutting","category":"dx","session":"3814d650","source":"daily-read","title":"Patch code with the Edit tool or a quoted heredoc, and assert the anchor exists in scripted patches","detail":"Shell-quoted scripted patches mangled $, backslash and paren characters and String.replace silently no-oped.","why":"A silent no-op looks like success and surfaces later as a ReferenceError in production.","how":"Use Edit, or cat <<'EOF' with a quoted delimiter; in scripts throw unless src.includes(anchor) and unless the output differs from the input."},{"app":"cross-cutting","category":"integrity","session":"1d8ee789","source":"daily-read","title":"Record source and verification date beside every research-derived product rule","detail":"A restriction citing the wrong direction of a study shipped because the rule carried no provenance.","why":"Makes claims auditable and lets a later reader re-verify before trusting or removing a rule.","how":"Keep RESEARCH.md entries as claim, primary source link, verified-on date, and what the product does because of it; re-read the primary before encoding a limit."},{"app":"cross-cutting","category":"integrity","session":"1d8ee789","source":"daily-read","title":"Refresh the agent CLI on every run and add 'login <key>' so stale clients cannot pin agents to old behaviour","detail":"A cached apz.mjs guarded by a file-exists check kept agents on a stale version that lacked new commands.","why":"Prevents drift between server and the CLI agents actually run.","how":"curl the CLI unconditionally at start, and provide an explicit login command that writes the token file."},{"app":"Aprizely","category":"architecture","session":"2b0af159","source":"daily-read","title":"Record 'committed and deployed' per session inside the existing report JSON blob, with an honest tri-state banner","detail":"Reports gained a banner showing whether the session's work was committed and deployed. The Worker accepts a sanitised ship object {committed, sha, message, branch, deployed, url, version, at} stored inside the existing reports.data JSON; apz.mjs gatherShip() auto-detects git HEAD (clean tree means committed) and takes --deployed <url>. States: green committed+deployed, green committed plus amber 'Not deployed yet', and no banner for legacy reports.","why":"Written is not deployed is not working; a visible per-session proof stops 'done' being claimed early, and storing it in the existing blob meant no schema migration and full backward compatibility.","how":"Add an optional sanitised sub-object to the JSON you already store, render it only when present, derive it from git on the client, and let a flag supply the deploy URL; verify all three states plus the legacy no-ship report on wrangler dev before shipping."},{"app":"Hopefil","category":"design-elevation","session":"61020f60","source":"daily-read","title":"Let the logo cycle the site's look: inline boot script sets data-look before paint, a toast names the change, the choice persists","detail":"On the homepage a click on the logo cycles looks (Night, Dawn, Dusk), shows a small toast saying what changed, stores the choice in localStorage, and everywhere else the logo stays a plain link home. A tiny inline script in <head> reads the key and sets data-look on <html> before first paint so there is no flash; hidden alternates are gated with html[data-look] selectors and synced with aria-hidden/inert.","why":"Gives the brand a discoverable-by-play moment at zero navigation cost, makes the whole palette a token swap rather than three stylesheets, and avoids a flash of the wrong look on reload.","how":"Audit hard-coded surfaces first and move them to tokens, define each look as a [data-look] token block, add the inline boot script, wire the brand-link click only on the home route with preventDefault, announce with an aria-live toast and respect prefers-reduced-motion."},{"app":"Pixelbake","category":"integrity","session":"311311cf","source":"daily-read","title":"Reconcile generated images against the studio by (width x height, byte size) plus bake time, never by timestamp alone","detail":"To find AI images that never reached the studio, local files were matched to records. A time window falsely matched 156 of 188 files, dimension matching dropped it to 74, and byte-exact (WxH:bytes) plus time-and-size gave 14 genuinely unfiled. Studio timestamps were London time while file times were local EDT, and queue latency shifted bake times.","why":"Timestamp-only joins hide real strays and invent others; size and dimensions identify the exact file, so 'zero AI images left unfiled' can be proven.","how":"Pull the full library per project (the list endpoint caps at 200), stat local files, read dimensions with sips, match on exact WxH:bytes first then fall back to time window AND dimensions, exclude screenshots/downloads, print the unmatched list as the queue."},{"app":"Hallalu CRM","category":"workflow","session":"215ee275","source":"daily-read","title":"Prove the public demo equals the tested demo with a fingerprint taken through the real click path","detail":"The owner said the landing demo was not the demo being tested. Verification: clear localStorage as a first-time visitor, click the landing 'See the demo', capture a fingerprint (isDemo, base currency, lead names/stages, photo count, invoice refs, collected total), clear storage, load /app?demo=1 directly and diff the two strings. A first false 'not identical' was a hand-typed fingerprint, so the comparison must run on captured values.","why":"A demo is a public promise; comparing real captured state through the actual entry path catches mis-wired CTAs that checks of the seed alone never see.","how":"Add a fingerprint() helper, store the first result before navigating, compare after the second load, and record the verdict with lengths."},{"app":"Hallalu CRM","category":"ux","session":"215ee275","source":"daily-read","title":"Fold bulk import into the primary 'New lead' modal: auto-scan on paste, AI split as a refine step","detail":"The New lead modal opens with a paste box (mic on it) and a From a photo input. Pasting auto-scans with a free on-device parser; one result fills the form, several show editable draft cards with Add all, and 'Not right? Use AI to split' sits beside the results as a refine step rather than a peer of Scan.","why":"One obvious entry point removes decision overhead; the free parse handles the common case instantly, and the paid AI path is offered only when the free result looks wrong, protecting margin.","how":"Expose reusable parseLeadsLocal, addImportedLeads and photoSplit globals, call them from the create modal on input (debounced), show an editable preview before saving, and surface the AI button only after a scan produced results."},{"app":"Hallalu CRM","category":"architecture","session":"215ee275","source":"daily-read","title":"Render pickers opened from inside a form as their own stacked overlay, not through the single-overlay openModal","detail":"openModal() calls closeOverlays() first, so a currency picker launched from the new-lead/settings/invoice modal destroyed the parent form and everything typed. The fix renders the picker as a separate scrim+panel appended to body (higher z-index, its own close handler) that closes only itself and writes the choice back to the still-mounted button and hidden input.","why":"Nested choosers are everywhere (dates, currencies, contacts); one overlay model that wipes siblings silently loses user input.","how":"Give pickers a createStackedOverlay() that never calls closeOverlays, keep selection state on the parent's DOM nodes, and test every picker nested inside every form before shipping."},{"app":"Hallalu CRM","category":"workflow","session":"215ee275","source":"daily-read","title":"Screenshot a client's message and turn it into tickable per-client tasks that surface in Do-next","detail":"Each client gained an Assignments card: type a task, or screenshot the client's message and the existing /api/vision path extracts each request into a checklist item; open tasks also appear in the Do-next view tagged with a camera icon and can be ticked off there.","why":"Client requests arrive as screenshots of DMs; turning them straight into dated work removes retyping and keeps promises visible where the user already looks each morning.","how":"Reuse the vision helper with a prompt that returns one task per line, store lead.tasks[], render a card on client detail and inject open tasks into the next-action stream without changing due-date logic."},{"app":"Capital Signal","category":"design-elevation","session":"e63c44d3","source":"daily-read","title":"Give dark themes a separate blue-surface token instead of reusing the lightened accent","detail":"Lightening --blue for dark mode made white-on-blue chips, CTAs and stat labels 1.07:1. Chips and buttons now read --blue-surface (deep enough for white text) while --blue stays the readable link/accent colour.","why":"One accent token cannot be both a text colour on dark and a fill behind white text.","how":"Define --accent-text and --accent-surface per theme and assert 4.5:1 for each pairing in a build-time check."},{"app":"cross-cutting","category":"accessibility","session":"e63c44d3","source":"daily-read","title":"Sweep computed contrast over every leaf text node with its real ancestor background","detail":"A script walks every leaf text node, resolves the first opaque ancestor background and computes the WCAG ratio; it found three failures that screenshots and token checks missed.","why":"Token pairs say nothing about what actually sits behind each string (gradients, nested cards, dark sections).","how":"Run it per theme and per route in the CDP harness and fail on any ratio under 4.5 (3 for large text)."},{"app":"cross-cutting","category":"dx","session":"e63c44d3","source":"daily-read","title":"Register the LCP observer with Page.addScriptToEvaluateOnNewDocument, not after load","detail":"The first perf run reported LCP 0 and 0 of 5 pass because the PerformanceObserver was attached after the entry had already fired.","why":"LCP and CLS entries are only delivered to observers that exist before they happen.","how":"Inject the observer on new-document and read the buffered entries, with buffered:true as a second guard."},{"app":"cross-cutting","category":"workflow","session":"e63c44d3","source":"daily-read","title":"Run a parity audit script that compares every old-site sentence with the new-site corpus","detail":"The script splits the old pages into sentences and searches the new site; the first run showed 85 of 235 gaps, the fixed site reached 210 of 235 with the rest deliberate.","why":"A rebuild loses copy silently and nobody notices until a customer asks.","how":"Keep it in the repo, print the missing sentences, and re-run before launch."},{"app":"cross-cutting","category":"workflow","session":"e63c44d3","source":"daily-read","title":"Write a .pptx as raw OOXML in a zip when python-pptx is missing, then validate XML and rels","detail":"Without python-pptx a deck was assembled from slide XML, rels and [Content_Types].xml with the zip CLI and checked by parsing every part.","why":"Installing packages is not always possible and a corrupt pptx only fails when the user opens it.","how":"Generate parts from templates, zip with mimetype order preserved, then parse each XML part and each relationship target."},{"app":"cross-cutting","category":"performance","session":"e63c44d3","source":"daily-read","title":"Compress hero video with macOS avconvert and hard-mute it by dropping the audio track","detail":"avconvert -p Preset640x480 took a video from 5.07MB to 1.76MB; it has no strip-audio flag, so the muted copy was produced by exporting without the audio track.","why":"Autoplay hero loops must be small and silent.","how":"Use avconvert for the size win, then verify with ffprobe-equivalent (afinfo) that no audio stream remains."},{"app":"cross-cutting","category":"dx","session":"e63c44d3","source":"daily-read","title":"Audit at build time that every var(--x) used in CSS is defined","detail":"A small script lists custom properties used versus declared and fails on any undefined name.","why":"An undefined variable silently falls back to initial (transparent or inherit), the same class as the missing --card token.","how":"Regex the CSS for var(--name), diff against :root and theme blocks, run in CI."},{"app":"Hopefil World","category":"conversion","session":"e63c44d3","source":"daily-read","title":"Lead the hero with the outcome and a before/after, not the mechanism","detail":"The market study showed rivals open with features; the page now opens with the finished result and a before/after pair.","why":"Visitors decide on what they get, not how it is built.","how":"First screen: outcome sentence, one visual proof, one action; mechanism below the fold."},{"app":"Hopefil World","category":"design-elevation","session":"e63c44d3","source":"daily-read","title":"Use a warm charcoal dark theme and test every text tier on every elevation surface","detail":"Pure black was replaced by a warm charcoal; the three lowest text tiers passed on the base but failed on raised cards until each tier was measured on each surface.","why":"Contrast on the base background does not carry over to elevated cards.","how":"Measure each tier against base, raised and overlay surfaces and keep tier colours that pass all of them."},{"app":"Hopefil World","category":"design-elevation","session":"e63c44d3","source":"daily-read","title":"Show portrait video in a wide hero with a blurred backdrop and a feathered mask","detail":"A 356x640 portrait clip stretched across a 1440px hero threw away resolution; the clip now sits centred over a blurred, darkened copy of itself with feathered edges.","why":"Cropping a portrait video to 16:9 loses the subject; stretching blurs it.","how":"Layer a scaled blurred copy behind the sharp clip and apply a radial or linear mask to the edges."},{"app":"Hopefil World","category":"performance","session":"e63c44d3","source":"daily-read","title":"Probe sitemap candidate URLs in parallel","detail":"Trying sitemap.xml, sitemap_index.xml and variants one after another stalled the server-side site read; probing them concurrently cut it from 16s to 5s.","why":"Serial probes add every timeout together.","how":"Promise.allSettled the candidates with a short per-request timeout and take the first valid XML."},{"app":"Hopefil World","category":"architecture","session":"e63c44d3","source":"daily-read","title":"A Worker cannot launch Claude Code: queue the run, let a local agent claim it, and say so in the UI","detail":"The product queues a run and a local command (hopefil next) claims it; the UI states that a local agent must be running instead of implying the cloud builds it.","why":"Pretending the server executes the agent produces silent stalls.","how":"Store a queued state with a claim endpoint and show who claimed it and when."},{"app":"cross-cutting","category":"dx","session":"cc86f31f","source":"daily-read","title":"Verify a client-rendered page by rendering the DOM; a byte-identical curl shell proves nothing","detail":"A curl of the shell returned the same 82,682 bytes before and after a change because content is built by JavaScript.","why":"The server HTML of an SPA does not change when the client code does.","how":"Drive headless Chrome and assert on rendered text or computed state."},{"app":"cross-cutting","category":"dx","session":"cc86f31f","source":"daily-read","title":"CDP drivers must print exceptionDetails, not an empty object","detail":"A driver printed {} on a script exception; printing exceptionDetails.text and the stack exposed a safeHref ReferenceError.","why":"Runtime.evaluate returns exceptions inside a successful response.","how":"Check result.exceptionDetails on every evaluate and throw with line and message."},{"app":"cross-cutting","category":"workflow","session":"cc86f31f","source":"daily-read","title":"When two branches hold identical work, compare patch-id and tree hash, then let rebase drop the duplicate","detail":"git patch-id matched the commits and git rev-parse on the trees matched before and after the rebase, proving nothing was lost.","why":"Hand-resolving a duplicate risks dropping real changes.","how":"git cherry or patch-id first, rebase, then compare tree hashes."},{"app":"cross-cutting","category":"accessibility","session":"cc86f31f","source":"daily-read","title":"Measure pill contrast on the text band, and reset persisted theme between harness runs","detail":"The bounding box of a rounded pill includes transparent corners so sampling it reads the page behind; the harness also leaked setTheme through localStorage into the next run.","why":"Both produce false failures or false passes in contrast sweeps.","how":"Inset the sample to the text line box and clear localStorage before each theme pass."},{"app":"Hallalu CRM","category":"copy","session":"cc86f31f","source":"daily-read","title":"State Instagram DM limits as verified: private reply within 7 days, one message, business cannot initiate","detail":"Primary documentation says a private reply to a comment is allowed for 7 days and only once, a business cannot start a conversation, and the Human Agent tag is for humans only; vendor blogs repeat a 24-hour window.","why":"Wrong limits turn into automations that Meta blocks and promises the product cannot keep.","how":"Cite the Meta docs in the playbook and phrase auto-DM features as comment-triggered replies."},{"app":"Bug Ledger","category":"integrity","session":"b6ac4f45","source":"daily-read","title":"POST /api/bugs has no server-side duplicate check","detail":"A sync posted 83 items and the response reported skipped(dup)=0 because dedupe existed only against the client's own local log.","why":"Any agent re-run or second agent files the same title again.","how":"Hash app plus normalised title server-side, return 200 with duplicate:true and the existing id."},{"app":"Bug Ledger","category":"integrity","session":"5d4b033a","source":"daily-read","title":"The coverage gate accepts a bulk notFound list, so full coverage can be claimed without checking anything","detail":"A single script posted all 337 titles as notFound and got a full-coverage tick; nothing in the request proves any item was examined.","why":"A self-reported checklist rewards speed over verification.","how":"Require evidence per item (file, detector id or command) for a sampled subset and reject payloads whose notFound list was generated from the catalog without per-item notes."},{"app":"Budget LevelUp","category":"ux","session":"5d4b033a","source":"daily-read","title":"Check scrollWidth against clientWidth before turning a wrapping tab bar into one nowrap row","detail":"A single justified row of 20 tabs needed 1,874px in a 1,244px bar and clipped tabs silently; an auto-fill grid with 112px minimum columns gave two even rows with no overflow.","why":"Space-between hides the overflow until a tab is unreachable.","how":"Measure overflow at 1280 and 1024, and prefer grid auto-fill for large navs."},{"app":"cross-cutting","category":"dx","session":"5d4b033a","source":"daily-read","title":"Post JSON to the ledger from a file or a node script, never as an inline shell string","detail":"An apostrophe in a symptom broke the single-quoted curl body with unmatched quote errors and a backtick in a commit message swallowed words.","why":"Free text always contains quotes and backticks.","how":"Write the payload to a temp file and use curl --data @file, or call https.request from node."},{"app":"Bug Ledger","category":"dx","session":"5d4b033a","source":"daily-read","title":"Make the scanner follow index.html and skip files that are never loaded","detail":"Eight XSS-INNERHTML hits and a duplicate id came from an old app.js that no page loads, costing a manual triage pass.","why":"Dead files produce findings nobody can act on and hide real ones.","how":"Resolve script tags from the HTML entry points and report unreferenced files as dead-code instead of scanning them."},{"app":"cross-cutting","category":"dx","session":"8e4bfa79","source":"daily-read","title":"Disable captureBeyondViewport and assert scrollTop before screenshotting a scrolled inner element","detail":"puppeteer element.screenshot re-laid out the page and reset an inner scroll container, so the after image matched the before image.","why":"The proof screenshot looked identical to the bug it was meant to disprove.","how":"Use page.screenshot with a clip, captureBeyondViewport:false, set scrollTop immediately before capture and log it."},{"app":"cross-cutting","category":"dx","session":"9033ea59","source":"daily-read","title":"Every scripted multi-file patch must assert its anchor matched","detail":"Three times a python str.replace patch silently did nothing (script tags for calendar.js/extras.js inserted against a stale ?v= string, wire.js never added, a block located with .index() that did not exist) and the app shipped with missing modules or ReferenceErrors","why":"A silent no-op replace looks identical to success until a runtime ReferenceError appears deploys later","how":"wrap replace in a helper that asserts old in text (or prints MISS), bump version stamps BEFORE inserting new tags, then verify with [...document.scripts].map(s=>s.src) and a missing-functions list after every deploy"},{"app":"cross-cutting","category":"architecture","session":"9033ea59","source":"daily-read","title":"Private pages on Workers assets: remove the payload from the public bundle instead of gating the route","detail":"Cloudflare serves static assets before the Worker; run_worker_first matches the raw path but the asset server normalises // and %5F, and a gated HTML page still leaks its JS file","why":"No amount of route gating beats an asset that exists in the bundle","how":"move private html/js to src/private/*.txt, import as Text modules (rules: type Text, globs **/*.txt), serve from the Worker after normalising the path and checking a key; test //x, /%5Fx, /X, /./x, /dir/../x and the JS payload URL from outside"},{"app":"cross-cutting","category":"integrity","session":"9033ea59","source":"daily-read","title":"A critique is a claim too: verify the critic before editing shipped copy (and do not over-correct)","detail":"Two critiques were acted on unverified: the Kellogg quote was truncated (dropped '(besides generally faster and more efficiently)'), the critic claimed speed-to-lead rests only on a 2007 deck while omitting HBR 2011 (1.25M leads, 42 companies), and cited first-mover papers selectively; the verification pass also found 4 shipped legal claims wrong","why":"Following an unchecked critique degraded the product and removed a true concept; the right fix was narrower than the one made","how":"before deleting or rewriting a claim on a critic's say-so, run a second pass that reads the primary sources of both the claim and the critique, label VERIFIED/OVERSTATED/FALSE, then restore anything wrongly cut"},{"app":"cross-cutting","category":"integrity","session":"9033ea59","source":"daily-read","title":"Never let an LLM do date arithmetic: pass the user's phrase through and resolve it in code","detail":"Asked for 'next Tuesday' the model returned 2025-01-07 with today's date in the prompt; clamping past dates only moved it to 2027","why":"A reminder in the wrong year simply never appears, with no error","how":"prompt says 'say the day as the person said it, never compute a date'; dayOf() resolves today/tomorrow/in N days/weekday/next week deterministically and pulls any past ISO date forward; show the resolved date back to the user"},{"app":"Hallalu CRM","category":"architecture","session":"9033ea59","source":"daily-read","title":"One field schema must drive both the card display and the add/edit form","detail":"Rolodex influencer cards showed per-platform followers and engagement, providers showed rating, business showed phone, but the add form collected none of them (same class in several sections)","why":"Two hand-written lists drift until the UI displays data no one can enter","how":"define ROLO_SCHEMA per category once and derive card chips, form inputs and the edit modal from it; add a check that every rendered field has an input"},{"app":"cross-cutting","category":"integrity","session":"9033ea59","source":"daily-read","title":"Pin the Stripe API version: the 2026 'Dahlia' release removed ui_mode embedded and initEmbeddedCheckout","detail":"Code written from memory used ui_mode:'embedded' and stripe.initEmbeddedCheckout(), both removed (not deprecated) in the 2026-07-29.dahlia release; the correct values are ui_mode 'embedded_page' and createEmbeddedCheckoutPage from js.stripe.com/dahlia/stripe.js","why":"An unpinned integration starts failing on a date nobody chose and the first customer finds out","how":"send Stripe-Version on every REST call, read the release notes before coding checkout, use invoice.paid and customer.subscription.trial_will_end, implement a free week as an entitlement flag not trial_end (which would overwrite a paying subscription's trial)"},{"app":"cross-cutting","category":"integrity","session":"9033ea59","source":"daily-read","title":"Prove webhook signature verification with a forged-request harness","detail":"9-case harness against the live endpoint: correct signature accepted, replayed event deduped, body tampered, wrong secret, 400s-old timestamp, 400s-future timestamp, v0-only downgrade, secret rotation","why":"Verification code that merely fails closed when the secret is missing proves nothing about the HMAC path","how":"set a throwaway whsec_ secret, sign with node crypto createHmac sha256 over t.body, assert 200/duplicate/400 per case, then replace the secret with the real one"},{"app":"cross-cutting","category":"dx","session":"9033ea59","source":"daily-read","title":"Lint for duplicate case labels in switch-based event dispatchers and namespace state modifier classes","detail":"Two 'new-call' cases in one data-act switch made the first shadow the real handler, and a state class .ava collided with the avatar component class .ava","why":"JS allows duplicate case labels silently and shared class names cascade across components","how":"add grep -o \"case '[a-z0-9-]*':\" app.js | sort | uniq -d to the pre-deploy check; name state modifiers is-* so they cannot match component rules"},{"app":"Hallalu CRM","category":"integrity","session":"9033ea59","source":"daily-read","title":"Source registry carries per-platform compliance flags that change what the CRM allows","detail":"Dribbble deems you introduced by viewing a profile and requires 12 months of on-platform billing with audit rights; Etsy/eBay/Amazon/Upwork/TaskRabbit/Airtasker forbid off-platform contact or payment; Care.com penalises scraped data; Remote OK requires a dofollow attribution; NoDesk bans aggregator access; Thumbtack refunds only within 45 days","why":"A CRM that cheerfully drafts a direct invoice for a Dribbble-introduced client walks the user into a contract breach","how":"store an introducedOn date and a billOnPlatformUntil flag per source, warn or block direct invoicing, never build importers for platforms whose terms ban them, record unverified items as unverified"},{"app":"cross-cutting","category":"integrity","session":"9033ea59","source":"daily-read","title":"Shared free-tier quotas need per-account metering: Google Studio TTS 1M free characters is per project, not per customer","detail":"Studio voices cost $160 per million characters beyond the free 1M (about 20 hours) and cap each request at 5,000 bytes; the wording had implied 20 hours per customer","why":"One heavy user can burn the whole project allowance and the bill","how":"per-plan character budget with a visible meter, chunk text on sentence boundaries under 3,800 bytes using TextEncoder byte length, say plainly that the free allowance is shared"},{"app":"cross-cutting","category":"integrity","session":"9033ea59","source":"daily-read","title":"Struck-through 'was' prices: charge the list price genuinely first and gate the sale behind a flag with a recorded launch date","detail":"A $15 struck through to $7 on day one fails UCPD Art 6(1)(d) / DMCC s.226 presentation tests (SaaS is not covered by the EU goods 30-day rule), enforcement is live (SHEIN EUR40m), and anchoring barely moves real purchases (Brzozowicz & Krawczyk 2022: +0/+0/+14%)","why":"Fake reference prices are an enforcement target and may not even convert","how":"SALE config disabled at launch, launch date stored for audit, show $15 now, flip the sale only after 30 days with a lowest-price disclosure; remove every 'forever' price promise and offer 60 days written notice instead"},{"app":"cross-cutting","category":"ux","session":"9033ea59","source":"daily-read","title":"Celebration layer: rare, capped, evidence-calibrated, off under prefers-reduced-motion with an in-app toggle","detail":"Kao et al. CHI 2024 (n=1,699, pre-registered) found amplified feedback reduced competence and curiosity; streak research favours at most 2 repairable freezes and never announcing a broken streak","why":"Confetti on every task can patronise and lowers perceived competence","how":"celebrate only milestones, cap frequency, respect reduced-motion, mark the canvas aria-hidden, keep the in-app toggle conservative, keep streak freezes silent"},{"app":"cross-cutting","category":"workflow","session":"a5a97e71","source":"daily-read","title":"Rewriting git history across live co-edited repos: message-only filter, tree-hash proof, bundle plus refs/original backups, and check HEAD stability first","detail":"Stripping 720 Co-Authored-By trailers from 22 repos used a git filter-branch --msg-filter, compared per-commit tree hashes (all IDENTICAL) and kept a git bundle plus refs/original per repo; two repos were re-dirtied by live sessions (a new trailered commit, and a merge that pulled the old history back) before the push","why":"A history rewrite under a repo another session is committing to is silently undone or clobbers its work","how":"verify HEAD has been stable for minutes before rewriting, stash dirty trees, assert unique tree sets equal before and after, run the force-push as its own explicit step (a combined rewrite+push script was refused by the permission classifier), and verify remote HEAD with ls-remote afterwards"},{"app":"cross-cutting","category":"workflow","session":"ea9a3232","source":"daily-read","title":"Write deliverable HTML to a durable path, not the session scratchpad, and verify it exists before serving","detail":"The scratchpad reported 'File created successfully' then was empty (total 0) when the server returned 404, losing the whole page build","why":"The scratchpad can wipe mid-session and the loss only shows up as a confusing 404","how":"write to ~/ (or the repo), ls the file before starting a server, republish artifacts from the durable path"},{"app":"cross-cutting","category":"workflow","session":"ea9a3232","source":"daily-read","title":"Deliver a real PDF with headless Chrome --print-to-pdf and a ?print=1 static mode when the artifact sandbox may block downloads","detail":"A ?print=1 query param froze the animated counter, a print stylesheet forced the light theme and hid the topbar, and Chrome --headless=new --no-pdf-header-footer --virtual-time-budget=6000 produced a 14-page 1.26MB PDF verified with a qlmanage thumbnail","why":"Script-driven downloads and window.print() can be blocked inside a sandboxed iframe","how":"add print CSS plus a print-mode guard for animations, serve over local http, run headless Chrome print-to-pdf, check the page count and page 1 thumbnail, then send the file"},{"app":"Evertrue","category":"integrity","session":"17d3ca5a","source":"daily-read","title":"Multi-shop 'All shops' roll-ups must never add across currencies","detail":"Give every record a shopId and let each shop carry its own currency, fee table, Star Seller thresholds, goals and challenge. In 'All shops' mode show per-currency totals and per-shop cards, never one summed number.","why":"Adding USD and GBP produces a figure that is true in neither currency and silently wrong for any seller with two storefronts.","how":"Stamp shopId on every record and migrate existing data into the first shop. Add Store.sid(base) for per-shop singleton ids and an 'all' pseudo-shop. Group by currency in the hero stats, and format each row with its own currency."},{"app":"Evertrue","category":"architecture","session":"17d3ca5a","source":"daily-read","title":"Derive accent-soft, ink and ring from --accent with color-mix so any theme or custom accent stays coherent","detail":"A vendored theme module carried its own blue accent and token names (txt/dim/cardSolid), which overrode the app's accent and mismapped colours. Map module tokens to app tokens explicitly. Compute accent-soft, accent-ink, accent-hover and ring from the single --accent.","why":"Hand-picking each tint per theme breaks the moment a user fine-tunes one colour, and a third-party palette can silently recolour the brand.","how":"Define a THEME_MAP from module keys to CSS vars. Set --accent-soft with color-mix(in srgb, var(--accent) 12%, white) and equivalents for ink and ring in :root, and make Light/Dark clear any applied palette."},{"app":"Evertrue","category":"integrity","session":"17d3ca5a","source":"daily-read","title":"Don't display an invented time for date-only imported values","detail":"Etsy CSV dates carry no time. Formatting them with a time shows a fabricated '12:00 AM'.","why":"A made-up time reads as data and misleads ship-by and reply-clock reasoning.","how":"Use a hasTime(ms) check (hours, minutes or seconds non-zero) and append the time only when the source had one."},{"app":"cross-cutting","category":"workflow","session":"17d3ca5a","source":"daily-read","title":"Resume rate-limit-killed research agents by message ('write findings now from what you gathered') instead of restarting","detail":"Six parallel research agents were killed by the session limit mid-write. Their transcripts persisted, so each was resumed via SendMessage with an instruction to write its findings file immediately from its context and reply with path plus summary. All six delivered without re-searching.","why":"Restarting repeats around 100 web fetches per lane and trips the limit again.","how":"Have every lane write its output file incrementally. After the limit resets, send each agent the 'write the file now, no new searches' message, one at a time."},{"app":"Coco Modules","category":"workflow","session":"17d3ca5a","source":"daily-read","title":"Re-fetch the registry manifest and run describe-search before publishing a new module","detail":"A concurrent session published near-duplicates (to-do-list and day-planner) beside todo-list and routine-timetable, so the registry ended up with two of each idea.","why":"Duplicate modules fragment fixes and confuse agents choosing what to reuse.","how":"Fetch modules.json immediately before authoring, search by description, and extend an existing module if it fits. Keep an explicit slug-to-group map so the TOC does not rely on tag regexes."},{"app":"cross-cutting","category":"dx","session":"17d3ca5a","source":"daily-read","title":"Verify generated .xlsx via Excel AppleScript from /tmp, and read value/number format, not 'text of range'","detail":"Opening the test file from ~/Desktop raised a macOS 'Excel would like to access files in your Desktop folder' dialog that hung every osascript call. After it was cleared, 'text of range' failed with Parameter error -50 while 'value' and 'number format' worked.","why":"A permission dialog blocks an unattended agent indefinitely, and the wrong property gives false failures.","how":"cp the test file to /tmp, open -a 'Microsoft Excel', then read value of range and number format of range per cell. Also assert bold, fill colour, freeze panes and autofilter."},{"app":"cross-cutting","category":"dx","session":"17d3ca5a","source":"daily-read","title":"Screenshot with headless Chrome plus a cache-buster when the browser-pane screenshot fails or the pane is stale","detail":"The pane screenshot threw UnknownVizError on tall or resized viewports and served cached shells and sample data. Headless Chrome with --virtual-time-budget produced reliable full-page PNGs.","why":"Proof screenshots are a required deliverable, and a flaky capture tool should not block them.","how":"Run Google Chrome with --headless=new --disable-gpu --hide-scrollbars --window-size=W,H --virtual-time-budget=7000 --screenshot=out.png and a random cache-busting query on the URL. Read the PNG at full size to QA it."},{"app":"cross-cutting","category":"dx","session":"17d3ca5a","source":"daily-read","title":"Wrap wrangler deploy in a backgrounded retry-with-backoff and gate on wrangler whoami first","detail":"Deploys failed repeatedly with 'malformed response from the API' and 'upstream connect error' during a Cloudflare API blip, and later with an expired OAuth token. Blocking the session on them wasted turns.","why":"Transient API errors and expired logins need different handling, and retries should not stall the work.","how":"Run npx wrangler whoami to refresh or detect expiry. Then run a deploy loop of 6-10 attempts with 30-40s sleeps in the background, and confirm the served asset ?v= with curl before verifying."},{"app":"cross-cutting","category":"integrity","session":"17d3ca5a","source":"daily-read","title":"Check the terms of a feed before building a feature on it","detail":"Google News RSS was reachable from the shell, but its terms limit it to personal use. The news feature used Etsy's own investor press RSS plus the Community announcements page and labelled curated versus fetched items honestly.","why":"A reachable endpoint is not a licence, and building on one forces a rewrite later.","how":"Prefer first-party RSS or HTML. If a forum exposes no RSS, parse its embedded JSON. Read datePublished from the topic page's ld+json rather than stamping fetch time. Store only title, link and date."},{"app":"Aprizely","category":"dx","session":"124574d9","source":"daily-read","title":"Agent API silently drops unknown task fields; return an ignored-fields warning or carry data in existing strings","detail":"/api/agent/worklog whitelists task fields to text/status/note/wave. A dedicated eta field would have vanished with no error, so ETAs had to ride inside the wave and task strings as (~NNm) tokens parsed client-side.","why":"Silent field stripping makes agents believe data was saved.","how":"Return an ignored_fields array in the response, or extend the whitelist deliberately. Keep client parsers tolerant: a token wins at wave level, and a missing token renders no badge."},{"app":"cross-cutting","category":"workflow","session":"124574d9","source":"daily-read","title":"Agent-memory rules do not change the product: a requested board capability must ship as a product change and be verified on a fresh board","detail":"The user asked for per-wave ETAs and no board lag. The first response only edited the agent's private memory, so a freshly run board looked unchanged and the user reported 'did not see the changes'.","why":"Behavioural rules only affect sessions that load that memory. A request about what a page shows needs a code change.","how":"Classify each ask as agent behaviour or product feature. For product features, change and deploy the product and prove it on a new run. State plainly which kind each change was."},{"app":"Aprizely","category":"workflow","session":"124574d9","source":"daily-read","title":"Don't add a second agent to sync the board: apz keeps one local state file, so interleave board calls in the same tool batch","detail":"The user suggested a dedicated agent to keep the board current. A second writer would race on the single local worklog state file and cause the very lag it was meant to fix.","why":"A single-writer state file plus parallel writers causes lost or out-of-order ticks.","how":"Issue step/done in the same batch as the real work, and surface lag with a freshness pill derived from the worklog updated timestamp."},{"app":"Aprizely","category":"architecture","session":"124574d9","source":"daily-read","title":"Derive the immutable asset version from a content hash at deploy instead of a hand-bumped constant","detail":"The shell rewrites assets to /_v/<ASSET_VER>/file with immutable caching, and a forgotten manual bump shipped changes that cached browsers never loaded.","why":"Anything that depends on remembering a constant will eventually be forgotten, and the failure is invisible to the developer.","how":"Compute a short hash of the asset files at build or deploy and inject it as ASSET_VER, or make a deploy script fail when public/ changed but the version did not."},{"app":"cross-cutting","category":"workflow","session":"86334a14","source":"daily-read","title":"Research fan-outs must write incrementally and stay at 3-4 parallel agents","detail":"Twelve parallel research-lane agents hit the account session limit (HTTP 429) within about an hour. Eleven died with zero output, and two relaunches of eleven lanes were cut the same way. Once every agent was told to create its lane file first with skeleton headings and append section-by-section, five lane files survived with partial findings.","why":"A rate-limit cut otherwise erases all in-flight work, and re-running burns the same quota again.","how":"Run at most 3-4 agents per batch. Have each agent create its output file first, append per question, and cache source pages to disk (curl + text extraction) so a resumed run reuses them. Have the main session read the lane files rather than the agents' final messages."},{"app":"cross-cutting","category":"workflow","session":"86334a14","source":"daily-read","title":"Bot-walled primary sources: curl with a browser UA into a page cache, and say 'could not verify' otherwise","detail":"Ofcom (Cloudflare 'Just a moment...'), EUR-Lex, Etsy and the UK IPO returned 403s or captcha walls to WebFetch and the browser pane, and WebFetch's safety layer failed on whole batches. About 250 primary pages were fetched with curl and a browser UA into the scratchpad and run through a text extractor, then grepped for verbatim clauses.","why":"A failed fetch is not a finding. Treating it as one invents restrictions or drops evidence, and a page cache survives agent deaths.","how":"curl -sL with a browser UA into scratchpad/<lane>/, extract text with a small script, quote clauses by grep. Take fees and statutes from an alternate primary (EUR-Lex annex, legislation.gov.uk). Record walled pages under 'could not verify' and never bypass captchas."},{"app":"cross-cutting","category":"integrity","session":"6739dab7","source":"daily-read","title":"Verify a 'verbatim law' string with a script across every file; keep it on one physical line","detail":"When a user's exact wording is embedded as the governing text of a skill, markdown line-wrapping and a stray period broke the exact match in the command file while SKILL.md and the checklist passed. A node script that reads each file and checks includes(V) caught it, and later skills put the sentence on a single line.","why":"'Embedded verbatim' is otherwise asserted, not proven, and shell one-liners mangle characters such as em-dashes, arrows, >= and nested quotes.","how":"Write the check as a script file (not a shell argument) that normalises nothing and reports EXACT/MISSING per file. Keep the law on one unwrapped line and re-run the script after every edit."},{"app":"SkillSea","category":"dx","session":"6739dab7","source":"daily-read","title":"Auto-detect user-authored skills instead of hard-coding an ORIGINAL_SKILLS set","detail":"scan.mjs files a ~/.claude/skills entry as 'your original' only if its name is in a hard-coded Set, which was hand-edited eight times in one stretch (finish, together, analyses, reason, window, keep, detail, ...). Anything not listed is catalogued as third-party 'installed'.","why":"Forgetting the edit silently miscounts originals and mislabels the owner's own work, and every new skill needs a code change plus redeploy.","how":"Derive 'original' from provenance: a matching ~/.claude/commands file, or an 'origin: user' frontmatter field, or any skill not under ~/.claude/plugins. Keep the Set only as an override."},{"app":"cross-cutting","category":"dx","session":"6739dab7","source":"daily-read","title":"Verifying a fresh deploy in the Browser pane: defeat the 5-minute HTML cache and don't trust blank screenshots","detail":"The site served HTML with cache-control max-age=300, so the browser showed the old CSS and counts right after deploy. navigate() dropped the ?query, so the cache-bust did not apply. A hidden pane made screenshots time out while DOM reads still worked, and a tab pinned to a local file preview refused navigation.","why":"Verification against a stale or invisible page produces false 'not fixed' or false 'fixed' conclusions.","how":"Run curl with a cache-busted URL for server truth. In the pane use location.replace(url+'?cb='+Date.now()), then read computed styles and DOM text. If the pane is hidden or screenshots are blank, say so and cite the DOM or curl proof. Open a new tab when one is pinned."},{"app":"cross-cutting","category":"architecture","session":"6739dab7","source":"daily-read","title":"Boot watchdog: race the session fetch, validate its shape, and turn a stuck splash into Reload / Reset","detail":"A returning user hung on 'Loading…' forever because boot() awaited api('/me') with no timeout and rendered the shell outside any try/catch. The fix was a 10s race on /me, a shape check on the response, a guarded post-auth render, and a 15s watchdog that swaps the splash for a Reload / Reset-and-reload card. It was proved on the deployed app by stubbing window.fetch to hang and to return {}.","why":"Any await on the boot path can strand every returning user, and stale local state is invisible to the developer in a clean browser.","how":"Wrap every boot-blocking fetch in an AbortController timeout. Validate the payload before touching nested fields. Add a global watchdog that offers Reload and a Reset that clears only the token. Test by monkey-patching fetch in the live page."},{"app":"Analysis","category":"dx","session":"6739dab7","source":"daily-read","title":"Author reports as JSON or template literals, not single-quoted JS strings, in the ANALYSES array","detail":"Report copy lives inside single-quoted JS strings in worker.js. While avoiding apostrophes, one callout was mangled to 'Couldn not-verify is not doesn not-exist' and had to be fixed before the node --check passed. The file is also edited concurrently by other sessions.","why":"One unescaped quote can take the whole Worker down at deploy, and writers distort the prose to dodge it.","how":"Move entries to a data file (JSON/JS module with template literals) and validate with a schema check plus node --check in the publish script. Append entries by id, never by array position."},{"app":"cross-cutting","category":"integrity","session":"86334a14","source":"daily-read","title":"Digital-content and credit checkouts need express consent plus acknowledgement of the lost right to cancel","detail":"Under the UK Consumer Contracts Regulations 2013 reg 37, the trader must not begin supplying digital content before the cancellation period ends unless the consumer has given express consent and acknowledged that the right to cancel is lost. This applies to AI credits, downloads and instant-access checkouts in Pixelbake, Stitchhooky, Hallalu and similar apps.","why":"Without the two-part consent the buyer keeps a 14-day refund right on content already consumed, and the trader bears the loss.","how":"Add a required unticked checkbox at checkout that records consent, acknowledgement and timestamp with the Stripe session. Show the refund policy, and note that the DMCC subscription regime has been delayed to spring 2027."},{"app":"cross-cutting","category":"integrity","session":"86334a14","source":"daily-read","title":"Check the payment processor's restricted-business list before monetising trading or advice tools","detail":"Stripe's restricted-businesses page lists 'consultation, advisory services or tools providing guidance on how to profit through trading or investments in financial products or cryptocurrency'. Trader-journal, backtester and signal apps can fall inside that wording, and the research found small operators shut down by Stripe, Etsy, Yahoo or Meta rather than fined.","why":"An account closure is the real enforcement risk for a solo developer and it can freeze all revenue.","how":"Read the processor's restricted and prohibited lists per app before enabling billing. Position the product as process and record-keeping, keep the not-investment-advice and hypothetical-results disclaimers, and keep a second processor ready."},{"app":"cross-cutting","category":"workflow","session":"86334a14","source":"daily-read","title":"Clear a product name on the registers before building the brand (costs and sources included)","detail":"TMview (an EUIPO mirror of UKIPO, EUIPO and USPTO data) and Companies House gave exact-hit checks across 25 names in one pass and found 4 unsafe and 7 serious conflicts. Fees verified from primary sources: UK online £205 + £60 per extra class (up from £170/£50 on 1 Apr 2026), EUTM €850/€50/€150, USPTO $350 per class.","why":"Renaming after launch costs links, users and marketing, and an identical mark in the same class is infringement from day one.","how":"Search the name and phonetic variants in classes 9, 35, 36, 38 and 42 on TMview, USPTO and Companies House before naming. Also check platform trademark policies (such as Git's). Register one house mark first (COCONVO) and file individual product names only when live."},{"app":"Pixelbake","category":"architecture","session":"7dfd4c0c","source":"daily-read","title":"First-party AI upscale: Images binding fit scale-up with a sharpen/contrast/saturation finishing pass","detail":"The existing env.IMAGES binding can AI-upscale 2x/4x and takes sharpen (0-10), contrast and saturation in the same transform. It runs as one billed transformation and needs no third-party billing.","why":"It works today without AI Gateway credits and gives a visibly crisper result on low-res sources. Measured: the sharpen pass, not chaining, was the lever.","how":"env.IMAGES.input(stream).transform({width,height,fit:'scale-up'}).transform({sharpen:4,contrast:1.06,saturation:1.08}).output({format}); cap the long edge at 8192px; store as a versioned child image."},{"app":"Pixelbake","category":"integrity","session":"7dfd4c0c","source":"daily-read","title":"Run a controlled A/B before shipping an 'improvement' - a confounded comparison almost shipped double-ESRGAN","detail":"Chained 2x+2x ESRGAN looked clearer than a single 4x pass, but the single pass in that comparison had weaker sharpening. Re-testing with equal finishing showed negligible extra detail.","why":"It stopped a costlier, slower pipeline from shipping on a false win, and it was reverted openly.","how":"Change one variable at a time on the same low-res source and compare matched crops at equal display size. Keep a result only if it survives the controlled re-run, and revert and say so if it does not."},{"app":"Pixelbake","category":"integrity","session":"7dfd4c0c","source":"daily-read","title":"Price labels must come from the same function that bills (live /api/estimate), never hardcoded","detail":"The 'Bake the fix - 2 credits' button hardcoded a price while creditsFor() scaled by model and size (42 for FLUX.2 dev, 8 for klein-4b at 2048 square). The same static-label pattern was reported on the re-engineer compare and carousel fix buttons but not verified.","why":"A wrong price label on a credit product is a trust and refund problem.","how":"Render the button without a number, call the estimate endpoint on open and on every model or size change, and write credits_needed into the label; grep every button that triggers a billable bake."},{"app":"Pixelbake","category":"ux","session":"7dfd4c0c","source":"daily-read","title":"Every long async job ends with an explicit 'done' moment","detail":"New tiles pop in with a glow and a fading 'Just baked' flag, and modal results open with a green labelled ribbon ('Upscaled 2x - Clear').","why":"Users otherwise cannot tell that a multi-second job has finished.","how":"A markFresh(tile) helper plus openLightbox(id, freshLabel); ribbon auto-fades and respects reduced motion."},{"app":"Pixelbake","category":"architecture","session":"7dfd4c0c","source":"daily-read","title":"Spend a model's small reference-image budget on the face: Images gravity:face crop at about 500px","detail":"FLUX.2 klein accepts up to 4 references, each under 512px. A full portrait wastes those pixels on background, so references are face-cropped before they are sent.","why":"Reference resolution is the identity-fidelity ceiling on first-party klein.","how":"env.IMAGES.input(src).transform({width:500,height:500,fit:'cover',gravity:'face'}) before building input_image_0..3."},{"app":"Pixelbake","category":"integrity","session":"7dfd4c0c","source":"daily-read","title":"Show a VLM identity-match score, label it an estimate, and require a likeness-consent acknowledgement","detail":"Each character bake runs a vision check and shows 'identity match N/10 - off: nose, eyebrows, lips'. Workers AI has no face-embedding model, so the UI says this is an AI estimate, not biometric. Saving a person requires a consent tick (NO FAKES / GDPR / EU AI Act).","why":"It surfaces the signal competitors hide, avoids overclaiming accuracy, and covers likeness-rights exposure. Observed scores: 9/10, 8/10 and 6/10.","how":"Two-step vision check returning {score, same, off[]}, with the score shown as a lightbox chip, an honest-limits note (profiles, expressions, aging) and a mandatory consent checkbox on save."},{"app":"Pixelbake","category":"workflow","session":"7dfd4c0c","source":"daily-read","title":"Character recipe: enumerated feature descriptor + curated multi-angle reference bank + locked seed + auto character sheet","detail":"Describe a person with enumerated features (eye shape, nose bridge, jaw, hair, skin, scar and freckles), not 'same person'. Keep 3-6 varied-angle references and a locked seed, and auto-generate a front, three-quarter, profile and smile sheet.","why":"This was the research-backed recipe that carried identity into new scenes.","how":"Store the brief, traits JSON, ref ids and seed per character, and inject an anchor prompt plus face-cropped refs and the seed into every bake that names the character."},{"app":"cross-cutting","category":"integrity","session":"7dfd4c0c","source":"daily-read","title":"Charge for a paid AI call only after provider success, and say 'Nothing was charged' on failure","detail":"The Pruna 'Insufficient AI Gateway credits' failure returned a 502 with 'Nothing was charged.', and credits were debited only after the output was stored.","why":"Provider billing and quota errors are common and must never cost the user credits.","how":"Run the call, validate and store the output, then debit with the image id as the reference. Map provider error codes to plain-English messages and log an 'issue' event."},{"app":"Coco Modules","category":"integrity","session":"7dfd4c0c","source":"daily-read","title":"Derive the registry's count from the array length at deploy, and keep a single served modules.json","detail":"A hand-edited 'count' field had silently drifted by one, and edits to an unserved duplicate file deployed nothing.","why":"Agents read this registry as the source of truth.","how":"A predeploy script sets count = modules.length and fails if the root and public copies differ. After deploying, verify with a ?v=timestamp fetch."},{"app":"cross-cutting","category":"testing","session":"7dfd4c0c","source":"daily-read","title":"Test API contracts from a script file, not inline shell loops - quoting artifacts produced a false 'estimate = 1 credit' alarm","detail":"A bash loop using set -- $wh and node -e one-liners reported 1 credit for every model and size. Raw curl showed the endpoint correctly returned 42 and 8.","why":"A misleading harness nearly caused a correct fix to be distrusted and rewritten.","how":"Write the request as a small .mjs script with JSON bodies, print the raw response, and only then assert on it."},{"app":"cross-cutting","category":"dx","session":"7dfd4c0c","source":"daily-read","title":"Verify an auth-gated SPA by serving public/ through a same-origin proxy that injects the agent token (bind to 127.0.0.1 only)","detail":"A ~30-line Node proxy serves the static files, forwards /api to the live Worker with the stored token, and the app boots signed in. This verified the real modals, labels and loaders without a PIN login.","why":"It proves UI work on authed surfaces with real data and creates no account.","how":"proxy.mjs: http.createServer on localhost, static fallback for non-/api paths, add an Authorization header on /api, and stop it afterwards. Never bind to 0.0.0.0, since it holds a live token."},{"app":"Finished.","category":"integrity","session":"4324cbca","source":"daily-read","title":"Give any temporary auth bypass a greppable marker and prove it is gone before committing","detail":"A local #verify gate bypass was added in App.tsx (entered initial state and the auth-expired handler), tagged TEMP-VERIFY-BYPASS, then removed.","why":"A forgotten test bypass in an auth gate is a shippable vulnerability. The marker made absence provable.","how":"Tag every temp bypass with a unique token, run grep -rn TEMP-VERIFY-BYPASS src before staging, and check git diff --stat shows only the intended files."},{"app":"Finished.","category":"integrity","session":"4324cbca","source":"daily-read","title":"When you add input sanitising, also harden render-time CSS so already-stored damaged content is repaired","detail":"Docs saved before the fix still held pasted inline styles. CSS forces ul[style] and li[style] back to outside markers with proper padding.","why":"A fix at the input boundary does not repair existing records.","how":"Add attribute-selector overrides (ul[style], ol[style], li[style]) that restore list-style-position, padding and marker colour, and test them on a pre-fix saved document."},{"app":"Finished.","category":"ux","session":"4324cbca","source":"daily-read","title":"Google-Docs-style A4 page breaks in pure CSS, with page count from real content height","detail":"Two stacked repeating-linear-gradients keyed to --pageh draw a shadow, a desk-grey gutter and a page edge, with background-attachment:local so they scroll with the text. Page total is computed from content height minus bottom padding and the one-page min-height.","why":"It gives visible page boundaries without splitting DOM nodes, and the Page N of M pill matches the real end (verified 1/5, 2/5, 5/5).","how":"--pageh = clientWidth*1.414; total = ceil((scrollHeight - padBottom)/pageH); clamp cur to total at scroll end; use separate colour tokens for light and midnight themes."},{"app":"cross-cutting","category":"workflow","session":"4324cbca","source":"daily-read","title":"Honour per-repo 'push to main auto-deploys to live users and Stripe' rules: commit locally and ask before pushing","detail":"The project's command file said 'Deploy only if I ask' and 'stage only files you touched'. The session committed four named files locally, reported, and pushed only after an explicit go-ahead. It then confirmed the live CSS bundle carried the fix by polling for --page-desk.","why":"It avoids an unreviewed release to paying users, and 'pushed' is not 'deployed'.","how":"git add <named files>, commit, then ask. After approval, push and poll the production bundle with a cache-busting query until a unique token from the change appears."},{"app":"Coco Modules","category":"architecture","session":"cd37da75","source":"daily-read","title":"Give copied-whole modules a version stamp and a drift check","detail":"The activity-timeline module now exists as three copies (modules registry, Aprizely public/, Breadcrumb public/) because the registry philosophy is to copy modules whole, and the apz.mjs CLI is likewise kept in three places that are synced by hand and compared with md5.","why":"Copies silently diverge: a fix to one copy never reaches the others, and nobody notices until a view behaves differently across apps.","how":"Add a version and checksum header to every module, publish checksums in modules.json, and ship a small modules-check command that compares each app's local copy with the registry, prints which are behind, and runs from the deploy script."},{"app":"Aprizely","category":"copy","session":"cd37da75","source":"daily-read","title":"Label generated next steps and hide boilerplate when the run gives no signal","detail":"When an agent supplies no nextSteps, report pages render a Next steps card from canned lines such as add a before/after metric next time and automate the repetitive part with a scheduled agent, even for runs with an empty queue and no issues.","why":"The owner asked for suggestions they may not have thought of; identical generic lines on every report read as filler and make the agent-written ones look equally generic.","how":"Mark each card as suggested by the agent or auto-generated, derive fallback lines only from real data in the run (open queue items, issues, missing metrics, stale projects), and omit the card when there is nothing specific to say."},{"app":"cross-cutting","category":"dx","session":"cd37da75","source":"daily-read","title":"Browser-pane verification harness: assert the page first, wrap scripts in an IIFE, avoid hidden-pane actions","detail":"Repeated verification stumbles in the Aprizely, Breadcrumb and Payrails runs: a reload landed the shared tab on the /live board URL so every state check ran against the wrong page (S and go undefined); javascript_exec rejects a top-level return and a const redeclared between calls; computer scroll and screenshots time out or come back blank when the pane is hidden.","why":"Each stumble costs a round trip and can produce a false verdict that the feature is broken.","how":"Keep the live board and the app under test in separate tabs (tabs_create); start every check by returning location.pathname and a known global; always wrap scripts in an IIFE that returns JSON.stringify of the result; prefer DOM reads and elementFromPoint over scroll and screenshots when the pane is hidden, and front the tab before taking pictures."},{"app":"Aprizely","category":"workflow","session":"8007b232","source":"daily-read","title":"Let agents upload real screenshots by wiring a headless-Chrome or CDP capture into apz.mjs shot","detail":"The standing rule says every run must screenshot each page it touched, but screenshots taken in the Browser pane come back inline and cannot be written to disk, so the only shots uploaded in the proving run were five synthetic mockups drawn by a Node script. A headless Chrome command (--headless --screenshot --virtual-time-budget, with ?demo=1 for gated apps) was used successfully in an earlier session.","why":"Without a file path the capture-and-compare feature cannot meet its own rule, and agents are pushed toward fake images.","how":"Add apz.mjs shot --capture <url> that shells out to headless Chrome (or the shoot.mjs CDP helper for authenticated pages) and uploads the result with its label and stage, and document the one-liner in AGENTS.md."},{"app":"Aprizely","category":"integrity","session":"8007b232","source":"daily-read","title":"Mark synthetic or test screenshots so they never join a project's real Screens record","detail":"Five generated mockup PNGs were uploaded through apz.mjs shots with the same labels and before/after stages as genuine captures (Dashboard, Reports) and attached to the Aprizely project; the store is append-only so they cannot be removed.","why":"The Screens tab, live board and reports present shots as evidence, so test images in the permanent record mislead anyone who compares before and after later.","how":"Add a test stage that is excluded from compare pairing and public galleries by default, have the CLI refuse to attach test uploads to a real project unless explicitly forced, and require the report to say when shots are synthetic."},{"app":"cross-cutting","category":"dx","session":"238f3801","source":"daily-read","title":"Replace hand-bumped ?v= cache stamps with content hashes at deploy time","detail":"Across Aprizely, Breadcrumb and Hallalu the asset version is bumped by sed (v23 through v28 in the sampled sessions), one Calm-view redeploy reused ?v=26 with changed CSS, and on Remembrance a stale-page theory was offered before the real cause was found.","why":"Manual stamps are forgotten or reused, and the symptom looks like a logic bug, so people debug the wrong thing.","how":"Add a predeploy script that appends the first 8 hex characters of each asset's SHA-256 to its script and link tags in app.html, and serve the HTML itself with no-cache through _headers."},{"app":"Aprizely","category":"integrity","session":"cd37da75","source":"daily-read","title":"Fail closed when the pepper secret is missing instead of hashing without it","detail":"The first Aprizely deploy went live before APZ_PEPPER was set (the secret was uploaded after the deploy), and passcodes are hashed with PBKDF2 plus that pepper; an account created in the gap would have been hashed differently from every later login.","why":"A silently missing pepper creates accounts that can never log in once the secret is added, and the pepper is already flagged as impossible to rotate.","how":"Return 503 from the auth entry points when env.APZ_PEPPER is absent or shorter than 32 characters, put set secrets before the first deploy in the new-app checklist, and add the same guard to every Worker that uses the Finished-style pad."},{"app":"cross-cutting","category":"dx","session":"3e50ec98","source":"daily-read","title":"Add a free-disk preflight and alert before long agent runs","detail":"Recurring disk-full events on the Mac (Cursor state.vscdb around 13 GB, the Claude VM bundle, a phantom Adobe registry, TCC-hidden Photos libraries) end in ENOSPC, where Bash and file-write tools cannot even create their own output files, so an agent cannot save results or clean up; a curation run was stuck unable to write its JSON.","why":"The failure appears at the end of long runs, after the expensive work, and the tools give no warning beforehand.","how":"Start /showwork, /deepscan and the curation scripts with df -h and stop with a clear message below roughly 5 GB free; write results incrementally to a small file early; keep a monthly reclaim checklist (sudo du for hidden folders) in the ledger DX notes."},{"app":"cross-cutting","category":"dx","session":"2c2a51fc","source":"daily-read","title":"Prune and consolidate the 3,412-rule settings.local.json permission allowlist","detail":"While diagnosing a Claude Code crash (an out-of-memory kill logged by ReportCrash after a macOS update) settings.local.json was found holding 3,412 accumulated allow rules, roughly one per approved command.","why":"A giant allowlist adds load and memory cost, hides risky entries among thousands of one-off commands, and keeps approvals meant for a single task alive forever.","how":"Collapse repeats into a few prefix wildcards for known-safe CLIs, drop rules that embed literal paths, ids or secrets, run a quarterly pruning script, and keep high-risk commands out of the allowlist."},{"app":"cross-cutting","category":"workflow","session":"0ad8bea4","source":"daily-read","title":"Give every append-only writer (PatentCake, Bug Ledger, Aprizely) a dry-run preview","detail":"The PatentCake triggers reject UPDATE and DELETE, so the first filing locked in a truncated slug permanently; the same irreversibility applies to Bug Ledger entries and to Aprizely reports and shots.","why":"With no undo, the only safe place to catch a bad slug, title or severity is before the write.","how":"Add --dry-run to pc.mjs, worklog.mjs and apz.mjs that prints the exact payload and derived identifiers and exits without posting, and have agents run it first whenever a field is auto-derived."},{"app":"Hallalu CRM","category":"ux","session":"d8a2d889","source":"daily-read","title":"Auto-segment and punctuate dictated text from Chrome speech recognition","detail":"Chrome SpeechRecognition returns long unpunctuated runs, so dictated notes and narrated portal text read as one block.","why":"Unpunctuated text is hard to scan and sounds wrong when read back with speech synthesis.","how":"Use result boundaries and pause timestamps to break sentences, capitalise the first word, add a full stop at pauses over about 700 ms, and offer a clean-up pass the user can accept before saving."},{"app":"Remembrance","category":"design-elevation","session":"1363a864","source":"daily-read","title":"Reusable contested-claims pattern for research and memorial sites","detail":"Remembrance shows a per-entry contested flag, named perpetrators including inter-faith cases, a debate and counter-evidence section, ranges instead of single figures, and explicit labelling of the one continuous annual series (about 13 per day) versus episodic events; the Nigeria framing is shown with ACLED and HRW counter-evidence and a debunked narrative is labelled as such.","why":"Sensitive numbers get quoted without context; building the caveat into the data model keeps every card honest and stops a headline figure outrunning its sources.","how":"Extract the pattern (contested flag plus note, low, high and representative values, basis, perpetrator and sources fields, and a methodology panel) into a Coco module so Payrails-style ranking pages and future research sites start with it."},{"app":"cross-cutting","category":"dx","session":"1363a864","source":"daily-read","title":"When a user says it is not working, reproduce under their conditions before blaming cache","detail":"On Remembrance the user reported the race and ethnicity buttons as not working after a real mouse click succeeded in the agent's browser; the agent first answered that it was a cached older copy and added no-cache headers, and only later found the page falls back to a stale inline dataset when data.json cannot be fetched.","why":"Dismissing the report as cache cost several rounds and left the user unconvinced.","how":"Check the failure paths first (fetch failure, file preview, a second browser profile, mobile width, the console on a cold load) and only then suggest a hard refresh; state what was and was not reproduced."},{"app":"Breadcrumb","category":"integrity","session":"cd37da75","source":"daily-read","title":"Use Breadcrumb's email-plus-phrase, throttled, self-import-blocked pattern for every account import","detail":"Breadcrumb recovery phrases are salted PBKDF2 hashes, so the new import-from-another-account endpoint takes the source email and the phrase, runs the same lockout gate as sign-in, blocks importing your own account and copies rows with new ids without touching the source. Aprizely's import finds the source account from the phrase alone, which depends on a deterministic recovery-hash lookup (recalled in-session, not re-verified).","why":"Phrase-only lookup turns recovery phrases into search keys and removes the account identifier from the check; the email-plus-phrase design keeps hashes salted and throttles guessing.","how":"Review Aprizely's /api/import/account against Breadcrumb's: confirm how the phrase is matched, require the handle as well, apply the shared gate and lockout, cap rows copied and report any skipped rows, and reuse the same checks in future imports."},{"app":"Breadcrumb","category":"workflow","session":"cd37da75","source":"daily-read","title":"Mint agent keys through the app's device-connect flow, not a direct production D1 insert plus temp files","detail":"To make the live board work without approval, a Breadcrumb ingest key was generated in a shell, its hash inserted into the production ingest_keys table with wrangler d1 execute --remote, and the plaintext written to /tmp/bc-key.txt before being copied to the local key file.","why":"Direct production writes bypass the app's own audit and revoke paths, and a plaintext key left in /tmp is readable by other local users until it is deleted.","how":"Use the existing device-connect approval (one click) or an authenticated mint endpoint that returns the key once, write it straight to a mode-600 file, delete any temp copy, and record the key label so it can be revoked from the app."},{"app":"Finished.","category":"ux","session":"61999ed8","source":"daily-read","title":"Show a live preview of the thing being edited at the top of its editor modal","detail":"The block editor gained a live preview card (real block with the chosen colour, fill pattern, emoji and highlight) above the controls; the Settings 'Slot style' chips were replaced by the same visual fill cards.","why":"The owner said colour and theme options felt missing even though they were present; a live preview makes every choice tangible and prevents a 'where did it go' report.","how":"Render the same component used on the grid inside the modal, bind it to the draft state so it re-renders on every change, and reuse the preview cards for the equivalent settings control."},{"app":"Finished.","category":"ux","session":"61999ed8","source":"daily-read","title":"Settings anchored popovers overflow narrow viewports: use a centered modal for wide panels","detail":"A 660px right-anchored settings popover opened from the gear overflowed the left edge on a narrow viewport; the panel was converted to a centered modal opened by the gear (the app's established pattern).","why":"A wide panel that must be reachable only from one icon cannot rely on anchor geometry on phones; inline rendering also pushed the grid down.","how":"Render big settings in the shared modal component with a click-away backdrop, keep the gear as the only entry point, and verify at the narrowest supported width."},{"app":"Stepapa","category":"integrity","session":"c73f3217","source":"daily-read","title":"Default the daily step goal from evidence (7,000), not the 10,000 marketing number","detail":"10,000 steps is the brand name of a 1965 Yamasa pedometer; Lancet Public Health 23 Jul 2025 (57 studies) found benefits inflect at 5,000-7,000 steps with 7,000 linked to 47% lower CVD death versus 2,000. The app ships a 7,000 default with the source shown.","why":"The bestseller number is folklore; a goal the user can reach and trust is the product's whole premise of personal, honest numbers.","how":"Pick a default from primary research, label it FACT with the citation in the research notes, and let the user change it while keeping the evidence one tap away."},{"app":"Stepapa","category":"ux","session":"c73f3217","source":"daily-read","title":"Dashboards should show a personal baseline band with the user's daily points, not a population target line","detail":"Research on Gentler Streak (Apple Design Award 2024) and sports-science sources showed population norms are often the wrong comparison; the analytics dashboard was built on a personal baseline band instead of a global target.","why":"A personal baseline never shames rest days and matches the product thesis that your own gait and pace are the reference.","how":"Compute a rolling personal median and band from the user's own history and plot daily points against it, with no streak-shaming copy."},{"app":"Stepapa","category":"dx","session":"c73f3217","source":"daily-read","title":"Scripted pbxproj edits: assert the anchors before writing and scope replacements to one target","detail":"A global string replace injected the app's entitlements line into the widget target's build configurations and an assert placed after the write masked it; a substring filter earlier removed GENERATE_INFOPLIST_FILE lines.","why":"pbxproj edits fail silently (a wrong target still builds) and corrupt several configurations at once.","how":"Back up the file, assert the expected count of anchor matches per target before writing, scope each replacement to the target's configuration block, and re-assert the critical keys (GENERATE_INFOPLIST_FILE, entitlements) after."},{"app":"Joy","category":"workflow","session":"3a6f2186","source":"daily-read","title":"When reddit.com refuses, use the PullPush and Arctic Shift archive APIs for voice-of-customer research","detail":"A customer-voice subagent could not open reddit.com, G2, Quora or YouTube, but two Reddit archive APIs (PullPush and Arctic Shift) returned real threads current to the day; PullPush rate-limited, so the downloaded corpus was re-searched locally instead of re-querying.","why":"Earlier studies recorded 'Reddit blocked' and went without a Reddit voice; archive APIs close that gap with real comments and scores.","how":"Query the archive API per keyword, save the JSON corpus to the study folder, re-search it offline, cite the thread permalinks, and tag each quote SIGNAL unless corroborated; re-open any Trustpilot quote that came through a summarising fetch tool before reuse."},{"app":"Joy","category":"integrity","session":"3a6f2186","source":"daily-read","title":"Republish dashboards and recaps after the last research lane lands, or stamp them preliminary","detail":"The research dashboard and Breadcrumb recap were published before the customer-voice lane finished and kept the earlier ranking (loudest hate and loves re-ordered once the final lane arrived); the copy of REPORT.md sent earlier was also stale.","why":"Three published artifacts disagreed with the study folder until the user was told; the verdict held but the ranking they showed did not.","how":"Gate publishing on all lanes returning, or label outputs 'preliminary - lane N pending' and re-publish the dashboard URL and recap in place when the last lane folds in."},{"app":"cross-cutting","category":"integrity","session":"25fc73ab","source":"daily-read","title":"State what a plan multiplier applies to: Max 5x/20x is per 5-hour session, not total weekly capacity","detail":"Counter-evidence kept in the report: the 5x/20x multipliers apply to the 5-hour session cap, so the effective weekly boost is about 3.5x (Max 5x) and 6-8x (Max 20x); Anthropic published weekly hour ranges in July 2025 then removed them; a June 2026 class action alleges deceptive marketing over exactly this.","why":"A flat-vs-metered comparison that treats the headline multiplier as total capacity overstates the subscription's value and reads as a marketing claim.","how":"In any subscription-vs-API calculator or report show the per-session and per-week limits separately, tag the weekly numbers SIGNAL unless the vendor publishes them, and lead with the monthly-recurring versus one-time-top-up difference."},{"app":"cross-cutting","category":"dx","session":"1fe195d5","source":"daily-read","title":"CDP screenshot scripts must pick the page target, not targets[0] (the Omnibox popup is often first)","detail":"A hand-rolled Chrome DevTools screenshot script attached to targets[0] of /json and hung with an empty shots folder; selecting the target with type 'page' that is not the Omnibox popup fixed it, after a stuck background task had to be stopped and the debug-port Chrome killed.","why":"Headless/remote-debugging Chrome lists several targets (omnibox, extensions, service workers); capturing the first one produces silent empty output that reads as a slow render.","how":"Filter targets by type==='page' and exclude title /Omnibox/, log the chosen target's title and url, poll for the PNG instead of waiting on process exit, and kill the profile's Chrome before re-running."},{"app":"Hallalu CRM","category":"integrity","session":"1d92f8fb","source":"daily-read","title":"State plainly which platforms a link-fetch cannot read instead of faking a bypass","detail":"The 'Study a video' paste-a-link flow fetches any public file (direct mp4, Vimeo, many blogs, some LinkedIn/Threads) and tells the user that TikTok, Instagram, Threads and YouTube hide the file behind their player and that a Worker cannot run a yt-dlp-style extractor, so they should download the clip and drop the file in.","why":"A silent failure or a fake 'fetched' state on blocked platforms would read as a bug; an honest boundary note on the landing view turns it into a clear next step and keeps the feature trustworthy.","how":"Show the boundary note beside the link field, report per-URL why no file was found, and always offer the upload/drag-and-drop path as the guaranteed route."},{"app":"Hallalu CRM","category":"architecture","session":"1d92f8fb","source":"daily-read","title":"Do media decoding in the browser and keep Workers AI for model calls: audio chunks + one frame per second, then Whisper and Llama vision","detail":"The video-study engine decodes audio and grabs a frame per second in the browser, detects cuts for the shot map, sends chunked audio to Whisper (offset-stitched) and each frame to Llama 3.2 vision on the AI binding, then makes one synthesis call and falls back to a no-AI structural teardown when the AI is off.","why":"Workers cannot run ffmpeg-style extraction; moving decode client-side keeps the Worker within CPU limits and makes the heavy model work free-ish, high-volume and keyless.","how":"Extract audio/frames with Web Audio and canvas, normalise nested Whisper segments[].words[] on the server, degrade per frame when vision errors (8007/3030) and keep the transcript-only shot."},{"app":"Hallalu CRM","category":"dx","session":"1d92f8fb","source":"daily-read","title":"Prove Workers AI model shapes with a wrangler dev --remote harness before shipping, not from the docs","detail":"With no admin session available, a throwaway remote-dev harness exercised the real Whisper and Llama 3.2 vision bindings and found two schema bugs the docs and tutorial had misled (word timestamps nested in segments[].words[]; image requests need prompt, not messages) plus a false-positive 8007 NSFW rejection on a plain red square.","why":"Unit checks and rendered UI had all passed; only the real binding exposed the shape mismatches that would have blanked every shot's spoken line and failed every frame.","how":"Start wrangler dev --remote on a spare port with a tiny /t/* route per model, send a spoken sentence and a benign generated image, assert the response keys, then delete the harness and record the proven shapes."},{"app":"Joy","category":"integrity","session":"3a6f2186","source":"daily-read","title":"Record share-link opens and downloads with time, kind and file name only - no IP or identity","detail":"Joy Cloud link activity stores each open/download with its time, kind and file name and nothing about who (no IP address), and shows 'Opened 3 times - 1 download - last Oct 1' or 'Not opened yet' beside the link and inside the mail thread.","why":"The top unmet need was a link that confirms it landed; it can be delivered without collecting personal data, which keeps the privacy positioning honest.","how":"Log events with token, kind, file id and timestamp only, derive counts from the event table, and exclude owner previews with an explicit preview flag."},{"app":"Abba","category":"dx","session":"1fe195d5","source":"daily-read","title":"Verify a fixed overlay with an elementFromPoint overlap sweep across pages and viewports","detail":"For the heart-never-covers-info request, an overlap sweep on the dashboard and badges pages found zero page elements under the heart at desktop and mobile sizes after the title rows reserved a gutter for it.","why":"Eyeballing a screenshot misses content hidden under a fixed button at one width; the sweep makes 'never covers info' a measurable check.","how":"For each route and viewport, sample the overlay's bounding box, collect elementsFromPoint at its corners and centre, and fail when any non-overlay content element is returned."},{"app":"cross-cutting","category":"accessibility","session":"research-2026-10-04","source":"WebAIM Million 2025","title":"Ship against the six WCAG failures that are 96% of all a11y errors","detail":"WebAIM Million 2025: 94.8% of pages fail WCAG. Six issues = 96% of all errors: low-contrast text (79.1%), missing image alt (55.5%), missing form labels (48.2%), empty links (45.4%), empty buttons / icon-only buttons with no accessible name (29.6%), missing <html lang> (15.8%).","why":"Fixing just these six moves a product from inaccessible to broadly usable; they are cheap and the same list 5 years running.","how":"Contrast >=4.5:1 for body text; alt on every content image; label every input; no empty <a>/<button>; aria-label on icon-only buttons; set <html lang>. Run the A11Y-* detectors on every build."},{"app":"cross-cutting","category":"architecture","session":"research-2026-10-04","source":"Cloudflare Workers quota docs / eastondev 2025","title":"Cloudflare free-tier 100K requests/day is ACCOUNT-wide, shared across ALL Workers","detail":"The 100K req/day free limit is per-account, not per-Worker. A portfolio of 30+ Workers on one account shares a single 100K bucket; KV reads/writes and Cache API ops also count as requests.","why":"Directly relevant: this account runs ~34 Workers. One chatty Worker (polling, hourly crons, live boards) can starve the rest and cause account-wide 1015/quota errors.","how":"Budget requests across the portfolio; cache aggressively; avoid per-second polling and chatty KV; move hot paths to paid or to static assets; watch the account request graph."},{"app":"cross-cutting","category":"dx","session":"aa7b3b11","source":"daily-read","title":"Test a new data-act value against the click-delegate switch with a script that lists every data-act in the markup and the cases handled","detail":"After adding cards and views the session found two buttons wired to an action name no handler knew, only by luck of a grep","why":"Delegated-click SPAs fail silently on an unknown action; there is no error to see","how":"CI/pre-deploy check: collect all data-act values from public/*.js templates, diff against the case labels of the delegate, fail on any orphan"},{"app":"Hallalu CRM","category":"design-elevation","session":"aa7b3b11","source":"daily-read","title":"Use Workers AI FLUX schnell only for photographic mockups and hand text-heavy products to a text-capable model or an editor","detail":"The photo-proof test produced a convincing flat-lay but garbled text ('birthdy withdAY'); the caveat and Canva hand-off carry the expectation","why":"Users judge a proof by its readable copy; garbled lettering reads as broken","how":"Say 'look, not copy' on the result, offer a sharper-text model as a toggle, and overlay real headings with a canvas compose step"},{"app":"Joy Day","category":"dx","session":"aba97122","source":"daily-read","title":"Move Joy Day off its hand-patched auth-gate (CSS-hidden tabs, prefilled hidden identifier) onto the module passcode mode that shipped later","detail":"On 6 Sep Joy Day used the full sign-up/sign-in card as a one-person PIN pad by hiding the segmented tabs with CSS, hiding the identifier field and prefilling it because sign-in refuses an empty identifier, and making the fixed overlay backdrop transparent, across three patches. On 1 Oct auth-gate v1.1 gained mode passcode (v1.2 adds remember-me and forgot), which Joy mail uses","why":"A hidden-but-required field and CSS overrides break on the next module update, and Joy Day does not get remember-me or the shared lockout behaviour","how":"Replace the three patches with FinishedAuth.mount(..., {mode:\"passcode\", pinLength:6, onPasscode}), keep the HMAC session, and add the per-IP failure counter the Joy mail worker uses"},{"app":"cross-cutting","category":"integrity","session":"aba97122","source":"daily-read","title":"Assert that a gauge's drawn fraction equals the number printed inside it, since 59 green tests still shipped a ring that contradicted its label","detail":"The ring filled as Neurons were spent while the centre number counted down what was left; only looking at the page found it, after which a test reading the stroke-dasharray from the HTML was added","why":"Unit assertions on numbers cannot see a visual encoding that disagrees with its label","how":"For every gauge, bar or ring: render, read the drawn length, and assert it equals the printed value over the maximum, in the empty, full and over-limit cases"},{"app":"Sell skill","category":"workflow","session":"5bd3b322","source":"daily-read","title":"Fold per-run composer fixes back into the skill's compose.mjs or the next project re-fixes them","detail":"The receipt chip, sideways scrim, code block and seam fix were written into the project folder's compose.mjs only; the skill's copy stays without them","why":"Each /sell run re-discovers the same layout defects (12 fixed over four render passes) and the ledger already holds several for this file","how":"At the end of a run diff the project composer against the skill copy, port the generic changes behind options, and bump a header version so agents can tell which copy they hold"},{"app":"cross-cutting","category":"workflow","session":"ca3adf13","source":"daily-read","title":"When a command needs the user's sudo, have it write to a file the agent reads instead of asking for a paste","detail":"read_terminal could not see output that had scrolled past, and pasted blocks arrived truncated or empty; a command that ends with '> /tmp/x.txt; echo done' let the agent read the whole result directly","why":"Each paste round trip cost minutes to hours of wall-clock in a disk-full emergency","how":"Standard form: sudo CMD 2>&1 | head -N > /tmp/NAME.txt; echo 'written, say done'; then Read /tmp/NAME.txt; keep the first command small and the file path stable"},{"app":"Bug Ledger","category":"integrity","session":"5f9a4f4e","source":"daily-read","title":"Cluster near-duplicate catalogue items into canonical classes with per-app instances so coverage is not padded","detail":"A deep scan reported 67 security items that are really about 30 concepts: SSRF three times, XSS five or more, cross-account local leak five or more, CSP twice. Each item was the same class first seen in a different app, so a pass counts variants separately and inflates both effort and apparent thoroughness","why":"Coverage numbers are only meaningful per distinct risk","how":"Add a class key on every item, report 'N classes checked, M instances', and let one detector or one test answer a whole class"},{"app":"Bug Ledger","category":"integrity","session":"5f9a4f4e","source":"daily-read","title":"Add a per-project applicability fingerprint so the checklist marks items with no matching surface as N/A instead of a hollow pass","detail":"About 15 of Hallalu's 67 security items concern other apps' features (co-stitch rooms, a cloud vault, a render path) yet were weighted equally and ticked","why":"A pass on something that cannot apply tells the reader nothing and dilutes the items that do","how":"Declare has-auth, has-vault, has-AI, has-D1, static-site and similar flags per project, tag items with the surfaces they need, and show non-matching items as N/A with the reason"},{"app":"Bug Ledger","category":"integrity","session":"5f9a4f4e","source":"daily-read","title":"Match coverage on a stable item id and re-run a detector signature to prove a fix and flag regressions","detail":"Coverage matches normalised title strings, so credit required reverse-engineering the exact catalogue wording; a submitted fix with file:line is taken on trust and nothing watches whether it stays fixed","why":"Title matching rewards string gaming, and found-once is not the same as stays-fixed","how":"Give every item an id used for matching, attach a detector signature, re-run it when a fix is submitted to confirm the pattern is gone, and flag a regression on any later scan where it returns"},{"app":"cross-cutting","category":"dx","session":"0c4410c7","source":"daily-read","title":"Receive-path smoke test for Email Routing: SMTP to route1.mx.cloudflare.net over IPv4 from a sender domain with no SPF","detail":"A hand-rolled node:net SMTP session was rejected with 550 'Sender IP reverse lookup rejected' because the connection left over IPv6 without reverse DNS; forcing family:4 delivered, and a sender domain with no SPF record (result none) was accepted. Cloudflare's inbound MX rejects an IPv6 sender with no rDNS and hard-fails only on failing SPF or DKIM, which makes a 40-line script a repeatable end-to-end test of catch-all, Worker, R2 and D1","why":"Proves the whole receive pipeline without needing a second mail service","how":"Open the socket with family 4, use a MAIL FROM on a subdomain with no SPF record, poll the authenticated messages API for the marker, then delete the test row"},{"app":"Joy Docs","category":"dx","session":"0c4410c7","source":"daily-read","title":"Send X-Robots-Tag noindex on public share-by-link doc Workers so a hand-out link is not crawled","detail":"joy-docs serves the Handbook and the market dossier from a public static-assets Worker so one link works for everyone, with no auth and no robots header; the pages name the live webmail URL, the mail domain and the architecture","why":"A share link intended for a few readers becomes a search result; the same applies to every static docs Worker in the portfolio","how":"Add a _headers file with X-Robots-Tag: noindex, nofollow and Referrer-Policy: no-referrer for /*, or a robots.txt Disallow, and keep an opt-in public flag per doc"},{"app":"Joy Day","category":"integrity","session":"aba97122","source":"daily-read","title":"Copy the vendor's published unit (Neurons) and derive money from it, never re-derive the unit from rounded dollar figures","detail":"Cloudflare lists both a dollar rate and a Neurons rate; flux-2-dev's rounded $0.00041 implies 37.27 N while the published column says 37.50, and input tiles were priced separately from output tiles","why":"A rate card that disagrees with the vendor's own unit in the third significant figure makes every derived scenario, projection and budget slightly wrong, and the error compounds with volume","how":"Store the published Neurons column verbatim with a read date and source URL, compute dollars at request time from one overage constant, and add a test that recomputes each model's cost by hand arithmetic"},{"app":"cross-cutting","category":"dx","session":"a15dff44","source":"daily-read","title":"Verify a Supabase-gated app locally by seeding the REAL auth storage key with a far-future expiry and the anon key as the access token","detail":"Seed localStorage key sb-<project-ref>-auth-token with expires_at far in the future and access_token set to the project's publishable key. getSession() then returns without a network call and edge-function gateways that verify the JWT accept it.","why":"A made-up key name passes the 'entered' check but cloud.ts raises the auth-expired event and flips the gate back; a token of 'f' makes background calls 401 and bounces to the sign-in screen.","how":"Write the seed in one javascript_tool call on the dev origin, reload, and treat any 401 from your own edge functions as 'needs a real session' rather than a bug. Never create accounts or type PINs."},{"app":"cross-cutting","category":"dx","session":"a15dff44","source":"daily-read","title":"Drive React forms from the Browser pane by dispatching events, and read state instead of trusting focus","detail":"Automation 'type' ignores programmatic focus and caret moves done in requestAnimationFrame, the Return key does not fire React onKeyDown, and same-tick clicks are batched so the DOM is stale between them.","why":"Caret-insert and keyboard shortcuts looked broken or fine for the wrong reason during verification.","how":"Set values with the native setter plus a bubbling input event, dispatch a real KeyboardEvent for Enter, click once per call, and assert on textarea.value and selectionStart."},{"app":"Finished.","category":"architecture","session":"a15dff44","source":"daily-read","title":"Make a monthly grant idempotent by putting the period in the ledger reason and indexing it","detail":"Use reason 'monthly-free:2026-08' with a partial unique index on (user_id, reason) where reason like 'monthly-free:%', insert ... on conflict do nothing, and bump the balance only if a row was actually inserted (GET DIAGNOSTICS row_count).","why":"date_trunc is not immutable so it cannot sit in an index expression; the reason string carries the period and makes concurrent or repeated calls safe and auditable.","how":"Call ensure_monthly_free() lazily from the balance RPC so no cron is needed, and skip it in a month that already has a welcome or renewal grant."},{"app":"cross-cutting","category":"dx","session":"a15dff44","source":"daily-read","title":"Test SECURITY DEFINER functions through execute_sql by setting request.jwt.claims to a real user","detail":"select set_config('request.jwt.claims', json_build_object('sub', <real uid>)::text, true) then call the function in the same statement batch.","why":"The function reads auth.uid(); foreign keys need a real user; RAISE NOTICE output is not returned and a rollback cannot span separate calls.","how":"Pick a throwaway real user, assert results with select statements, and make the function idempotent so re-running is safe."},{"app":"Finished.","category":"performance","session":"a15dff44","source":"daily-read","title":"Lazy-load big word lists: dynamic import for bundled banks and fetch-on-open for the 60k dictionary","detail":"The 24k-word bundle added about 46KB raw / 19KB gzip to the main chunk until it was split; the 60,000-word A-Z list ships as public/dictionary.txt (about 500KB) fetched the first time that level opens and merged with curated entries (curated definitions win).","why":"Keeps first load small while the library still reaches dictionary scale.","how":"Show a 'Loading the full dictionary' note in the plan line while it fetches; connect-src 'self' already allows it."},{"app":"Finished.","category":"ux","session":"a15dff44","source":"daily-read","title":"Forgiving pronunciation scoring: phonetic match, bands, unlimited retries and a self-rate fallback","detail":"Score with Double Metaphone plus Levenshtein, never exact match; give bands not pass/fail; allow unlimited retries with a TTS model; offer self-rating when the microphone or speech API is unavailable; show an improvement chart instead of streak pressure.","why":"Speech-recognition error rates are roughly double for some accents, children and non-native speakers, so exact match punishes the learners the app is for.","how":"Keep the scorer in readscore.ts, feed the same score log to XP, the league and the progress dashboard."},{"app":"Finished.","category":"design-elevation","session":"a15dff44","source":"daily-read","title":"Homework runway bar from date assigned to due date, with colour never carrying meaning alone","detail":"Draw the assignment window as a bar with today's marker, days left and a text label; pair every colour state with a word or icon (WCAG 1.4.1).","why":"Shows pacing at a glance and works for colour-blind users.","how":"Compute progress from assignedAt and dueAt in the schedule model and reuse the bar in the list, calendar and widget views."},{"app":"Finished.","category":"integrity","session":"a15dff44","source":"daily-read","title":"When asked for '1,000+ per section', publish the honest count against the real full-suite size and let the owner choose","detail":"A per-section audit table (for example GRE 3,500 canonical, GMAT 750 to 1,000, Latin phrases 300 to 500 authentic, literary terms 300 to 500 real) replaced padding; the owner then chose which gaps to fund.","why":"Padding with shared banks produced 'dead' in SAT and 'able, about, above' in Travel, which users noticed immediately.","how":"Count by real membership, flag padded levels, and decline to invent entries; stop at the honest number and say so."},{"app":"cross-cutting","category":"dx","session":"a15dff44","source":"daily-read","title":"Test third-party fetches under the production CSP with vite preview, not the dev server","detail":"Keep a launch.json entry that serves the production build with the real public/_headers (a prod-csp configuration) and run new network features through it.","why":"Dictionary and translate APIs worked on the dev server and would have been blocked in production by connect-src.","how":"Add each new origin to connect-src in the same commit as the fetch, then verify under the preview."},{"app":"Finished.","category":"ux","session":"a15dff44","source":"daily-read","title":"Adaptive practice from the score log: missed words first, then unseen, close, mastered; soft league tiers without demotion","detail":"Order the queue 'again', unseen, 'close', 'nailed' with a stable sort after shuffling; show Bronze to Diamond tiers by weekly XP with an 'XP to next tier' bar and no demotion.","why":"Resurfaces what the learner needs without extra data; gentle tiers motivate without punishing.","how":"Build the queue from stored scores on level change and once after scores load for a returning learner."},{"app":"Finished.","category":"ux","session":"a15dff44","source":"daily-read","title":"Timed quiz that works under real test conditions: Quick-start, save and resume, deadline auto-score, and choose/type/speak answers","detail":"One-tap Quick start picks length, mix and answer mode; the quiz state persists so it can be resumed; a 1 hour, 1 day or 1 week deadline auto-scores completed answers; meaning answers can be chosen, typed or spoken and matched with a lenient content-word matcher.","why":"Lets learners rehearse exam pacing while still fitting life, and feeds the same XP and league as practice.","how":"Persist quiz progress to localStorage (and sync it if cross-device resume matters), and reuse the speech helpers."},{"app":"Finished.","category":"dx","session":"a15dff44","source":"daily-read","title":"Ship the generator and source packs beside generated data files","detail":"vocab-extra.ts says 'do not hand-edit, regenerate via gen-extra.mjs' but the generator, the researched lists, build-dict.mjs and words_alpha.txt lived only in a session scratchpad and /tmp.","why":"Scratchpads can be wiped, which leaves a 3,763-line generated file nobody can regenerate or audit.","how":"Commit scripts/ with the generator and a SOURCES.md (origin, licence, date) for every pack; keep large raw downloads out of git but record their URLs and hashes."},{"app":"cross-cutting","category":"dx","session":"a15dff44","source":"daily-read","title":"Unit-test pure parsing code by esbuild-bundling the real source and importing it from a data: URL","detail":"Bundle src/lib/timetable.ts with esbuild (platform neutral, localStorage shim), import the result via a base64 data: URL and run a fixture table.","why":"Six spoken-day fixtures (run-on, no-time list, ranges, bare times, food safelist, '3 apples') found four splitter bugs in minutes without a test framework.","how":"Keep the fixture table in the repo and rerun it after every parser edit."},{"app":"Finished.","category":"ux","session":"a15dff44","source":"daily-read","title":"Speech capture should land in an editable review step, never auto-commit","detail":"Open a review modal that starts listening, shows Speak / Pause / Resume / Done, keeps the transcript editable and previews the split before adding; offer an optional gated AI tidy (canUseAI and credits) beside rule-based defaults.","why":"Recognition errors are common and the owner could not correct them when dictation auto-added blocks.","how":"Reuse the shared useDictation hook for the block editor, bulk add and the day dump; keep rules as the free default."},{"app":"Finished.","category":"design-elevation","session":"a15dff44","source":"daily-read","title":"Make rule-based design the default: category-driven fills and colours with a Settings tick, AI as an optional upgrade","detail":"A category-to-pattern map (dots, stripes, crosses, confetti, emoji) plus colour and emoji from keyword rules makes a day look designed with no AI call; AI only improves it.","why":"Free users get a finished look and credits are not spent on cosmetics; a tick lets people choose a flat style.","how":"Resolve the fill at render time through one helper (blockFill) so it never needs a data migration."},{"app":"Finished.","category":"architecture","session":"a15dff44","source":"daily-read","title":"Pass the 12/24-hour format as a parameter or context instead of a module-level flag set during render","detail":"fmtTime reads a module-level FMT24 set by setFmt24(!!s.hour24) inside the Timetable render body.","why":"Memoised children and any other importer of fmtTime can show a stale or foreign format; it only works because the whole tree re-renders.","how":"Give fmtTime an explicit h24 argument (already supported) and thread the setting through props or a small context."},{"app":"cross-cutting","category":"workflow","session":"a15dff44","source":"daily-read","title":"Give every Worker a never-cached /api/_v route, version static asset paths by content hash, and verify deploys against both","detail":"A probe route that returns a build marker proves worker code is live; rewriting asset URLs to /_v/<hash>/file gives every release a new cache key; compare the served file's sha with the local sha.","why":"wrangler's Success output and the deployments list said nothing about stale static files, and a hand-bumped ASSET_VER is easy to forget.","how":"Derive the version from a hash of public/ at build time, keep the shell HTML no-cache, serve /_v/* as immutable, and add the probe check to the deploy script."},{"app":"Aprizely","category":"ux","session":"a15dff44","source":"daily-read","title":"One timeline for all work: agent sessions itemised by wave, manual timers and payments on a per-day analysis","detail":"Work Log shows each agent board with its tasks and descriptions, project link, time and duration, above a per-day bar chart of focused time with spend markers and a week graph on top.","why":"The owner wanted a single place to see what was achieved, for which project and when, instead of two disconnected lists.","how":"Merge S.sessions and S.worklogs by day in the client, label agent duration as started to finished-or-updated, and flag boards left active as unreliable."},{"app":"Aprizely","category":"ux","session":"a15dff44","source":"daily-read","title":"Voice-fill forms with a rule-based parser and a visible 'heard' line","detail":"A mic on the payment and cost forms parses spoken amounts (digits and number words), relative dates, project and note into the fields without AI.","why":"Voice that only dumps text into a box feels broken; filling fields is what the owner asked for.","how":"Strip number words from the note, show what was heard, and test the parser with fixtures like 'twenty five dollars for Cloudflare hosting today'."},{"app":"Aprizely","category":"ux","session":"a15dff44","source":"daily-read","title":"Timestamp every shipped item and add a deterministic Fathom-style day summary","detail":"Each feature, fix and session row shows its clock time, and the day report opens with a plain-English TL;DR (counts per project, focused time, first and last activity) built without AI.","why":"The logs.at timestamp already existed but was not shown; a short summary answers 'what did I ship today' at a glance.","how":"Compute from the day's events, keep it deterministic, and list timestamped highlights under it."},{"app":"Finished.","category":"design-elevation","session":"a15dff44","source":"daily-read","title":"Help as a full page: FAQ accordion plus contact form, with the textarea resize grip removed","detail":"A two-column help centre (common questions and a message form) replaced a small modal; resize: none and a proper focus ring remove the diagonal grip that looked unfinished.","why":"The owner called the small box low standard and the corner dashes unpolished.","how":"Stack the columns on mobile, keep Question / Bug / Suggestion / Other kinds, and send to a table that someone actually reads."},{"app":"Finished.","category":"integrity","session":"a15dff44","source":"daily-read","title":"Build language packs from real bilingual dictionaries with readings, and eyeball every generated pack before bundling","detail":"Chinese from CC-CEDICT with tone-marked pinyin, Japanese from EDICT2/JMdict with Hepburn romaji (EUC-JP converted with iconv), French/Spanish/German/Italian from FreeDict TEI streamed line by line (the German file is 449MB), each intersected with a frequency list so common words come first.","why":"Bare frequency words taught nothing, and an LLM-written list of the same size was less accurate; sampling caught a leaked '(P)' marker in the romaji.","how":"Parse into { w, d } with the meaning, strip markers, print 20 samples per language, and check licences and a profanity filter before shipping (see the licensing entry)."},{"app":"cross-cutting","category":"dx","session":"f256d011","source":"daily-read","title":"After a deploy, prove the browser loaded the new build before testing it (and curl with a unique query first)","detail":"In one session the Browser pane served the previous index.html after a successful wrangler deploy on more than ten occasions (v97 vs v98, v119 vs v120, v147 vs v148, v151 vs v152, v168 vs v169, v169 vs v170). ?cb= and location.replace(?x=Date.now()) often still loaded the old document; only a brand-new unique URL worked. About ten turns were once spent suspecting wrangler, the wrong directory and a service worker. navigate returns before the old document has finished running.","why":"Verifying against a stale build produces false failures (feature 'missing', 'S is not defined') and false passes, and burns turns.","how":"1) curl the page with a unique query and grep the build stamp (?v=NNN). 2) In the page, assert the loaded script's ?v= equals the expected before running any check, and if it does not, navigate to a never-used URL. 3) When a chart or element looks wrong, measure getBoundingClientRect and the computed style before telling the user to hard-refresh; the 16px chart bug was blamed on cache first."},{"app":"cross-cutting","category":"integrity","session":"f256d011","source":"daily-read","title":"Verify behaviour, visibility and the real route; not element presence, URL strings or function existence","detail":"This run's misses were all presence-level: DM chips shipped dead because the check counted chips (not clicks); a logo img passed because its src string existed while Clearbit was dead; Edit 'existed' in the toolbar while the user could not see it; Preview was closed without reproducing it; a quiet-week state never rendered because the fixture lead had other activity; a persistence probe error was waved off as 'demo save no-ops'. Techniques that worked: dispatch a real input event then read state; Image() onload for third-party URLs; getBoundingClientRect/elementFromPoint at the user's width; a monkeypatched spy on askAI to prove aiCalls:0; decoding the share-link JSON to audit every field; computing contrast in-page.","why":"A check that cannot fail for the bug in question is not a check, and 'verified' in a report then misleads the user.","how":"For each feature, write one assertion that would fail if the user-visible behaviour were broken: click then read state, measure rect and hit-test, spy the side effect, load the third-party asset, and use an isolated fixture for empty and edge states. Also remember harness traps: go(to) takes one arg (use #/client/id), '/' is the marketing page and /app the app, wrap each probe in an IIFE, and navigate to /app before touching S."},{"app":"cross-cutting","category":"integrity","session":"f256d011","source":"daily-read","title":"'Could not verify' from a blocked or exhausted researcher is not 'does not exist'; never remove capability on a negative finding","detail":"A research lane reported it could not verify five effect names while also reporting its web-search budget exhausted (200/200) and bot-gated engines. The names were deleted from the product. All five were real. The user's rule: a critique is a claim too; never invent a restriction.","why":"Absence of evidence from a broken tool becomes a shipped restriction, and the cost is asymmetric when the field is free text (a stale suggestion is free; a missing famous one is not).","how":"Require every lane to report its tool health (searches used, blocked domains) and to label results verified-true, verified-false or unreachable. Only act on verified-false. When a lane is unreachable, re-verify yourself or leave the option in. Add the asymmetry note in code where you keep something you could not verify."},{"app":"cross-cutting","category":"integrity","session":"f256d011","source":"daily-read","title":"Research provenance: say when the primary source was blocked and never present aggregator paraphrase as a quote","detail":"A voice-of-customer lane could not reach Reddit (WebFetch, .json, mirrors and search all blocked) and returned aggregator-sourced paraphrases explicitly labelled as not verbatim Reddit quotes, with zero threads read. A separate counter-evidence lane re-audited the other lanes' own claims and caught four miscitations (a healthcare adoption stat transplanted to freelancer portals; Etsy; follow-up counts; a Flickr study cited as Instagram).","why":"Fabricated or transplanted evidence in a product dossier ends up in shipped copy.","how":"Brief every lane to disclose blocked sources and label FACT / SIGNAL / HYPOTHESIS / VENDOR / FOLKLORE. Add a standing audit lane that opens the cited page for each load-bearing stat and checks the domain, sample and confidence interval. Re-run blocked lanes through a real browser or API."},{"app":"cross-cutting","category":"copy","session":"f256d011","source":"daily-read","title":"Folklore watchlist: never hard-code these statistics or rules in product copy","detail":"Traced or checked this run: '$100 per 1,000 followers' (a 10x inflation of a 2017 Digiday quote of $1,000 per 100,000); '3-5 content pillars' (earliest trace Later 2020; Hootsuite publishes seven; HubSpot gives no number); 5-3-2, rule of thirds, 80/20, 4-1-1 (unattributed); '5-7 follow-ups' (source said fifth to twelfth contact); SMS 98% open rate; '98% WhatsApp open'; deposits cut no-shows 65%; 'post daily or be punished' (unsupported, not disproven); skeleton loaders feel 20-30% faster (spinners tested faster); '94% of first impressions are design' (untraceable; 46.1% defensible); 'filters raise reach' (no credible evidence; the 21% figure is a Flickr study); NN/g 'comprehension halves on mobile' (2010, contradicted by NN/g 2016).","why":"Each of these has been repeated widely and would pass a casual check.","how":"Keep the list in the research skill. For each claim in copy, record the primary source and date, or phrase it as 'no one has shown'. Use measured data where it exists (for example Collabstr, n=21,000 collaborations: paid medians YouTube $255, Instagram $193, TikTok $186, UGC $154; 80% of deals under $300)."},{"app":"cross-cutting","category":"workflow","session":"f256d011","source":"daily-read","title":"Research lanes that spawn their own sub-lanes return 'Holding' as their result","detail":"A premium-design lane completed seven times with results like 'Lanes are still actively researching. Holding.' (about 144k tokens, 22 minutes); its real output came from a different lane. A task-notification fires each time an agent stops with no live children, and TaskStop on a completed task errors. Two other lanes failed mid-flight with 'your computer went to sleep' and two hit a session limit; the assistant correctly reported these as gaps rather than filling them with guesses.","why":"A notification is not a deliverable, and the user lost half an hour to an empty result.","how":"Brief lanes not to spawn agents and to end with a final report; treat any 'holding / still researching' result as a failure and re-run it directly; list failed lanes explicitly in the report."},{"app":"cross-cutting","category":"workflow","session":"f256d011","source":"daily-read","title":"Do not browser-verify while a browser-using subagent is running","detail":"A parallel research subagent drove the shared Browser pane, navigated to buildertrend.com, and took over the main session's verification even in a freshly created tab (S was undefined). The pane also hits a tab cap, times out on scroll and screenshot, and 'zoom' returns the full image.","why":"The agent's page state and the verifier's page state are the same pane.","how":"Wait for browser-using lanes before verifying, or give research lanes WebFetch/WebSearch only; use JS checks instead of scroll/zoom when the pane is unresponsive."},{"app":"cross-cutting","category":"dx","session":"f256d011","source":"daily-read","title":"Lint generated CSS custom-property values: AI-written hex tokens were corrupted three times","detail":"Garbage spliced into colour values: dashboard artifact '--ink-2:#586ersync,#586472' and dark-mode '--win:#2cc1 ae,#2cc1ae'; portal.html '--ink3:#79footer;--ink3:#7c8697'. An invalid custom-property colour silently drops the token. All were caught by eye on self-review; one only hours later.","why":"Silent token loss shows up as odd greys and missing accents, not an error.","how":"Before publishing or deploying, regex every --token value that starts with # against ^#[0-9a-fA-F]{3,8}$ and fail on anything else; also reject duplicate declarations of the same token in one block."},{"app":"cross-cutting","category":"dx","session":"f256d011","source":"daily-read","title":"node --check cannot catch hallucinated helpers or classes; add a no-undef and class-exists check","detail":"portal.js was written against micBtn(), openShareSheet() and a .modal-wide class that do not exist; node --check passed because undefined globals only fail at runtime. It was caught only because the assistant grepped the codebase for each helper before deploying (the real patterns were .mic-in[data-mic-target] with attachMics(), and shareClientSummary()). A half-built registry entry (msgDeposit referenced but never defined) was also self-caught.","why":"Hallucinated APIs pass syntax checks and fail in front of the user.","how":"Run eslint with no-undef (window globals declared) or a script that extracts called identifiers and class names and greps for their definitions; run it as part of the pre-deploy step."},{"app":"cross-cutting","category":"accessibility","session":"f256d011","source":"daily-read","title":"Compute contrast for every text token across every theme and both colour schemes in one script","detail":"A one-off in-page script measured --ink-3 at 2.54:1 on white (WCAG failure) and later caught White 3.03:1, Pastel 3.87:1 and Aurora/Ocean 4.35:1 label text across ten templates. It measured only one scheme, and non-default themes set tokens on :root[data-ptheme] which outranks the plain-:root prefers-color-scheme:dark block, so those themes stay light in dark mode.","why":"Eyeballing greys misses real failures, and a 'light and dark pass' claim needs both measured.","how":"Loop themes x schemes (resize_window colorScheme or emulate), read the computed colour of each text token against its real background, flag anything under 4.5:1 for small text, and decide explicitly whether themes should follow the OS dark setting."},{"app":"Hallalu CRM","category":"design-elevation","session":"f256d011","source":"daily-read","title":"Premium UI tokens from measured CSS of Linear, Vercel, Raycast, Stripe and Notion","detail":"Extracted rather than blog-sourced: text ramp primary 17-19:1, secondary 9-13:1, tertiary 4.5-6:1, quaternary about 3.2-3.5:1 (nobody uses pure black on white; Monday does, at 21:1); borders about 1.2-1.4:1; elevation is a 1px hairline before shadows; radii cluster at 4-8px; motion 100-300ms with one shared easing; slightly negative tracking that scales with size. Myth checks: Linear's type is free Inter plus Berkeley Mono, not custom; its look is not gradient-free (205 gradient declarations); Jakob's Law has no supporting data; Arc was admired but abandoned for a 'novelty tax' (feature adoption as low as 0.40%), so be premium in execution and conventional in structure.","why":"Gives numeric targets for a high-end feel instead of adjectives, and no published A/B test shows distinctive design changes B2B trust either way.","how":"Set the app's ink tiers to the measured bands (Hallalu now: 18.7 / 9.39 / 4.59), keep hairline borders around 1.25:1, and treat the work as craft and accessibility, not a revenue claim."},{"app":"Hallalu CRM","category":"design-elevation","session":"f256d011","source":"daily-read","title":"Pure-white base with aurora washes behind translucent glass cards","detail":"The user rejected an off-white base. The treatment that worked: body background stays #ffffff; a fixed aurora (coral, blue, mint, purple radial gradients) sits behind the page; cards are rgba(255,255,255,.58) with backdrop-filter blur(18px) saturate(1.6), a hairline edge light and a soft shadow; a 3px brand-gradient hairline crowns the page; print overrides make cards solid white. Verified computed body rgb(255,255,255).","why":"Glass needs something behind it to blur; on pure white the aurora layer supplies it, and warmth never tints the base.","how":"Put the aurora on body:before/after, not on the surface; strip aurora, blur and shadows in @media print; keep the same layer for the dark theme at stronger alpha."},{"app":"Hallalu CRM","category":"architecture","session":"f256d011","source":"daily-read","title":"Share one design-token file across standalone share pages so locks (pure white, contrast) are inherited","detail":"portal.html, site.html, kit.html and summary.html are separate documents with their own CSS, so the pure-white lock was lost on the new page and ink tokens had to be fixed again inside it. Contrast fixes in app.css did not reach them.","why":"Every new client-facing page re-derives colours and re-introduces already-fixed mistakes.","how":"Extract tokens.css (colour tiers, radii, motion, aurora layer) and link it from every public page; test them against the same contrast script."},{"app":"Hallalu CRM","category":"architecture","session":"f256d011","source":"daily-read","title":"Backend-free share pages via fragment-encoded JSON: instant and private, but irrevocable","detail":"summary.html, kit.html, site.html and portal.html#<b64> render a snapshot encoded in the URL fragment with no database. The data never touches the server, but there is no revocation and the decode uses the deprecated escape(). The portal added a server-side pid for comments and a published snapshot at /portal.html?p=<pid>.","why":"The tradeoff decides whether a link can ever be taken back.","how":"Keep fragment links for low-sensitivity shares, show a one-line 'this link cannot be withdrawn' note, and use a server pid with unpublish for anything containing money or client detail."},{"app":"Hallalu CRM","category":"integrity","session":"f256d011","source":"daily-read","title":"Auto-assembled client-facing pages should allow known-safe sources and be audited field by field","detail":"The portal first filtered the timeline list, but the 'next' KPI still carried an internal reminder label; it was found only by decoding the encoded snapshot JSON. Messages are behind a per-send toggle, and the owner's own view marks internal rows 'only you see this'.","why":"Private CRM cadence ('Friendly nudge') leaking to a client is the worst failure for this feature.","how":"Build the client snapshot from an allowlist of kinds, add a test that decodes the real link and asserts no internal label, hours or private note appears in any field, and keep a marker on the source events (not a title regex)."},{"app":"Hallalu CRM","category":"integrity","session":"f256d011","source":"daily-read","title":"WhatsApp links: never invent a country code","detail":"waNumber() prefers a WhatsApp-labelled number, then Mobile, then the first phone, and needs 6 or more digits. A number without a country code produces wa.me/?text= (and a toast tip) instead of a guessed prefix, because a wrong prefix messages a stranger. Six cases verified, including wa.me/447700900123?text=Hi%20Maya!.","why":"A confident wrong number is worse than asking the user.","how":"Reuse waNumber/waLink/waOpen from contactfields.js wherever a chat link is built."},{"app":"Hallalu CRM","category":"integrity","session":"f256d011","source":"daily-read","title":"Bank details: store identifiers as strings and validate per country; never put them in a URL","detail":"Researched this run: sort code, BSB, routing number and CLABE keep leading zeros so must be strings; validate an IBAN by country length and MOD-97 but warn rather than block; BIC is optional within SEPA (Regulation 260/2012); a US wire ABA differs from an ACH ABA; show 'verify before the first payment' because invoice-interception fraud is the main risk; use structured fields plus a free-text catch-all. The share-summary snapshot deliberately excludes bank fields.","why":"Numeric storage corrupts identifiers and URLs leak details.","how":"Country-driven fields (paydetails.js, 10 countries) feeding one paymentBlock(); exclude bank data from any shareable snapshot or URL."},{"app":"Hallalu CRM","category":"architecture","session":"f256d011","source":"daily-read","title":"Do not reuse the platform's billing Stripe to collect users' client payments","detail":"Payment reminders and deposits let each user paste their own payment link and bank details (payBlock() appended to the drafts). Using the platform Stripe would route a user's client money to the platform account.","why":"Money would land in the wrong account and create a regulatory problem.","how":"Keep platform Stripe for subscriptions only; use the user's own link, or Stripe Connect when built."},{"app":"Hallalu CRM","category":"architecture","session":"f256d011","source":"daily-read","title":"No-AI path registry for deterministic reports and editable message drafts, with a spy to prove zero AI calls","detail":"avapaths.js is a registry of pure-data reports (pipeline snapshot, income recap, dated follow-up agenda, payment plan, daily brief, win-back) plus honest, editable drafts (payment reminder, no-reply nudge, thank-you, review request without incentives). Drafts are pushed as a separate Ava message so Copy gives a clean draft; follow-on chips are path ids, not AI prompts. A monkeypatched spy on askAI proved aiCalls:0.","why":"Cuts cost and removes hallucination for the common jobs, and respects the draft-and-send, human-in-the-loop house style.","how":"Add new jobs as registry entries that read existing data only (do not fabricate prices that are not stored), reuse renderArtifactDoc, and verify with an askAI spy."},{"app":"Hallalu CRM","category":"ux","session":"f256d011","source":"daily-read","title":"Analysis text that only claims what the sample supports","detail":"The work-log analysis writes plain sentences from the user's own sessions (hours this week vs last, strongest weekday, typical stretch, time per product and client) with guards: strongest weekday needs 5 or more distinct logged days, typical stretch needs 3 or more sessions with segment data, and it says when sessions are not linked to anything. A related analytics sentence at n=1 read awkwardly ('Of the 1 you gave a target, 1 hit it').","why":"Small samples produce confident nonsense.","how":"Gate each sentence on a minimum n, say 'not enough yet' otherwise, and special-case n=1 copy."},{"app":"Hallalu CRM","category":"conversion","session":"f256d011","source":"daily-read","title":"Living client progress report: verdict-first, freshness-stamped, degrades gracefully, no-login with optional comments","detail":"Three research lanes plus a counter-evidence lane converged: nobody pairs a beautiful no-login page with easy comments (no-login tools kill commenting, commenting tools force login); nobody pushes via WhatsApp or SMS; the 'clients ignore portals' critique is about login-gated, stale portals ('a stale portal is worse than email because the client believes it'). Design rules: a status verdict as the headline, a work timeline, coming-up-next, 'just needs you', a never-0% progress bar, end on forward motion, coral only for 'you are here', hours and internal tasks off by default, cap summaries at 5-6 items. Transparency backfires on a bad week, so the page falls back to the plan rather than an empty feed.","why":"The page's job is to relieve client anxiety, not to expose activity, and staleness shifts the burden to the owner.","how":"Auto-assemble from logged work, show an 'Updated X ago' stamp, and nudge the owner when a portal goes two weeks without an update (still unbuilt)."},{"app":"Hallalu CRM","category":"ux","session":"f256d011","source":"daily-read","title":"Deliverable card research: approvals, personal note, verb by type, invoice separate from the file","detail":"Findings: one-click Approve / Request-changes (timestamped, no login) is the most-loved feature; a real preview and a one-line personal note is the signature; the verb follows the file type (Watch, View, Download); a NEW-since-last-visit dot; the card unlocks when paid but never fuse Pay into the file's own button; avoid bare filenames and version-decoding. Also: soft completion-estimate range, book-a-call and a completion moment that gates the testimonial ask. Avoid an in-client kanban, mandatory login and mid-project NPS for a solo operator. For fixed-price work show phase progress, not raw hours.","why":"Grounds the card in evidence rather than taste.","how":"Build approvals with a real kind and a verified response (see the open Approve bug) and keep invoice actions visually separate."},{"app":"Hallalu CRM","category":"ux","session":"f256d011","source":"daily-read","title":"Ship a findable entry for every headline feature in the same release","detail":"After eight releases the user asked 'where do you access it?' for the client portal, which lived only as a topbar button and an inline card inside each client page; the assistant admitted 'you clearly had to hunt'. The Today entry added afterwards renders nothing unless a client has unread replies.","why":"A feature nobody can find does not exist, and function tests do not catch it.","how":"Add the entry to Today (always visible, with an empty-state prompt) and navigation when the feature lands, then test findability from the user's start screen."},{"app":"Hallalu CRM","category":"architecture","session":"f256d011","source":"daily-read","title":"Themes as data-attribute token blocks plus tri-state flourish overrides","detail":"Ten templates are :root[data-ptheme=X] token blocks (fonts, radius, label case and tracking, gap, divider) selected from the snapshot, with layout (data-plyt) and accent override separate. Motion, drop-cap and drifting wash have a per-theme default and a tri-state owner override (unset falls back to the theme), all inside prefers-reduced-motion. Research applied: mono only for labels and figures with neutral sans body, tabular-nums on every figure, system ui-serif/ui-rounded stacks with no webfonts, small-caps labels. 'Monochrome' themes needed an override pass on semantic status colours, and a multicolour opt-in lost to flat-theme !important rules until it used !important itself.","why":"Distinct personalities without per-theme code, and owner edits layer on top.","how":"Keep tokens in one block per theme, treat unset as inherit, and test opt-in overrides against flat themes."},{"app":"Hallalu CRM","category":"architecture","session":"f256d011","source":"daily-read","title":"Gate hash-routed pages in the route table, not only on the button that opens them","detail":"Making the portal a #/portal/<id> page meant direct URL navigation would skip the business gate that the old modal opener enforced; the assistant added 'portal' to BIZ_VIEWS so the router shows the upgrade wall.","why":"A gate that lives only on a button is bypassed by the URL.","how":"Keep gated views in one list that the router consults, and test a direct hash visit as a free user."},{"app":"Hallalu CRM","category":"workflow","session":"f256d011","source":"daily-read","title":"Before replacing a modal with a page, list every surface the modal hosted","detail":"Moving the portal from a modal to a full-page iframe preview would have removed the owner's only place to reply, hide comments and toggle requests (loadThread targets #ptThread, which only existed in the modal). It was caught pre-ship and a Replies button plus thread modal were added. A line-range sed repoint of handlers also missed two lines (pe-hours, pe-done) and was caught by re-reading.","why":"Refactors silently drop features that lived inside the thing being replaced.","how":"Grep every handler and element id the old component owned and map each to the new layout before deleting it; avoid line-number-scoped sed over handler blocks."},{"app":"Hallalu CRM","category":"workflow","session":"f256d011","source":"daily-read","title":"Route every destructive action through one confirm helper","detail":"The portal's remove buttons shipped without a confirmation for nine releases. The fix wrapped them in askDel (confirmDel with Keep it / Yes, delete and an editor re-open); Ava thread delete also had no confirm until added.","why":"Delete-confirm is a house rule, and per-handler discipline fails.","how":"Make confirmDel the only path for data-act delete handlers and grep for any remove that bypasses it before release."},{"app":"Hallalu CRM","category":"integrity","session":"f256d011","source":"daily-read","title":"One source of truth for plan prices and an amount-aware Stripe lookup_key","detail":"The Plus price existed in four hand-mirrored places and a fixed lookup_key meant Stripe's immutable Prices were reused forever. Entitlement already falls back to subscription metadata.plan, so re-minting is safe, and a deployment without pinned PRICE_* env vars auto-mints.","why":"Prices drift between display and charge, and a price change can silently not apply.","how":"Define PLANS once and have the pricing grid, billing view and stripe.js read it; keep the lookup_key keyed on amount (plan_interval_amount); if PRICE_* ids are pinned, mint new ones and update them."},{"app":"Hallalu CRM","category":"integrity","session":"f256d011","source":"daily-read","title":"Do not fake 'download all'; and pay-to-unlock must withhold the file URL until paid","detail":"Without a real bundle, 'Download everything' became an owner-set full-pack URL above per-product links. Pay-to-unlock products show 'Buy $29 - Unlocks after payment' until the owner flips a lock chip; the digest does not show whether a locked product's file URL is removed from the base64 snapshot and the stored body.","why":"A lock that is only a flag over a URL already in the link is cosmetic.","how":"Omit the file URL from the snapshot while a product is locked, confirm the build does so, and add payment-webhook unlocking when a payment provider is connected."},{"app":"Hallalu CRM","category":"copy","session":"f256d011","source":"daily-read","title":"Tell the client when a page notes their activity","detail":"The portal logs view, download, approve and pulse events (no IP, no cookies, pid as the key) and shows the owner 'viewed 3x, last seen 2h ago' and the emoji pulse, but nothing on the client's page says activity is noted.","why":"Attributing activity to an identified person without saying so is a transparency gap, whatever the storage.","how":"Add one line ('this page notes when you open it and what you download') and make the owner-visible stats optional per portal."},{"app":"Hallalu CRM","category":"copy","session":"f256d011","source":"daily-read","title":"No promissory wording and no invented value multipliers in pricing copy","detail":"Phrases such as 'free whenever you want it', 'forever' and 'always yours to export' were removed from account.js, views4.js and landing.html. A request for '20x / 4x' value multipliers was refused in favour of an honest 'Most complete' label and a sourced $80-90 comparison stack; the Free tier sits last.","why":"Promises and made-up multiples are a claims and legal risk.","how":"Review pricing and plan copy for 'forever', 'always', 'unlimited' and ratios without a source; keep comparisons to documented prices."},{"app":"Hallalu CRM","category":"ux","session":"f256d011","source":"daily-read","title":"Steppers must accept typed numbers, and every number input needs an input handler","detail":"The follow-up cadence count (+/- only) and then the posting goal both blocked a user who wanted to type 10 or 70. It happened twice, then the typed value still did nothing because the handler listened to change.","why":"Repeated, user-visible friction; the second occurrence shows it was not swept.","how":"Make every stepper a number input with + and - buttons, bind input for state and a sentence repaint, bind change for the full render, and sweep all steppers once."},{"app":"Hallalu CRM","category":"integrity","session":"f256d011","source":"daily-read","title":"Merge, never replace, when a form saves part of a stored object","detail":"Two near misses were caught before shipping: the content-calendar day save rebuilt its meta as {goal, notes} and would have dropped the day photo and linked content; sqSave read fields by id and would have thrown once the metrics grid was swapped for story fields. Ids moved into fieldsFor(type) with null guards.","why":"Partial saves that overwrite are silent data loss.","how":"Spread the existing object ({...old, ...changes}), iterate the fields actually present, and null-guard element lookups."},{"app":"Hallalu CRM","category":"integrity","session":"f256d011","source":"daily-read","title":"Replace guessed rate ranges with disclosed transaction data","detail":"The brand-deal rate calculator used guessed CPM tiers. A transaction dataset with disclosed methodology (Collabstr, n=21,000) shows paid medians of YouTube $255, Instagram $193, TikTok $186, UGC $154, 80% of deals under $300 and 2% over $1,000.","why":"Real medians are a better anchor and an honest reality check for creators.","how":"Show the medians with source and date next to the CPM maths, and keep red-flag prompts (perpetual usage, whitelisting, exclusivity, product-only, no payment terms)."},{"app":"Coco Modules","category":"architecture","session":"f256d011","source":"daily-read","title":"Extract dependency-free voice-mic and an Intl-based currency picker as modules, with one manifest","detail":"voice-mic is a floating button plus inline dictation and a raw listen loop with a graceful fallback when SpeechRecognition is missing; the floating mic was removed from the Hallalu app because it duplicated Ava's. The currency picker now derives each symbol with Intl.NumberFormat (no data table), adds a Popular group and icon search and follows light/dark.","why":"Both are needed by several apps and were being re-implemented.","how":"Publish both as modules with the same API (open/button/search), keep one modules.json that deploys to public/, and add a predeploy diff check."},{"app":"Hallalu CRM","category":"design-elevation","session":"f256d011","source":"daily-read","title":"Brand logos: clean white tile, real marks, neutral fallback","detail":"After three iterations (Clearbit, DuckDuckGo icons, a favicon over a colour monogram that the user rejected), the settled pattern is the logo on a clean white tile with a neutral grey-letter fallback, only official single-path glyphs for the seven platforms that have them, and demo brands chosen for visible logos. Hand-drawn logos from memory were rejected and an existing LOGOS table at socials.js:27-42 had been missed, so a parallel module was wasted.","why":"The user's rule is actual logos only; guessed marks look wrong.","how":"Grep the codebase before writing a new component, use simple-icons paths, and fall back to a plain initial rather than a coloured monogram."},{"app":"Hallalu CRM","category":"ux","session":"f256d011","source":"daily-read","title":"Toast conventions: past tense, three words or fewer, no punctuation, about four seconds with pause on hover, undo for destructive","detail":"Research behind the toast review (see the toast icon bug): error toasts need their own icon, hover pauses the timer, and destructive actions offer undo.","why":"Cheap polish that affects every action.","how":"Update toast() once and apply the copy convention app-wide."},{"app":"Hallalu CRM","category":"integrity","session":"f256d011","source":"daily-read","title":"Verify domain vocabulary against first-party docs before shipping it","detail":"VSCO preset codes were assumed wrong (AL is Artificial Lighting, not Analog; P is Instant film; G is Portrait; KP is Kodak Portra) until checked against VSCO's Preset Guide (20 Feb 2026). The Instagram filter list was also wrong (Hudson missing; Fade is an adjustment slider; Duet, Stitch and React are collaboration features, not effects); third-party Instagram AR effects were permanently removed on 14 Jan 2025.","why":"Plausible names from memory read as errors to the people who use them.","how":"Cite the first-party page per list, store the date, and keep unverifiable names as free text rather than as presented facts."},{"app":"Hallalu CRM","category":"architecture","session":"f256d011","source":"daily-read","title":"SSRF-guarded link unfurl: oEmbed first, Open Graph scrape second, optional Firecrawl","detail":"/api/unfurl validates URLs through safeUrl (127.0.0.1 returned bad-url in testing), uses oEmbed for YouTube, TikTok and Vimeo, falls back to OG scraping, rate-limits via tooMany, and treats Instagram, which blocks scrapers, as manual. Metrics stay OCR or manual.","why":"Auto-pull without exposing internal addresses.","how":"Keep the allowlist of schemes and block private ranges, and move the rate limit to a global store (see the open security item)."},{"app":"Hallalu CRM","category":"architecture","session":"f256d011","source":"daily-read","title":"Never cap an AI artifact generator to a fixed kind list; sanitise and sandbox instead","detail":"make_artifact was limited to an enum of eight kinds, an artificial limit. It now takes a free-form kind and an 'html' section that strips script and style, rendered in an iframe with no allow-scripts. A fragment without a doctype also rendered in quirks mode in a local preview (compatMode), which made a map screenshot look blank.","why":"Limits invented by the builder remove capability, and untrusted generated HTML needs a sandbox.","how":"Allow free-form kinds, strip scripts server and client side, sandbox without allow-scripts, and preview with a doctype."},{"app":"Coconvo","category":"integrity","session":"01a056d7","source":"dailyledger","title":"Consent-first AI meeting notes: own-mic in-browser transcription + visible banner/chime + real opt-out","detail":"Each participant transcribes only their own microphone in the browser, only while room notes are on and they have not opted out, with a persistent banner plus a chime for everyone and the speaker's display name as the label.","why":"Silent AI notetakers are now litigated and blocked by IT teams (Otter/Granola/Fireflies, 2026); invisible central capture with a fake opt-out is a legal and reputational risk.","how":"Gate per-speaker client-side transcription on a per-person opt-out flag; show a 'notes on' banner and play a chime when capture starts; never send a bot or transcribe a participant who has opted out."},{"app":"Start in Story","category":"workflow","session":"e8725186","source":"dailyledger","title":"QA a bulk AI image batch with captioned contact sheets, twelve per sheet, prompt text under each frame","detail":"For 200 per-prompt photos, a script rendered 12-up contact sheets with each image's prompt printed beneath it; every sheet was read and failures appended to a redo file with a sharper prompt, then re-baked and re-sheeted.","why":"171 of 199 passed first time and 28–30 needed a re-bake for defects only visible when image and prompt are side by side: misspelled baked-in text, merged objects, extra hands, wrong composition.","how":"Stable id per prompt, resumable baker that skips files already on disk and runs 3 at a time, qa.mjs to build sheets via headless Chrome, redo.txt of 'index|new prompt', repeat until a sheet passes; add negative prompts for text and logos."},{"app":"Coconvo","category":"ux","session":"01a056d7","source":"dailyledger","title":"Carry browser-stored settings across a domain move with a one-time handoff redirect","detail":"When the app moved from workers.dev to teams.coconvo.com, old links redirect to the new host carrying the visitor's profile and preferences, which the new origin imports once and then cleans from the URL; www redirects to the canonical host.","why":"localStorage is per origin, so a domain change silently resets every returning user's name, avatar, theme and admin keys unless they are handed over.","how":"On the old origin, package the known localStorage keys into the redirect (fragment, not query), import on first load at the new origin only if the keys are absent, strip the fragment, and verify with a real old-link visit."},{"app":"cross-cutting","category":"dx","session":"01a056d7","source":"dailyledger","title":"After a scripted block replacement, audit the removed lines with git diff -U0 before trusting it","detail":"Rebuilding two pages by slicing between markers accidentally deleted about 120 lines of shared helpers that sat inside the replaced range. They were restored from git show HEAD:file, and every removed line was then listed with 'git diff -U0 file | grep ^-' and checked as intended.","why":"An index-to-index splice passes its own assertions (both anchors exist) while silently removing unrelated code between them; syntax checks may still pass until a helper is called.","how":"Keep a copy of HEAD's file before the splice, run the removed-lines listing afterwards, and confirm each deleted line is one you meant to replace; prefer anchors that bound only the target block."},{"app":"Hopefil World","category":"architecture","session":"61020f60","source":"dailyledger","title":"Serve client-uploaded files sandboxed and accept them only through a signed, per-run upload ticket","detail":"The public Start page lets anyone attach logos, PDFs, video or audio to a run. Uploads go to R2 under the run's prefix via a short-lived HMAC ticket issued when the run is created, and every uploaded object is served with sandboxing headers so it can never execute script on the site's origin.","why":"An open upload form on the same origin as a key-gated admin area is a stored-XSS and abuse vector: an uploaded HTML or SVG file would otherwise run with the site's cookies and keys.","how":"Issue an HMAC ticket bound to the run id at creation; require it on POST /upload; store under uploads/<run>/; on GET set a sandbox Content-Security-Policy and nosniff, and never serve uploads from a path that shares scope with authenticated pages."},{"app":"CD Enterprises","category":"integrity","session":"61020f60","source":"dailyledger","title":"Label a recoloured product photo as a recolour, and show only the reviews that actually exist","detail":"The drag-to-compare figure shows the real lot photograph against a hue-shifted copy; its caption states plainly that the second colour is a recolour to show the shape, not a car in stock. The rating block shows the 4.4 score with 'from 8 reviews' and only the two review texts that are published, including the critical one with the owner's reply.","why":"A recoloured photo of a vehicle reads as available stock, and padding a reviews band beyond what exists is a fabricated-testimonial risk. Both were avoided without losing the feature.","how":"Any edited or generated product image carries a caption saying what was changed and that it is illustrative; counts and quotes in a social-proof block come only from recorded source data, with the count shown as recorded."},{"app":"cross-cutting","category":"dx","session":"e63c44d3","source":"dailyledger","title":"Before calling a feature broken, prove the test can observe it working","detail":"Three scripted checks reported working features as broken or untestable: a dispatched MouseEvent('mousemove') did not move a slider that listens for pointermove; scrollIntoView did nothing because scroll-behavior:smooth was active; headless Chrome denied clipboard permission so a copy button never confirmed. Each was a test artefact, and one of them hid a genuinely broken scroll-spy.","why":"A failing synthetic test is a claim too. Acting on these would have meant 'fixing' working code, while the real defect stayed hidden behind an untestable harness.","how":"Read the handler's actual event binding and dispatch that event type (or drive a real mouse via CDP Input.dispatchMouseEvent); set scroll-behavior:auto or use instant scrolls in scripted runs; grant clipboard permission in headless runs. Confirm the positive path once before trusting any negative result."},{"app":"cross-cutting","category":"integrity","session":"e63c44d3","source":"dailyledger","title":"Check every verbatim quote and review score a research subagent returns against its source before publishing","detail":"A market-study lane returned a customer quote that a summarising step had invented; it was caught by re-opening the source and was discarded and listed by name in the report's evidence gaps. The same study found the review-site scores were confounded: every high score belonged to a profile that pays for and solicits reviews, every very low one to an unpaid, non-soliciting profile.","why":"Quotes and star ratings are the most persuasive items in a research report and the easiest for a summariser to fabricate or misread; one invented quote discredits the whole document.","how":"Treat any quote that came through a summariser as unverified until the exact string is found on the live page; record whether each review profile is paid or soliciting beside its score; list discarded items in an evidence-gaps section instead of dropping them silently."},{"app":"Hopefil World","category":"architecture","session":"e63c44d3","source":"dailyledger","title":"Probe a site with both a plain and a browser user-agent so a bot wall is not reported as a dead site","detail":"The Worker's reachability step fetches the URL twice, once with the default agent and once with a browser user-agent, and compares. capitalsignal.com answered 406 to one and 200 to the other, and the run recorded 'user-agent block' rather than 'unreachable'.","why":"A single server-side fetch that gets 403/406 makes a healthy client site look down, and every later recon step then runs against an error page.","how":"Fetch with two agents in parallel; if only the browser agent succeeds, record a user-agent block as a finding and continue with that agent; if both fail, report unreachable."},{"app":"Hopefil World","category":"copy","session":"e63c44d3","source":"dailyledger","title":"Do not show a volume counter while the number is tiny","detail":"The homepage stat row read '2 runs recorded so far'. It was replaced with four measured outcome numbers from the one run done in depth (accessibility routes passing, contrast failures, LCP and similar).","why":"A usage counter is a brag only when it is large; a live count of 2 advertises that nobody uses the product. Measured results from one real case are both honest and more persuasive.","how":"Gate any 'N customers / runs / users' line behind a threshold and fall back to measured before/after figures from a real case until the count clears it."},{"app":"cross-cutting","category":"dx","session":"7e294579","source":"dailyledger","title":"Verify canvas editors by exporting the canvas to a PNG and probing pixels; make test clips with ffmpeg","detail":"The Browser pane screenshots a <canvas> as black, and when the pane is hidden requestAnimationFrame stops, so canvas.captureStream and MediaRecorder produce nothing and an in-page clip generator fails. Proof came from getImageData pixel probes, exporting toDataURL to a file and viewing it, and from real fixtures made with ffmpeg lavfi (testsrc/colour video plus a sine tone) fetched into the page.","why":"A black screenshot or an empty recording looks like a broken feature and invites pointless fixes; these methods give evidence that does not depend on the pane painting.","how":"Probe known coordinates with getImageData; write canvas.toDataURL() out and open the PNG; drive draw loops with setInterval rather than rAF in tests; generate short clips with `ffmpeg -f lavfi` outside the deployed assets folder; front the pane before any capture or record step."},{"app":"Pixelbake","category":"ux","session":"7e294579","source":"dailyledger","title":"Editing text on an image edits the real words in place, and every text item is a click-to-edit box","detail":"Adding a text layer over an image that already had copy just stacked new words on the old ones, which the owner flagged. Now double-clicking the words in a photo opens the in-image swap editor (erase and redraw into the pixels); overlay text and auto-captions are edited by clicking them and typing; captions render exactly as typed instead of forced uppercase.","why":"Users expect to click text and type. An 'add text' tool that cannot change existing copy, or a caption they cannot correct after speech recognition gets a word wrong, reads as broken.","how":"Route double-click by layer type (photo to in-image editor, text to inline textarea matched to the layer's font, size, colour and alignment); click a selected text item again to edit; never transform case at render time on user-editable text."},{"app":"Pixelbake","category":"design-elevation","session":"7e294579","source":"dailyledger","title":"Ground a cut-out with a shadow tinted from the backdrop and multiplied, not a flat black drop shadow","detail":"The Layers editor's subject shadow takes its colour from the backdrop underneath (sampled ambient colour, read from the live layer stack) and composites it with Multiply, alongside per-layer opacity and blend modes.","why":"The research pass on compositing found the contact shadow is the largest single realism gain for a cut-out; a neutral black shadow on a coloured or gradient backdrop is what makes a subject look pasted on.","how":"Sample the backdrop's average colour under the subject, darken it, draw the blurred silhouette with globalCompositeOperation 'multiply', then the subject; recompute when the backdrop changes (including after undo)."},{"app":"Pixelbake","category":"architecture","session":"7e294579","source":"dailyledger","title":"With snapshot-based undo, read layers from the live stack every time instead of holding object references","detail":"Undo/redo in the Layers editor restores whole-stack snapshots (each layer cloned, including its erased-pixel canvas). Before adding it, three places that used a captured `backdrop` variable were changed to read St.layers[0], and cached filter results are invalidated at every point the source pixels change.","why":"After a restore the stack holds new objects; any closure still holding the old backdrop or a cached filtered bitmap would draw stale state, giving an undo that appears to work for some properties and not others.","how":"Grep for direct references to layer objects captured at init; replace with a lookup at use time; clone pixel canvases in snapshots; record history at action boundaries (pointer up, debounced slider end), and verify undo on the hardest case (an erase) as well as an add."},{"app":"Analysis","category":"workflow","session":"c6c95d36","source":"dailyledger","title":"Before deploying the single-file reports Worker, fetch and confirm the live deployment is your own last one","detail":"Several sessions append reports to one worker.js and each deploys the whole file. Before inserting, the session ran git fetch, compared HEAD with origin/main, and read wrangler deployments list (it prints oldest first, so read the tail) to confirm the live version was its own earlier deploy.","why":"Deploying from a copy that lacks another session's report removes that report from the live site with no error.","how":"git fetch and pull first; if origin has commits you lack, merge before inserting; check the newest wrangler deployment id against your last deploy; confirm the diff is insertions only before wrangler deploy."},{"app":"Joy","category":"integrity","session":"7420082e","source":"dailyledger","title":"Guard an AI auto-responder with locked categories, a confidence line, a link allowlist and per-person caps","detail":"Joy Broadcast's reply autopilot sorts each reply into nine categories set to Automatic, Ask me or Off, with three locked: unsubscribe requests always remove the person and get no answer, out-of-office replies are ignored, complaints always wait for a human. An automatic answer is held back if confidence is under 80%, if it needs a fact not in the owner's business notes, if it contains a link that is in neither the notes nor the original email, if that person already got an automatic answer today or the thread already has three, or if the daily cap is reached. Reply text that tries to instruct the model is treated as plain content and held. Automatic answers carry Auto-Submitted: auto-replied so other responders do not answer back.","why":"An unattended model answering customer email can invent prices, send unknown links, loop with other auto-responders or obey instructions planted in a reply.","how":"Ship with the master switch off; draft only from owner-supplied notes plus the email replied to; implement each guard as a reason to queue for approval rather than a silent drop; test with a booking question, praise, 'remove me', an out-of-office, a complaint, a prompt-injection asking for a discount code and a second reply the same day."},{"app":"Joy","category":"integrity","session":"7420082e","source":"dailyledger","title":"Internal copies of campaign emails must carry no tracking or unsubscribe links","detail":"Broadcast's 'Copies to another inbox' builds each copy with its own small MIME builder: no click-tracking links, no one-click unsubscribe header or link, a visible 'Copy' banner, and for forwarded replies the original sender as Reply-To. A failed copy never blocks the real send, and copies count toward the daily cap.","why":"Forwarding the recipient's actual email to a second inbox means opening or clicking the copy can unsubscribe the real recipient or record fake clicks and sales against them.","how":"Render copies from the campaign content, not from the per-recipient frozen email; strip List-Unsubscribe and tokenised URLs; test that a two-person campaign yields exactly one copy with none of those links and that an invalid copy address is rejected."},{"app":"Joy","category":"integrity","session":"7420082e","source":"dailyledger","title":"Bulk sender safety set: block before sending with a reason, warm up, auto-brake, and keep bulk off the personal mail domain","detail":"Every Broadcast campaign passes a pre-send check that blocks unsafe sends in plain words (consent record per contact, postal address present, unsubscribe present, sending domain). Volume starts at 200 a day and grows 1.5x daily; everything pauses if bounces pass 2% or complaints pass 0.1% in a week. Sends to more than 50 people are refused while the From domain is the owner's personal inbox domain. Consent rows are append-only, enforced by database triggers, and bounce notices are read from the platform's own inbound mail.","why":"Review mining for the market study found unexplained suspension is the top complaint about email platforms (64 of 206 low-star reviews), and Gmail and Yahoo require complaints under 0.3% for bulk senders. Complaints on a shared domain also damage the owner's personal mail.","how":"Gate the send endpoint on the preflight result rather than on UI state; store warm-up and brake thresholds as settings; require a dedicated subdomain before list sends; prove the consent table rejects UPDATE and DELETE."},{"app":"cross-cutting","category":"dx","session":"7420082e","source":"dailyledger","title":"Scan the whole git history for the passcode and key patterns before the first push of a local-only repo","detail":"Joy had only ever existed as a local repo. Before creating the private GitHub remote, the session listed tracked files matching env, dev.vars, secret, pem and key, then ran git log -p --all through a grep for the live passcode value and for sk_live_, whsec_ and private-key headers.","why":"A first push publishes every historical commit at once; a secret removed from the working tree months ago still ships. Creating the repo private limits exposure but does not remove it.","how":"git ls-files | grep -iE for secret-like names; git log -p --all | grep -nE '<known secret values>|sk_live_|whsec_|BEGIN (RSA|PRIVATE)'; only then gh repo create --private --source=. --push. Do not print the secret values in the transcript."},{"app":"Joy","category":"ux","session":"ba780a05","source":"dailyledger","title":"Every count on a dashboard opens the records behind it","detail":"After the owner's demo-parity rule, Joy Broadcast gained a /api/people route (kinds sent, clicked, sales, unsub, bounce, optionally per campaign or period) and a People view. Cockpit tiles for subscribers, attributed sales and click rate, report tiles for delivered, clicked, sales, unsubscribes and bounces, per-link click counts and each list's subscriber count all open the people or orders that make up the number, and each row opens the full contact record.","why":"A total the user cannot open is unverifiable and reads as a demo. Verified example: the $178 sales tile opens the two orders ($129 and $49) with buyer, order number and email.","how":"For each KPI, add a query that returns the rows the aggregate was computed from and link the tile to it; put secondary links on their own line rather than nesting one anchor inside another; check that the opened rows sum to the tile."},{"app":"Hallalu CRM","category":"performance","session":"ba780a05","source":"dailyledger","title":"Rotate across several Overpass mirrors, fastest first, and retry busy tiles","detail":"With the main Overpass endpoint timing out even on small boxes, lz4.overpass-api.de answered a 406-shop query in 2.4 s and maps.mail.ru answered slowly. The finder now tries the fast mirror first, spreads tiles across the rest, marks heavy tiles for a later retry, and carries on in the background.","why":"A free shared API with one endpoint made a city search take about an hour and look broken.","how":"Keep an ordered mirror list; probe with a tiny bounding box when results stall; treat 429/504 as retry-later per tile rather than failing the job; record which mirror served each tile."},{"app":"Hallalu CRM","category":"ux","session":"ba780a05","source":"dailyledger","title":"When a search finds more than the requested count, keep the reachable results first","detail":"With more businesses in the area than the limit, the finder now fills the limit with rows that have a published email or at least a website before those with neither. On the same 150-row Port of Spain search, rows with an email rose from 8 to 37.","why":"A hard limit applied in arrival order returns mostly rows the user cannot act on.","how":"Rank candidates by contactability before truncating to the limit, and say in the results heading how many have an email."},{"app":"Hallalu CRM","category":"integrity","session":"ba780a05","source":"dailyledger","title":"Label every found contact with its country's cold-email rule and default unknown countries to 'Check first'","detail":"Each Lead Finder row is marked OK to email, Check first, Needs consent or Depends on the address, with the reason, for 23 researched countries. Examples: US and UK limited companies OK; UK sole traders, Canada, Ireland check first; Germany, Spain, Italy, South Africa need consent; Australia and New Zealand need consent because they ban emailing addresses collected by software, which is what the tool does; France, Belgium, Jamaica and India allow generic inboxes such as info@ but not named people. Company versus sole trader is guessed from the name suffix. The platform's do-not-email list always overrides.","why":"A lead tool that returns addresses with no legal context invites the user to send mail that is unlawful where it lands. Stating the stricter reading where sources disagree, and 'not checked' elsewhere, avoids both false permission and invented bans.","how":"Keep the rule table in code with the research date; classify generic versus named inboxes; hold back anything not marked OK unless consent is recorded; label the output as research, not legal advice."},{"app":"cross-cutting","category":"integrity","session":"ba780a05","source":"dailyledger","title":"Use Google Places only to discover a business's website; store data taken from the business's own site","detail":"Two constraints were checked before designing the finder: a Places text search returns at most 60 results (three pages of 20), so a city has to be tiled; and the Maps service terms forbid storing listing content or building a database from it, with the place ID the only field that may be kept. The design therefore uses Google (optional, key-gated) to find the website, then reads the published email from the business's own pages, with OpenStreetMap and the US NPI register as free sources.","why":"Saving Google listing fields into a CRM breaches the terms the API key is issued under, and 'get all the businesses on Google' is not achievable from one query.","how":"Split the area into tiles and query each; persist only place_id from Google; record source and date on every stored field; note that a Worker cannot open port 25, so address checking is limited to an MX lookup unless a verification service is added."},{"app":"Hallalu CRM","category":"integrity","session":"5a0287de","source":"dailyledger","title":"Rolling local backup plus a 'Recover unsaved call' banner for any long capture session","detail":"On every recognised phrase the in-progress call (transcript, typed note, duration) is written to localStorage; hashchange, beforeunload and visibility change flush it; Cancel clears it. On the next visit a banner offers Recover or Discard and restores the outcome screen.","why":"A capture that lives only in memory is lost by a refresh, an app-update prompt or forgetting to stop; the user lost a real call this way.","how":"Keep one backup key per capture type, write on each increment, flush on navigation events, clear only on explicit save or cancel, and test by injecting a backup and reloading."},{"app":"cross-cutting","category":"architecture","session":"5a0287de","source":"dailyledger","title":"Use a server-side Whisper pass on the saved recording as the second transcriber, never a second live recogniser","detail":"Keep exactly one live SpeechRecognition for the on-screen feed and run Workers AI whisper-large-v3-turbo on the recording already saved to IndexedDB for an accurate second pass; the same endpoint also serves uploaded recordings.","why":"Two live recognisers compete for one microphone in Chrome and silenced the visible transcript; a post-hoc pass adds redundancy without touching the mic.","how":"Record with MediaRecorder, store the blob, POST base64 audio to a /api/transcribe Worker route, then feed the text into the same recap pipeline."},{"app":"cross-cutting","category":"dx","session":"5a0287de","source":"dailyledger","title":"Test mic-dependent flows without a mic: a result-semantics simulator plus synthesized speech","detail":"The Browser pane rejects getUserMedia with NotAllowedError. The accumulation logic was proven with a Node model of webkitSpeechRecognition (per-session cumulative results, resultIndex, restarts), and the transcription endpoint with a clip made by macOS say and afconvert (8 kHz mono WAV keeps the payload small).","why":"Otherwise speech features ship verified only by reading the code, which is how a dual-recogniser regression reached a real call.","how":"Simulate old versus new logic across restarts in Node; generate audio with say -o x.aiff and afconvert -f WAVE -d LEI16@8000 -c 1; drive the real button by injecting the blob into IndexedDB; state plainly which real-device step remains."},{"app":"HallaluSocial","category":"dx","session":"6a0014e0","source":"dailyledger","title":"Build a local stand-in for third-party platforms so real OAuth and verification code runs end to end before any keys exist","detail":"A small mock server mimics each platform's documented consent, token, follow-check and webhook responses; the Worker points at it through a MOCK_BASE dev var, and an e2e script walks every verifier, the unlock and the anti-cheat rules (56 checks on the first run, 108 later).","why":"Seven providers each need developer keys and app review; without a stand-in none of the sign-in or check code would have been executed before launch.","how":"Keep provider base URLs overridable, mirror the documented response shapes exactly, randomise test identities per run, and label every result as 'tested against the stand-in only' until one real-account test passes."},{"app":"HallaluSocial","category":"integrity","session":"6a0014e0","source":"dailyledger","title":"Label every proof with how it was proven: Verified, Corroborated, Attested or Reviewed","detail":"Each step carries a trust badge reflecting the actual mechanism: API-checked (Verified), indirect evidence such as TikTok following-count rising inside the window (Corroborated), self-confirmed (Attested), or creator-approved upload (Reviewed). A later follower-export match adds a second 'Confirmed' badge without breaking the receipt.","why":"Competitors blur the difference and users assume giveaways are fake; honest tiers keep the product's claims true where a platform has no follow API.","how":"Store the trust level on the event at write time, render it everywhere the step appears, and never upgrade a label without new evidence."},{"app":"HallaluSocial","category":"architecture","session":"6a0014e0","source":"dailyledger","title":"Anchor signed records to Bitcoin with OpenTimestamps on a cron instead of asking users to trust the server's signature","detail":"An hourly scheduled handler hashes new receipts into one digest, posts it to a public OpenTimestamps calendar, stores the proof, and the public receipt page checks it and offers the proof files. Verified against the real calendar and shown as 'Anchored in Bitcoin'.","why":"Gives the public, un-editable timestamp that blockchain quest tools offered, with no wallet, gas or crypto UI.","how":"Batch with a bounded limit per run, call the calendar directly from the Worker, keep anchors in their own append-only table, and re-verify client-side on the receipt page."},{"app":"HallaluSocial","category":"conversion","session":"6a0014e0","source":"dailyledger","title":"In-app browser escape sheet with the right exit per app and platform","detail":"When the page loads inside Instagram, TikTok, Facebook, Snapchat or LinkedIn's built-in browser it shows that app's own steps: on Android an 'Open in Chrome' intent button fired only on tap, on iPhone the app-specific menu path, an 'Open in Safari' button only for Facebook (it fails in TikTok), plus Copy link and Continue here (remembered for the visit).","why":"Fans are not signed in inside in-app browsers and Google sign-in does not work there, which is where cross-platform journeys leak.","how":"Detect by user agent, build the intent URL from the page's own scheme, always show manual steps beneath any button, and test each app and OS combination by emulated user agent."},{"app":"HallaluSocial","category":"integrity","session":"6a0014e0","source":"dailyledger","title":"Ship experiments with sample sizes, a significance read and a 'how many you need' guide","detail":"The head-start A/B card shows each group's completions and n, the difference, a p-value, and a rule of thumb (about 400 per group to detect a 10-point difference). The UI output was checked against a hand calculation (26/40 vs 17/40, p = 0.044). Fans are assigned at page load so the control group never sees a control that does nothing.","why":"A bare 'A beat B' on a few dozen visitors invites wrong decisions.","how":"Assign server-side at load, store the variant with the run, compute a two-proportion test, and verify the displayed numbers by hand once before shipping."},{"app":"Joy","category":"integrity","session":"6bfbafe5","source":"dailyledger","title":"Judge A/B winners on clicks, replies and sales, never opens, and show the confidence","detail":"Joy Broadcast sends two subjects or two whole designs to a random slice, waits a chosen number of hours, then sends the leader to the rest. Opens are deliberately not tracked or used; the report shows both arms side by side with a confidence read and typical click-rate benchmarks.","why":"Apple Mail privacy pre-fetching inflates opens (research in the session put it at roughly 55 to 60 percent of opens), so open-rate winners are noise.","how":"Record variant per send, attribute clicks through the tracker, decide on the cron after the window, and state the confidence instead of a bare winner."},{"app":"Joy","category":"integrity","session":"6bfbafe5","source":"dailyledger","title":"Email-in to template: hold anything from an unknown sender for approval","detail":"Forwarding an email to templates@ has Ava rebuild it as an editable template. Senders not on the trusted list land as 'pending' and need approval in Settings; imported links are cleared so the owner adds their own.","why":"An open inbound address would let strangers fill the template library or plant links.","how":"Keep an allow-list in settings, store the sender and a pending status on the row, and strip outbound links on import. Verified with a real SMTP message to the live address."},{"app":"cross-cutting","category":"dx","session":"6bfbafe5","source":"dailyledger","title":"Check the host app's CSP before loading a shared module from another origin; vendor it when script-src is self-only","detail":"Before adding emoji-picker and goal-celebrate from the modules registry, Broadcast's _headers CSP was read: it only allows its own scripts, so the two modules were copied into the shared maker's vendor folder, and their z-index was checked against the designer's overlay.","why":"A cross-origin script tag would have worked in dev assumptions and been blocked silently in production.","how":"Read _headers or the Worker's CSP first; if script-src is 'self', vendor the file through the build copy list and note the source version."},{"app":"Start in Story","category":"integrity","session":"9440fcf5","source":"dailyledger","title":"Calibrate a face-identity score against impostors and owner judgements, gate on face quality, and show bands instead of percentages","detail":"Score every candidate against owner-approved reference photos; refuse to score faces that are too small, turned or blurred; seed 25 lookalike 'impostor' women and collect the owner's same/different calls; set thresholds from that evidence; show Locked / Close / Drifted rather than a percentage. Cross-check the browser scorer against an offline Node scorer (here they agreed within 0.024).","why":"With starting thresholds the closest stranger scored 0.337-0.346, right on the 0.34 Close/Drifted line, so an uncalibrated cut-off can label a different woman 'Close'. A bare percentage also implies precision the model does not have.","how":"Keep reference, candidate and impostor sets per character; store every score and human call append-only; recompute thresholds from the impostor maximum and the human labels; run the same pipeline in two runtimes and compare before trusting either."},{"app":"Postplan","category":"ux","session":"53323280","source":"dailyledger","title":"Set a habit streak to the frequency people really act at: weekly with a repair, not daily","detail":"For a posting tool, make the streak weekly and forgiving (one repair), and make the daily action something lighter than publishing: a Today view with the post due, a draft to finish, an idea of the day and comments to answer.","why":"The study found 93.5% of Instagram accounts (28M sampled) post once a week or less, so a daily posting streak would break for most people in week one. Duolingo's published experiments attribute streak gains to a low daily bar and forgiveness. Among rivals only Buffer has a streak, and it is weekly.","how":"Before adding any streak, find the real base rate of the action from a primary dataset, set the streak period at or above it, add a repair, and pick a smaller daily verb for the home screen."},{"app":"Divorce Rates Atlas","category":"integrity","session":"fbad84e5","source":"dailyledger","title":"A within-year ratio is not a lifetime probability: never label 'divorces per 100 marriages' as 'of marriages end in divorce'","detail":"While relabelling, the KPI caption was first written as '% of marriages end in divorce' and corrected in the same pass to 'per 100 marriages (this year's divorces ÷ this year's marriages)'. The app now states that 74 per 100 is not '74% of marriages will end in divorce'.","why":"The cohort-probability reading is the single most common misuse of divorce statistics; shipping it would have been a false claim on the headline number.","how":"For any ratio of two same-year flows, write the denominator into the label and add one 'what this is not' sentence next to the headline figure."},{"app":"CRM Dealership","category":"integrity","session":"5f29f581","source":"dailyledger","title":"Ship regulatory numbers as a versioned rate pack where every line carries its source and a confirmed/unconfirmed flag","detail":"The Trinidad duty engine stores duty, VAT, MVT, levy, exemptions and the age limit as a versioned 'TT 2026' pack. Each line has a source and a confirmed flag; unconfirmed lines (MVT per-cc schedule, levy amount, hybrid ≤1599cc exemption) are shown as such and editable in Settings; each save creates a new version.","why":"Tax and import rules change (the age limit moved from 3 to 8 years during the research) and some figures could not be verified; hard-coding them would present guesses as law in a tool that prices cars.","how":"Model rates as data with {value, source, confirmed, version}; surface the flag in the UI and on the computed breakdown; never overwrite a pack, add a version."},{"app":"CRM Dealership","category":"architecture","session":"5f29f581","source":"dailyledger","title":"In-house finance module: never take custody of funds — record instalments, let the dealer stay merchant of record","detail":"The business-case research found the main licensing gate for a dealer-financing feature is money transmission. The MVP's BHPH-lite ledger therefore only schedules, records and receipts payments and sends reminders; it moves no money.","why":"Holding or routing customer funds turns the SaaS into a money transmitter in most jurisdictions (and UK in-house finance needs FCA permission); a ledger does not.","how":"Keep payments as records against a schedule; if card payments are added use connected accounts where the dealer is merchant of record; gate finance features per country."},{"app":"cross-cutting","category":"integrity","session":"5f29f581","source":"dailyledger","title":"Size a market as a reconciled range and drop broad-scope outliers before quoting a TAM","detail":"Six analyst estimates for dealership-management software clustered at $4–9B, while three others quoted $17–40B because they include hardware, services and non-auto dealers. The report quotes the range with a $5–6B midpoint, states why the larger figures are excluded, and derives SAM/SOM bottom-up from rooftop counts × ARPU.","why":"A single headline TAM from the widest-scope report inflates the opportunity several-fold and collapses under the first investor or client question.","how":"Collect ≥5 estimates, record each one's scope, cluster like-for-like, name the outliers and their scope difference, then build SAM/SOM from counts × price rather than a percentage of TAM."},{"app":"Hallalu CRM","category":"ux","session":"6e3bc715","source":"dailyledger","title":"Put a new admin feature where the request named it: top-level nav item plus a direct hash link, not three tabs deep","detail":"Wisdom Marketing first shipped at Socials → Wisdom Admin → Wisdom Marketing. The owner, who had asked for it in 'Hallalu CRM admin', reported 'not seeing it in my crm'. It was then given its own sidebar item under Account (admins only), a button on the Admin page and a direct link /app#/marketing.","why":"A feature the owner cannot find reads as a failed deploy and cost three debugging round-trips that were partly about navigation rather than caching.","how":"When a request names a location, add the entry point there; give every new surface a deep link and state the exact click path and URL in the hand-off message."},{"app":"Wedding Woosh","category":"architecture","session":"278fbfda","source":"dailyledger","title":"Keep every shipped version playable and never rename save keys, so progress follows the player across versions","detail":"tools/archive.sh vN \"label\" freezes the current build with its own art under /archive/vN/ and rebuilds an archive index; archives are never overwritten. All versions read the same ww.* localStorage keys, so weddings, upgrades and budget carry over between v1, v1-1, v2 and v3.","why":"The owner compares versions side by side and asked that progress carry over; without frozen builds a regression cannot be shown, and a renamed key silently resets a player.","how":"Archive before each upgrade as a self-contained static copy; treat storage key names as a public contract; add new fields with defaults rather than new keys."},{"app":"cross-cutting","category":"dx","session":"98ff1882","source":"dailyledger","title":"Moving a domain's mail onto Cloudflare: enable sending first, expect routing to be blocked by the old MX, and know wrangler's login cannot edit DNS","detail":"For hallalu.com: `wrangler email sending enable` worked immediately and added DKIM, SPF and DMARC p=reject; `wrangler email routing enable` refused while the Google MX existed; the wrangler OAuth login has no DNS scope (`wrangler login --scopes-list` shows none), so the MX could not be read or deleted from the CLI and the owner had to delete it in the dashboard. A background watcher polled the authoritative nameserver and enabled routing when the MX disappeared. Two wrangler config files existed and the one under ~/Library/Preferences held a stale token.","why":"The switch has an unavoidable manual step and a side effect: once p=reject is published, mail still sent as the domain from the old provider (which had no DKIM for it) is rejected, and inbound keeps going to the old provider until the MX changes.","how":"Back up public DNS with dig first; pre-stage the catch-all rule; enable sending and prove DKIM/DMARC pass with a test; tell the owner exactly which MX to delete and what stops working; poll the authoritative NS, then enable routing and prove receive with a real message."},{"app":"Start in Story","category":"architecture","session":"ea78c819","source":"dailyledger","title":"Meter paid AI with reserve-then-refund credits, and prove it with a failure-injection harness","detail":"Credits are reserved before any model call and refunded for every failed or partially failed item; identity shots cost 2; monthly and daily caps and tier sizes are Worker vars, plan is read from the subscription check and cached 15 min; a /v1/usage endpoint feeds an 'N left' display. An 11-check Node harness ran the real engine code with AI calls forced to fail fully, fail partway and succeed.","why":"The engine previously checked sign-in only, so failures either cost the user or the owner. Reserve-first closes the race where parallel requests overspend, and refund-on-failure keeps 'failed generations are free' true.","how":"Add usage + plan tables, wrap each paid route in reserve -> run -> refund(failed count), keep limits in env vars, and test with a stubbed AI binding that fails 0/some/all items plus one cheap real run locally with tiny limits."},{"app":"Start in Story","category":"conversion","session":"ea78c819","source":"dailyledger","title":"Capture first-touch attribution once and attach it at sign-up","detail":"On the first visit the app stores UTM tags, ?ref= or the referrer; a later visit does not overwrite it; the value is attached to the account when the user signs up.","why":"Launch relies on many creators, clippers and ads; without first-touch capture none of them can be measured separately.","how":"A small attribution module run from main.tsx that writes once to storage, plus one line in the sign-up call; verify in the browser that a second visit with different params leaves the first value intact."},{"app":"cross-cutting","category":"workflow","session":"ea78c819","source":"dailyledger","title":"Before building on a file a co-editing session hands over, diff it against the deployed Worker code","detail":"When another session passed over worker.js, the deployed script was fetched and compared with the edit base to confirm the on-disk file was 'their deployed version plus my additions'. Later a version-id mismatch between sessions was resolved by listing deployments and re-checking the live code still contained the new function.","why":"With two sessions deploying the same Worker, a stale base silently reverts the other session's work on the next deploy.","how":"Fetch the live script (Cloudflare workers_get_worker_code or wrangler versions view), compare against your base, and after any peer deploy re-run wrangler deployments list and grep the live code for your change."},{"app":"Start in Story","category":"integrity","session":"c009ca9b","source":"dailyledger","title":"Only print an identity % that was measured on that exact image; no chip when the face is hidden or strongly expressive","detail":"Every score chip in the creative set is the app's own face-api score for that file against the original. Pieces where the face is hidden, or where a frown/hand-at-temple pose scored 55%, carry no chip; the proof slide shows the real spread including the 42% reject.","why":"A score copied from a different bake, or from a generator's own 8-9/10 self-rating, would make the consistency claim false on the ad itself.","how":"Run each final PNG through a local Face Match page that loads the app's own models and thresholds, store the number in the spec next to the item, and render the chip only from that field."},{"app":"Pixelbake","category":"workflow","session":"c009ca9b","source":"dailyledger","title":"Keep expression and angle close to the anchor, and never feed a sub-locked bake back in as a reference","detail":"Against one anchor photo, calm front-on edits scored 80-96%, a big open smile 31%, a frustrated pose in a new scene 31-46%. Adding the best drifted result as a third reference held the score at about 62%; chaining small edits from it reached only 55-59%.","why":"Expression and pose move a face-embedding score as much as a real identity change, and a drifted reference teaches the model the drift.","how":"Change one thing per edit from a locked image, bake 3 variations, keep only locked ones as future references, and treat expressive scenes as unscored. Root-cause attribution for the third-reference effect is the assistant's reading of the scores, not a controlled test."},{"app":"Postfactory","category":"architecture","session":"9bbd641a","source":"dailyledger","title":"Split one big JSON-mode analysis into two focused calls (hooks, then blueprint)","detail":"A single Llama 3.3 JSON-mode call returning hooks, beats, CTAs, lifecycle and a blueprint kept returning a short shot list and script even after stricter prompt minimums. Splitting into hooks -> blueprint gave complete output.","why":"Small models under JSON mode truncate the last, largest field; tightening the prompt did not fix it.","how":"Run the extraction pass first, then pass its result into a second call that only writes the blueprint; log each model call's cost separately."},{"app":"Postfactory","category":"workflow","session":"9bbd641a","source":"dailyledger","title":"Read TikTok's public page JSON for free timestamped captions and full stats before paying for ASR","detail":"Logged-out, a TikTok video page's embedded JSON exposes subtitleInfos (a VTT URL with ASR captions) plus plays, likes, comments, shares and saves (collectCount). Music-only clips have no caption track. Instagram returns nothing without a login, so it is handled from a saved file.","why":"Native captions made the transcript step free (45 timed words on the test clip) and saves are not available from most tools.","how":"curl the video URL with a desktop user agent, parse subtitleInfos and the stats block, fall back to Whisper on 16 kHz mono audio when there is no caption track; keep downloads in the local CLI, never logged in."},{"app":"Loopsong","category":"ux","session":"0cc7f71a","source":"dailyledger","title":"Show the real wake-lock state and re-acquire it when the tab becomes visible","detail":"A chip shows whether the Screen Wake Lock is actually held; the browser drops it when the tab is hidden, so the app takes it back on return, and the copy says plainly that closing a laptop lid still sleeps.","why":"A keep-awake promise that silently lapses is worse than none for an 8-hour playback app.","how":"Request the lock on play, listen for its release event and for visibilitychange, update the chip from the lock object not from intent; test via CDP because the Browser pane reports the page as hidden."},{"app":"Analysis","category":"integrity","session":"0cc7f71a","source":"dailyledger","title":"Audit a published report against the research section list, and add a companion entry rather than editing","detail":"After publishing, the report was checked against REPORT.md and found to omit segments, ranked requests, switching reasons, the full competitor list and search signals. Because the archive is append-only, a 'Full Record' companion report was added and the first left untouched.","why":"'Nothing dropped' was claimed before it was checked; the short report alone would have lost most of the evidence.","how":"List the research file's headings, tick each against the report blocks before calling it done, and ship gaps as a linked companion slug."},{"app":"Fullfill","category":"performance","session":"819356c7","source":"dailyledger","title":"Ask the vision model about one cell per table column and copy the answer down the rows","detail":"For a ruled table, only the top cell of each column is sent to the model as a candidate; the rows below inherit its label with a row number. A 30-cell table became 6 questions.","why":"Cut tokens and latency and removed the row-by-row mislabelling; with the example-row fix it took a scanned form to 45 of 45 in about 10 s for two pages.","how":"Group detected boxes into columns (3 or more aligned cells), send the header-adjacent cell only, then fan the label out as 'Header (row N)'."},{"app":"Evertrue","category":"copy","session":"fbb12fd5","source":"dailyledger","title":"Spell the month and four-digit year in labels: 'Sept 26' was read as a date","detail":"A form label built from a short month label rendered 'New listings live in Sept 26', which the owner could not parse. It became 'New listings to publish in October 2026' with a one-line monthly-goal versus daily-challenge explainer.","why":"Abbreviated month plus two-digit year is indistinguishable from day-of-month; the owner reported not knowing what to type.","how":"Use a long-month, full-year formatter for any label that names a period, and say the action in the label."},{"app":"cross-cutting","category":"conversion","session":"5bd3b322","source":"dailyledger","title":"Ship an age-matched cast variant beside the young cast when the audience is 35 to 60","detail":"The brief asked for young models throughout. For the Gen X piece the run produced cast A (a model of the audience's age) and cast B (young) with identical copy, to be tested.","why":"Research in the session found nothing showing young models winning with women 35 to 60, and AARP stated-intent data favouring advertisers who show their age. Both were graded SIGNAL, not proof of a sales lift.","how":"Keep the owner's requested cast, add one same-copy variant matched to the segment's age, and mark it as an A/B test rather than a decision."},{"app":"cross-cutting","category":"dx","session":"fba7dfe5","source":"dailyledger","title":"Full-disk triage: read df first, skip du on a thrashing disk, and check simulator devices","detail":"On a 100% full Mac, du over the home directory stalled and timed out; df answers instantly. Two iOS Simulator devices held 2.2 GB and 2.1 GB of simulated-OS logs and caches around a 27 MB app.","why":"Three sessions lost minutes to measurement commands that could not finish, and the largest safe reclaim after caches was not in any cache directory.","how":"df for the number; delete known regenerable caches by path without sizing them first; size CoreSimulator/Devices; hand the owner `xcrun simctl erase <udid>` since erasing is theirs to approve; never treat ~/Pictures' reported size as real."},{"app":"Pixelbake","category":"architecture","session":"68db738b","source":"dailyledger","title":"Background removal on Cloudflare: use the Images binding segment:'foreground' (BiRefNet), because Workers AI has no segmentation model","detail":"Workers AI lists no matting or segmentation model. The Images binding transform({ segment: 'foreground' }) runs BiRefNet first-party, returned a true-alpha PNG in about 1.5 s on four real photos (two portraits, a fluffy dog, a glass bottle), and needs no AI Gateway billing.","why":"It avoids a third-party remover and keeps hair strands; the first reflex (look for a Workers AI model) finds nothing and wastes time.","how":"env.IMAGES.input(bytes).transform({ segment: 'foreground' }) to PNG; file the result as a versioned edit tagged cutout; charge only on success; composite blur, colour or library-image backgrounds from the same matte."},{"app":"Pixelbake","category":"integrity","session":"68db738b","source":"dailyledger","title":"Single-pass BiRefNet drops low-contrast parts (paws under grass); fuse three passes and guide the edge with the photo","detail":"One pass removed the bottoms of a dog's paws wherever grass blades crossed them and kept the grass. The new default runs the frame, its mirror and a 2x crop of the subject box, keeps any pixel a pass found, then applies a guided filter so the uncertain band snaps to real fur edges. On the same photo 1,312 pixels were recovered exactly at the paws, while the glass bottle and portrait masks barely changed.","why":"The owner compared it with Canva; the accuracy gain had to come from driving the available model harder, at the same 1 credit.","how":"Decode the PNG mattes inside the Worker (src/matte.js), union the three alphas, guided-filter against the source luminance; expect about 5.7 s on a 1024 square instead of 1.5 s, so keep a --fast single-pass option and return recovered-pixel stats so the gain is measurable."},{"app":"Hallalu CRM","category":"ux","session":"23c352e6","source":"dailyledger","title":"Make a multi-minute client-side job resumable: cache finished pieces by a hash of the input and warn before the tab closes","detail":"A 5-hour recording takes 15-25 minutes to transcribe in about 10-minute pieces, three at a time. Finished pieces are now cached on the device under a SHA-256 fingerprint of the recording, a beforeunload warning fires while a job runs, progress reads 'part 3 of 30', and the cache is cleared when the job completes.","why":"Closing the tab part-way used to throw all the work away. Proven by reloading after two pieces: the rerun started at 2 of 6.","how":"Fingerprint the blob, store each piece's text keyed by fingerprint and index, skip cached indexes on rerun, register beforeunload only while running, delete the cache entry on success."},{"app":"Hallalu CRM","category":"workflow","session":"23c352e6","source":"dailyledger","title":"Test long-audio transcription with a synthetic recording of numbered items, then count them","detail":"A 58-minute spoken test file containing 420 numbered items was generated with the macOS say command and converted to M4A, WebM, MP3, Ogg and WAV. Pass means all 420 come back, none missing and none out of order. The same file, cut to 23:12, reproduced the owner's exact failing case.","why":"Reading a long transcript by eye cannot show a dropped or reordered chunk; a countable sequence does, and it exposed both the empty-M4A-piece bug and the silent 503 loss.","how":"say -o long.aiff with a numbered word list, ffmpeg to each container, run the real pipeline, regex the numbers out of the result and compare with the expected sequence."},{"app":"cross-cutting","category":"integrity","session":"bab8f679","source":"dailyledger","title":"Scan for hard-coded keys before any bulk upload of source, reporting only path and key type, and expect base64 false positives","detail":"Before 65 folders (about 6,000 files) were uploaded to a code host, every candidate file was scanned for live key patterns (Stripe live and webhook keys, AWS, Google and similar). The first scan would have printed matches, so it was rerun to print only the file path and the kind of key. The four hits were 'AIza' substrings inside base64-embedded images in composed HTML, not keys.","why":"An exclude list for .env, .dev.vars, pepper, access-code and token files does not catch a key pasted into source, and echoing a match into tool output leaks the secret a second time.","how":"Regex per provider over the exact upload set, output path plus pattern name only, then inspect each hit's surrounding context with the value masked; data-URI images are the usual false positive."},{"app":"Joy","category":"dx","session":"9de37912","source":"dailyledger","title":"Return 400 for a missing required query parameter instead of an empty 200 list","detail":"During live verification of Joy Cloud, the share-activity endpoint was called with ?id= when it reads ?token=. It answered 200 with events: [] while the link's counters showed 1 view and 1 download, which looked like a tracking bug. A D1 check then showed zero event rows only because purging the test file had already cascaded its link events away. It took a source read and a fresh throwaway share to prove tracking worked.","why":"An empty success for a malformed request reads as 'no data' and sends the investigator after a bug that does not exist.","how":"Validate the required parameter first and reply 400 naming it; when checking counters against event rows, read the events before deleting the file that owns them."},{"app":"Joy","category":"workflow","session":"9de37912","source":"dailyledger","title":"Prove a passcode-gated live app end to end with a one-time ticket and a uniquely tokened file, then leave no trace","detail":"Joy Cloud's signed-in loop had only been proven locally. The session inserted a one-time, 10-minute ticket row into the app's own ticket table through wrangler D1, opened /sso?t=<ticket> to get a real session without typing the passcode, uploaded a 112-byte file containing a random token, shared it, downloaded it from the public share origin and compared bytes, read the owner's activity, revoked the link (download then 404, friendly page), and purged the file so the drive was exactly as found.","why":"It exercises the real production endpoints across both Workers without the agent handling the owner's passcode, and the unique token makes 'the bytes match' a fact.","how":"Reuse the app's existing ticket mechanism; random hex ticket with a short expiry; unique token in the test payload; screenshot each step; revoke, trash and purge at the end and confirm zero test files remain."},{"app":"Joy","category":"integrity","session":"07a38c70","source":"dailyledger","title":"Forgot-passcode by emailed code: the limits and side effects that made it safe on a shared passcode","detail":"One shared passcode guards Joy Mail, Cloud and Broadcast. Recovery emails a 6-digit code that works once, lasts 15 minutes, allows 5 tries and at most 3 sends per 15 minutes; a new send retires the previous code. A reset signs every device out of all three apps and emails a 'passcode changed' notice. Saving a recovery address sends a test email first and tells the old address about the change. The recovery inbox must be outside the system being recovered. After the first reset the new passcode lives as a salted hash in the database and the original Worker secret no longer applies.","why":"A short numeric passcode plus an emailed code is only as strong as its throttles, and a recovery address inside the locked mailbox is unreadable exactly when it is needed.","how":"One recovery module on the auth owner (Mail) with the other apps forwarding to it; refuse with a clear message when no recovery address is saved; prove wrong code, retired code, reused ticket, old passcode, old session and a fourth send are all refused. In wrangler dev the code can be read from the simulated .eml under .wrangler/tmp/email."},{"app":"Hallalu CRM","category":"integrity","session":"eaa7bb8e","source":"dailyledger","title":"Let a logged time entry be corrected after saving, but keep the original figure and mark the row 'adjusted'","detail":"A work-log timer left running overstated a session. Each logged row now has a Time button: type the hours and minutes actually worked, or set the real end time and subtract breaks, with a preview of exactly what the row will read. The original timed figure stays on the entry, the row shows an 'adjusted' tag, the change is written to the activity feed, and day, week and analysis totals recompute. Because the recorded pause pattern can no longer be true, the strip collapses to one work stretch plus one break block rather than a stretched copy.","why":"A log that cannot be corrected is wrong for ever, and one that is silently rewritten cannot be trusted for billing.","how":"Store originalMs alongside the edited value, flag the entry, derive all totals from the edited value, and never scale old interval data to fit a new duration."},{"app":"Aprizely","category":"architecture","session":"43a0a72d","source":"dailyledger","title":"Session history reachable from a shared public board must be an owner-only endpoint, not part of the public board payload","detail":"Every live board gained a Past sessions drawer listing all boards for the project or for every project (280 sessions across 52 projects). The list comes from a separate endpoint that requires the owner's signed-in cookie: an anonymous request gets 401 and the drawer shows a sign-in prompt with a same-origin return path to the board.","why":"Board links are shared with clients. Adding history to the public board response would expose every other project name and session title to anyone holding one link.","how":"Keep the public /live/<id> payload to that single board; serve history from a cookie-checked route; accept only same-origin paths in the post-sign-in redirect; test the anonymous 401 explicitly."}]};
